window.SDT_LESSONS=window.SDT_LESSONS||{};window.SDT_LESSONS["I1"]={"deck":"I1","slides":[{"p":1,"title":"IoT 스마트홈 표지","terms":["Internet of Things","Smart Home"],"pass1":[{"kind":"say","lines":["첫 장은 과목 표지예요. 과목 이름은 IoT 스마트홈이에요.","IoT는 **사물인터넷(Internet of Things)**의 줄임말이에요.","전등, 에어컨 같은 집 안 물건이 인터넷으로 서로 이야기하는 기술이에요.","그런 물건으로 채운 집이 **스마트홈(Smart Home)**이에요."]}],"pass2":[{"kind":"points","head":"이 과목 내내 붙잡을 한 문장","items":["센서가 느끼고, 네트워크가 나르고, 허브와 플랫폼이 판단하고, 기기가 움직여요.","네 동작을 줄이면 감지, 전달, 판단, 실행이에요.","슬라이드가 무엇을 말하든 이 네 칸 중 어디 이야기인지 찾아보세요.","**사물인터넷(Internet of Things)**은 이 네 칸을 인터넷으로 잇는 기술이에요."]}],"pass3":[{"kind":"look","walked":1}],"pass4":[],"pass5":[],"walk":{"head":{"b":[0.0696,0.3656,0.2577,0.1007],"c":[0.0567,0.3496,0.2835,0.1327],"r":3.0214,"img":"img/I1/walk/p001_h.jpg"},"parts":[{"b":[0.071,0.493,0.214,0.051],"c":[0.059,0.4635,0.238,0.11],"r":3.0599,"img":"img/I1/walk/p001_30_01.jpg","say":"교과목 번호는 07586이에요. 수강 신청과 성적표에서 이 번호로 찾아요."},{"b":[0.071,0.554,0.35,0.053],"c":[0.0535,0.5255,0.385,0.11],"r":4.9498,"img":"img/I1/walk/p001_30_02.jpg","say":"전공선택 과목이고 3학점, 일주일에 3시간 수업이에요."},{"b":[0.071,0.616,0.257,0.051],"c":[0.0582,0.5865,0.2827,0.11],"r":3.6346,"img":"img/I1/walk/p001_30_03.jpg","say":"김철재, 공정식 두 교수님이 나눠 맡아요. 누가 몇 주차인지는 3쪽 계획표에 있어요."}]}},{"p":2,"title":"교수소개: 김철재","terms":["Smart Home"],"pass1":[{"kind":"say","lines":["두 번째 장은 김철재 교수님 소개예요.","교수님은 스마트홈 자격증을 설계하고, 그 시험 문제를 내는 전문가 모임에 있어요.","그래서 수업 시험도 그 자격 시험과 닮았을 가능성이 커요."]}],"pass2":[{"kind":"points","head":"카드 네 장을 한 줄씩","items":["자격을 설계하는 사람: 정보통신 자격을 연구하고 기획하는 협회에서 일해요.","직업을 만든 사람: **스마트홈(Smart Home)**을 관리하는 직업이 무슨 일을 하는지 처음 정리했어요.","전문가 네트워크: 시험 문제를 내고, 검토하고, 채점하는 전문위원이에요.","국내 최초 설계자: 이 강의 체계를 처음 만들었어요."]}],"pass3":[{"kind":"look","walked":1}],"pass4":[{"kind":"points","head":"그래서 시험은 이런 모양일 수 있어요","items":["교수님이 출제위원으로 있는 시험은 국가공인 지능형홈관리사예요.","필기는 4지 택일 40문항을 40분에 풀어요.","영역은 지능형홈 개론, 지능형홈 네트워크, 지능형홈 기기 세 가지예요.","\"가장 적절한 것은?\", \"옳지 않은 것은?\" 모양이 많아요."]},{"kind":"check","q":"김철재 교수님 소개 카드에 나온 경력으로 알맞은 것은?","choices":["지능형홈관리사 출제, 감수, 채점 전문위원","건설사 아파트 현장소장","가전 제조사 앱 개발자","통신사 영업팀장"],"a":0,"why":"세 번째 카드예요. 시험을 만드는 사람이 가르치니, 수업 시험도 4지 택일 모양이 많을 거라고 예상해요."}],"pass5":[{"kind":"points","head":"실기 시험은 이렇게 생겼어요 (실기 가이드북 2권, 검정 개요)","items":["실기는 지능형홈 실무 15문항을 40분에 풀어요.","단답, 서술형 4점짜리 5문항과 작업, 분석형 8점짜리 10문항이에요.","실기가 끝나면 쉬는 시간 없이 바로 필기를 봐요.","합격하려면 필기와 실기 각각 40점 이상, 합계 평균 60점 이상이어야 해요."]}],"walk":{"head":{"b":[0.0673,0.1116,0.1981,0.0666],"c":[0.0553,0.0956,0.2221,0.0986],"r":3.1856,"img":"img/I1/walk/p002_h.jpg"},"parts":[{"b":[0.077,0.192,0.203,0.325],"c":[0.065,0.1758,0.227,0.3575],"r":0.898,"img":"img/I1/walk/p002_30_01.jpg","say":"ICQA는 한국정보통신자격협회예요. 신기술 분야 자격을 연구, 기획하고 교수님은 전략기획팀장이에요."},{"b":[0.293,0.192,0.202,0.325],"c":[0.281,0.1758,0.226,0.3575],"r":0.894,"img":"img/I1/walk/p002_30_02.jpg","say":"5년 전 직무분석으로 스마트홈관리사 직무체계를 정의했어요. 세상에 없던 직업을 만든 작업이에요."},{"b":[0.507,0.192,0.202,0.325],"c":[0.495,0.1758,0.226,0.3575],"r":0.894,"img":"img/I1/walk/p002_30_03.jpg","say":"100명이 넘는 전문가와 함께 출제, 감수, 채점을 맡아요. 수업에 나올 기업 대부분이 참여해요."},{"b":[0.721,0.192,0.204,0.325],"c":[0.709,0.1758,0.228,0.3575],"r":0.9019,"img":"img/I1/walk/p002_30_04.jpg","say":"IoT스마트홈 커리큘럼을 정립해 공급해요. 지금 전국 60명의 교수, 교사가 이 체계로 배워요."},{"b":[0.077,0.543,0.849,0.219],"c":[0.0345,0.527,0.9339,0.251],"r":5.262,"img":"img/I1/walk/p002_30_05.jpg","say":"공간디자인 전공 최초의 IoT스마트홈 강의예요. 정답이 없는 내용도 다루니 의견과 피드백을 달라는 부탁이에요."}]}},{"p":3,"title":"15주차 강의 계획","terms":["AI@Home","Home Assistant","Matter","4-Layer Architecture"],"pass1":[{"kind":"say","lines":["한 학기 열다섯 번 수업의 지도예요.","'구분' 칸을 보면 그 주가 집의 어느 층 이야기인지 알 수 있어요.","중간에는 집 기기를 직접 연결해 보는 실습 주도 끼어 있어요."]}],"pass2":[{"kind":"points","head":"'구분' 칸 읽는 법","items":["히스토리, 핵심 이론 체계: 전체 그림을 먼저 잡는 주예요.","Layer1, 2, 3, 4: **4-Layer 적층구조(4-Layer Architecture)**의 층 번호예요. 1층 전기, 2층 공간, 3층 무선 연결, 4층 AI예요.","HA: **Home Assistant(홈 어시스턴트)**로 기기를 연결해 보는 실습 주예요.","종합: 조명과 기기를 도면에 배치하며 앞에서 배운 층을 합쳐요."]},{"kind":"check","q":"강의 계획표의 'Layer3' 주차는 무엇을 배우는 주일까요?","choices":["무선 통신으로 기기를 잇는 층","전기 배선 층","AI 판단 층","시험 주"],"a":0,"why":"Layer3은 연결 및 네트워크 계층이에요. 그래서 3, 4주차 주제가 무선통신 I, II예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"compare","head":"주차 한눈에 보기 (1)","cols":["구분","주차","주제"],"rows":[["히스토리","1","AI@Home 개요와 지능형홈 시스템 구조"],["핵심 이론 체계","2","데이터 흐름과 IoT 파이프라인"],["Layer3","3, 4","무선통신 I 허브 방식과 WPAN, II 논허브 방식과 Matter 표준"],["Layer2","5","L2 공간 센서 기술 및 공간 감지 범위 분석"],["Layer4","6, 9, 12","AI 기술 I 인지 루프, II 공간 UX 시나리오, III 공간 케어와 미래 확장성"]]},{"kind":"compare","head":"주차 한눈에 보기 (2)","cols":["구분","주차","주제","담당"],"rows":[["HA","7","스마트홈 현장 실무 및 HA 개요","공정식"],["시험","8","중간고사","공정식"],["HA","10, 11","HA 기반 기기 연동 기초 설정 실습, HA 자동화 시나리오 연동 실습 과제","공정식"],["Layer1","13","전기 인프라와 IoT 조명설계 기초","김철재"],["종합","14","IoT 조명, 기기 배치 설계","김철재"]]},{"kind":"warn","head":"표 맨 아래가 잘렸어요","items":["15주차 줄은 글자 아래쪽이 잘려 있어요. 모양으로 보아 기말고사(Final Exam), 공정식 교수님으로 보여요.","공지로 한 번 더 확인하세요."]}],"pass4":[{"kind":"check","q":"HA 실습을 맡은 교수님과 주차가 바르게 짝지어진 것은?","choices":["공정식, 7, 10, 11주차","김철재, 3, 4주차","공정식, 13, 14주차","김철재, 7, 10, 11주차"],"a":0,"why":"HA 주차(7, 10, 11)와 8주차 중간고사는 공정식 교수님, 나머지 이론 주는 김철재 교수님이에요."}],"pass5":[],"walk":{"head":{"b":[0.0681,0.1116,0.6696,0.1411],"c":[0.0346,0.0956,0.7366,0.1731],"r":6.018,"img":"img/I1/walk/p003_h.jpg"},"parts":[{"b":[0.077,0.271,0.849,0.04],"c":[0.0345,0.1967,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p003_30_01.jpg","say":"1주차가 지금 배우는 1강이에요. 구분은 히스토리, 주제는 AI@Home 개요와 지능형홈 시스템 구조예요."},{"b":[0.077,0.356,0.849,0.086],"c":[0.0345,0.3047,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p003_30_02.jpg","say":"3, 4주차는 Layer3 무선통신이에요. I은 허브 방식과 WPAN, II는 논허브 방식과 Matter 표준이에요."},{"b":[0.077,0.527,0.849,0.089],"c":[0.0345,0.4772,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p003_30_03.jpg","say":"7주차 HA 개요와 8주차 중간고사는 공정식 교수님이 맡아요."},{"b":[0.077,0.659,0.849,0.087],"c":[0.0345,0.6082,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p003_30_04.jpg","say":"10, 11주차도 HA 실습이에요. 기기 연동 기초 설정, 자동화 시나리오 연동과 실습 과제예요."},{"b":[0.077,0.818,0.849,0.103],"c":[0.0345,0.7752,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p003_30_05.jpg","say":"13주차 Layer1 전기 인프라와 IoT 조명설계 기초, 14주차 종합 IoT 조명, 기기 배치 설계예요."}]}},{"p":4,"title":"교과목 개요 및 학습 목표","terms":["4-Layer Architecture","Resident-Experience Backward Design","Architect","User Experience","AI Cognitive Loop"],"pass1":[{"kind":"analogy","head":"집을 네 층 건물로 봐요","scene":"네 층짜리 건물을 떠올려 보세요. 맨 아래층에서 전기가 들어오고, 그 위층에 방과 가구가 놓여요. 셋째 층에는 기기끼리 이야기하는 무선이 깔리고, 꼭대기 층에서 두뇌가 집 전체를 생각해요. 아래층이 흔들리면 위층도 제대로 일할 수 없어요.","map":[["맨 아래층 전기실","전기 층"],["방과 가구","공간, 기기 배치 층"],["무선이 깔린 층","연결 층"],["꼭대기 두뇌","지능 층"]]},{"kind":"say","lines":["이 네 층 그림을 **4-Layer 적층구조(4-Layer Architecture)**라고 불러요.","목표는 네 층을 한꺼번에 이끄는 **지능형 공간 Architect**가 되는 거예요.","오케스트라 지휘자처럼 전기, 공간, 무선, 인공지능을 한 곡으로 맞추는 사람이에요."]}],"pass2":[{"kind":"points","head":"학습목표 세 가지를 쉬운 말로","items":["공간 DX: 마감재와 센서 데이터가 합쳐지는 원리를 알고, 사는 사람의 경험에서 거꾸로 기술을 정해요.","4-Layer: 층끼리 어떻게 기대는지, **AI 인지 루프(AI Cognitive Loop)**가 층을 어떻게 도는지 분석해요.","Architect: 전기, 통신, AI 시공자와 대등하게 이야기하고 조명, 센서, 자동화를 총괄해요."]},{"kind":"points","head":"이 쪽에서 처음 만나는 용어","items":["**거주자 경험(User Experience)**: 그 집에 사는 사람이 실제로 느끼는 편하고 좋은 기분이에요. 줄여서 UX예요.","**거주자 경험 역산 설계(Resident-Experience Backward Design)**: 사는 사람의 기분(목표)부터 정하고 거꾸로 기기를 고르는 설계법이에요.","**AI 인지 루프(AI Cognitive Loop)**: 센서가 보고, AI가 생각하고, 기기가 움직이는 동그란 반복이에요.","**지능형 공간 Architect**: 도면 위에서 네 층 기술을 지휘하는 통합 기획자예요."]},{"kind":"check","q":"'거주자 경험 역산 설계'에서 설계를 시작하는 곳은?","choices":["사는 사람이 느낄 경험 목표","가장 싼 기기 목록","통신사 요금제","벽 속 전선 길이"],"a":0,"why":"역산은 거꾸로 계산한다는 뜻이에요. 경험 목표에서 출발해 필요한 기술을 거꾸로 끌어내요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"약어 풀이","items":["DX: 디지털 전환(Digital Transformation). 공간 DX는 공간이 데이터로 움직이게 바뀌는 일이에요.","UX: **거주자 경험(User Experience)**. R-BD: **거주자 경험 역산 설계(Resident-Experience Backward Design)**.","1-Loop: AI 인지 순환 체계. 감지, 전달, 판단, 실행이 한 바퀴 도는 고리예요. 2주차에 자세히 배워요.","L1~L4: **4-Layer 적층구조(4-Layer Architecture)**의 1층 전기, 2층 공간, 3층 무선, 4층 지능이에요."]}],"pass4":[{"kind":"check","q":"이 과목 개요에서 '중심축'이라고 한 설계 방법론은?","choices":["거주자 경험 역산 설계(R-BD)","Bottom-Up 시공","브랜드별 앱 설치","월패드 중앙 통제"],"a":0,"why":"개요 둘째 문장이에요. UX에서 기술 요구사항을 역으로 도출하는 R-BD를 중심축으로 삼아요."},{"kind":"english","head":"답안 문장: 과목 개요","en":"이 과목은 전기, 공간, 통신, AI의 4-Layer 구조로 주거 공간과 지능형 기술이 만나는 지점을 탐구하고, 거주자 경험 역산 설계(R-BD)를 중심축으로 지능형 공간 통합 기획자(Architect)를 기른다.","ko":"4-Layer(무엇을), R-BD(어떻게), Architect(누가) 세 단어가 들어가면 돼요.","tip":"무엇을, 어떻게, 누가 순서로 세 단어를 떠올려 쓰세요."}],"pass5":[],"walk":{"head":{"b":[0.0673,0.1116,0.2808,0.0666],"c":[0.0533,0.0956,0.3088,0.0986],"r":4.4292,"img":"img/I1/walk/p004_h.jpg"},"parts":[{"b":[0.077,0.199,0.849,0.177],"c":[0.0345,0.183,0.9339,0.209],"r":6.3194,"img":"img/I1/walk/p004_30_01.jpg","say":"교과목 개요: 전기, 공간, 통신, AI로 이어지는 4-Layer 구조로 주거 공간과 지능형 기술이 만나는 지점을 탐구하는 전공 이론 과목이에요. 중심축은 R-BD예요."},{"b":[0.077,0.402,0.273,0.244],"c":[0.0634,0.386,0.3003,0.276],"r":1.5387,"img":"img/I1/walk/p004_30_02.jpg","say":"학습목표 1 공간 DX: 물리적 마감과 센서 데이터가 결합되는 공간 DX 메커니즘을 이해하고, UX로부터 기술 요구사항을 역산 설계(R-BD)해요."},{"b":[0.365,0.402,0.273,0.244],"c":[0.3514,0.386,0.3003,0.276],"r":1.5387,"img":"img/I1/walk/p004_30_03.jpg","say":"학습목표 2 4-Layer: 전기(L1), 공간(L2), 무선(L3), 지능(L4) 계층 간 수직적 의존성과 AI 인지 순환 체계(1-Loop)의 연계성을 분석해요."},{"b":[0.651,0.402,0.274,0.244],"c":[0.6373,0.386,0.3014,0.276],"r":1.5444,"img":"img/I1/walk/p004_30_04.jpg","say":"학습목표 3 Architect: 시공자와 대등하게 소통하며 조명, 센서 배치, 자동화 시나리오를 총괄 지휘하는 실무 기획 역량이에요."},{"b":[0.077,0.665,0.849,0.135],"c":[0.0345,0.6382,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p004_30_05.jpg","say":"인사이트: 이론과 함께 지능형홈 시뮬레이터 실습을 해요. 도면 위에 기기를 놓아 보며 공간 기획 감각을 익혀요."}]}},{"p":5,"title":"교재 및 학습 시뮬레이터 연동","terms":["AI@Home","4-Layer Architecture","Resident-Experience Backward Design"],"pass1":[{"kind":"say","lines":["공부 도구는 두 가지예요. 책 한 권과 웹 시뮬레이터 하나예요.","책은 이론의 뼈대를 줘요.","시뮬레이터는 인터넷 창에서 도면 위에 기기를 놓고 눌러 보며 연습하게 해 줘요."]}],"pass2":[{"kind":"compare","head":"두 도구 비교","cols":["구분","이름","하는 일"],"rows":[["주교재(Textbook)","AI@Home 설계 입문","**4-Layer 적층구조(4-Layer Architecture)**와 **거주자 경험 역산 설계(Resident-Experience Backward Design)**로 이론 뼈대를 세워요"],["학습 도구(Simulator)","지능형홈 학습 시뮬레이터","평면도 진단, 무선 간섭 분석, AI 스택 시뮬레이션을 도면 위에서 해 봐요"]]}],"pass3":[{"kind":"look","walked":1}],"pass4":[{"kind":"check","q":"슬라이드에 적힌 시뮬레이터 실습 항목이 아닌 것은?","choices":["평면도 진단","무선 간섭 분석","AI 스택 시뮬레이션","배전반 전선 직접 결선"],"a":3,"why":"시뮬레이터는 도면 기반 실습이에요. 평면도 진단, 무선 간섭 분석, AI 스택 시뮬레이션 세 가지가 적혀 있어요."}],"pass5":[],"walk":{"head":{"b":[0.0673,0.1116,0.3281,0.0666],"c":[0.0509,0.0956,0.3609,0.0986],"r":5.1764,"img":"img/I1/walk/p005_h.jpg"},"parts":[{"b":[0.077,0.194,0.414,0.232],"c":[0.0563,0.178,0.4554,0.264],"r":2.4395,"img":"img/I1/walk/p005_30_01.jpg","say":"주교재 『AI@Home 설계 입문』 공저, 이론 및 구조 편. 4-Layer 수직 적층 구조와 R-BD로 이론 뼈대를 구성해요."},{"b":[0.511,0.194,0.415,0.232],"c":[0.4903,0.178,0.4565,0.264],"r":2.4454,"img":"img/I1/walk/p005_30_02.jpg","say":"지능형홈 학습 시뮬레이터 v260805. 주소는 charles-kim79.github.io/aihome_simul/ 이에요."},{"b":[0.525,0.333,0.389,0.071],"c":[0.5056,0.3135,0.4279,0.11],"r":5.5014,"img":"img/I1/walk/p005_30_03.jpg","say":"평면도 진단, 무선 간섭 분석, AI 스택 시뮬레이션을 도면 기반으로 직접 실습해요."},{"b":[0.077,0.453,0.849,0.105],"c":[0.0345,0.4112,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p005_30_04.jpg","say":"강의 진도에 맞춰 시뮬레이터 연계 개념과 실무 접근 방식을 함께 다뤄요."}]}},{"p":6,"title":"1강 AI@Home 개요와 지능형홈 시스템 구조","terms":["AI@Home","4 Core Values of AI@Home Design","4-Layer Architecture","Architect"],"pass1":[{"kind":"say","lines":["여기부터 1강 본론이에요. 1강은 세 토막이에요."]},{"kind":"points","head":"세 토막 미리 보기","items":["첫째 토막: 똑똑한 집이 어떻게 퍼졌고, 왜 생활에 자리 잡지 못했는지","둘째 토막: 똑똑한 공간이 지켜야 할 네 가지 약속","셋째 토막: 집을 네 층으로 나눠 보고, 지휘자가 할 일 알기"]}],"pass2":[{"kind":"points","head":"세 토막을 용어로 다시","items":["1.1강: **지능형 홈(AI@Home)**이 나온 배경과 진화 과정","1.2강: 지능형 공간을 다시 정의하고 **지능형홈 설계 4대 가치(4 Core Values of AI@Home Design)** 배우기","1.3강: **4-Layer 적층구조(4-Layer Architecture)**와 **지능형 공간 Architect**의 역할"]}],"pass3":[{"kind":"look","walked":1}],"pass4":[],"pass5":[],"walk":{"head":{"b":[0.0677,0.3526,0.4096,0.1849],"c":[0.0472,0.3366,0.4506,0.2169],"r":2.938,"img":"img/I1/walk/p006_h.jpg"},"parts":[{"b":[0.071,0.561,0.329,0.043],"c":[0.0545,0.5275,0.3619,0.11],"r":4.6528,"img":"img/I1/walk/p006_30_01.jpg","say":"1.1강 AI@Home의 등장 배경과 진화: 7쪽부터 15쪽까지예요."},{"b":[0.071,0.614,0.343,0.044],"c":[0.0538,0.581,0.3773,0.11],"r":4.8508,"img":"img/I1/walk/p006_30_02.jpg","say":"1.2강 지능형 공간의 재정의와 4대 가치: 16쪽부터 24쪽까지예요."},{"b":[0.071,0.67,0.386,0.045],"c":[0.0517,0.6375,0.4246,0.11],"r":5.4589,"img":"img/I1/walk/p006_30_03.jpg","say":"1.3강 4-Layer 적층구조와 Architect의 역할: 25쪽부터 34쪽까지예요."}]}},{"p":7,"title":"[1.1강] 스마트홈 확산 역사와 AI@Home 진화","terms":["Smart Home","AI@Home","Business Model"],"pass1":[{"kind":"say","lines":["1.1강은 일곱 조각이에요.","옛날이야기에서 출발해 왜 막혔는지 보고, 새 집의 모습과 오늘 시장의 빈틈까지 가요."]}],"pass2":[{"kind":"points","head":"일곱 조각을 네 묶음으로","items":["과거: **스마트홈(Smart Home)**이 퍼진 역사와 자리 잡지 못한 이유","새 모습: **지능형 홈(AI@Home)**의 정의와 세대별 진화","시장: 큰 회사와 전문 회사들의 생태계 비교","빈틈: 회사마다 돈 버는 방식, 곧 **비즈니스 모델(Business Model)** 때문에 생긴 병목"]}],"pass3":[{"kind":"look","walked":1}],"pass4":[],"pass5":[],"walk":{"head":{"b":[0.0696,0.111,0.5069,0.0722],"c":[0.0443,0.095,0.5576,0.1042],"r":7.5679,"img":"img/I1/walk/p007_h.jpg"},"parts":[{"b":[0.093,0.222,0.55,0.111],"c":[0.0655,0.206,0.605,0.143],"r":5.9833,"img":"img/I1/walk/p007_30_01.jpg","say":"1.1.1 확산의 역사와 산업계의 패권 경쟁, 1.1.2 정착 한계 원인 분석이에요."},{"b":[0.093,0.364,0.55,0.111],"c":[0.0655,0.348,0.605,0.143],"r":5.9833,"img":"img/I1/walk/p007_30_02.jpg","say":"1.1.3 AI@Home(자율 지능형 공간)의 등장과 정의, 1.1.4 진화 흐름과 패러다임 전환이에요."},{"b":[0.093,0.503,0.557,0.113],"c":[0.0652,0.487,0.6127,0.145],"r":5.9759,"img":"img/I1/walk/p007_30_03.jpg","say":"1.1.5 빅테크와 가전 주도 생태계, 1.1.6 전문 브랜드와 스타트업 생태계예요."},{"b":[0.093,0.644,0.436,0.042],"c":[0.0712,0.61,0.4796,0.11],"r":6.166,"img":"img/I1/walk/p007_30_04.jpg","say":"1.1.7 공간 전문가 관점의 핵심 병목, BM 상세 분석이에요. BM은 비즈니스 모델이에요."}]}},{"p":8,"title":"1.1.1 스마트홈 확산의 역사와 산업계의 패권 경쟁","terms":["Smart Home","IPTV","Lock-in","AI Speaker","SmartThings","LG ThinQ"],"pass1":[{"kind":"say","lines":["똑똑한 집은 세 번의 물결로 퍼졌어요.","처음엔 TV에 붙은 상자, 다음엔 말로 부르는 스피커, 그다음엔 휴대폰 앱이 주인공이었어요.","세 번 모두 회사들이 거실의 주인 자리를 차지하려고 벌인 경쟁이었어요."]},{"kind":"figure","head":"세 번의 물결","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect class=\"box\" x=\"10\" y=\"80\" width=\"130\" height=\"90\" rx=\"3\"/><text class=\"tb\" x=\"75\" y=\"115\" font-size=\"18\" text-anchor=\"middle\">TV 상자<\/text><text class=\"tm\" x=\"75\" y=\"145\" font-size=\"14\" text-anchor=\"middle\">첫 물결<\/text><line class=\"e2 b2\" x1=\"140\" y1=\"125\" x2=\"168\" y2=\"125\"/><polygon class=\"arrow b2\" points=\"168,118 180,125 168,132\"/><rect class=\"box b2\" x=\"180\" y=\"80\" width=\"130\" height=\"90\" rx=\"3\"/><text class=\"tb b2\" x=\"245\" y=\"115\" font-size=\"18\" text-anchor=\"middle\">말하는 스피커<\/text><text class=\"tm b2\" x=\"245\" y=\"145\" font-size=\"14\" text-anchor=\"middle\">둘째 물결<\/text><line class=\"e2 b3\" x1=\"310\" y1=\"125\" x2=\"328\" y2=\"125\"/><polygon class=\"arrow b3\" points=\"328,118 340,125 328,132\"/><rect class=\"box2 b3\" x=\"340\" y=\"80\" width=\"130\" height=\"90\" rx=\"3\"/><text class=\"tb b3\" x=\"405\" y=\"115\" font-size=\"18\" text-anchor=\"middle\">휴대폰 앱<\/text><text class=\"tm b3\" x=\"405\" y=\"145\" font-size=\"14\" text-anchor=\"middle\">셋째 물결<\/text><text class=\"t\" x=\"240\" y=\"220\" font-size=\"16\" text-anchor=\"middle\">세 번 모두 거실의 주인 자리를 노린 경쟁<\/text><\/svg>","caption":"TV 상자, 말하는 스피커, 휴대폰 앱 순서로 퍼졌어요.","builds":3}],"pass2":[{"kind":"points","head":"물결마다 주인공과 목적","items":["첫 물결 **IPTV 홈 셋톱(IPTV)**: 통신사가 TV에 붙인 상자예요. TV 화면을 집 조종판으로 썼어요.","통신사의 목적은 **락인(Lock-in)**이었어요. 한 번 가입한 손님이 다른 회사로 못 떠나게 붙잡는 거예요.","둘째 물결 **AI 스피커(AI Speaker)**: 말로 명령받는 창구를 먼저 차지하려고 사은품으로 나눠 줬어요.","셋째 물결 가전 앱: **SmartThings(스마트싱스)**, **LG ThinQ(LG 씽큐)** 앱으로 휴대폰 원격 조종이 흔해졌어요."]},{"kind":"check","q":"'락인(Lock-in)'의 뜻으로 알맞은 것은?","choices":["가입한 손님을 다른 회사로 못 떠나게 붙잡아 두기","현관문을 자동으로 잠그기","기기끼리 암호를 맞추기","앱을 하나로 합치기"],"a":0,"why":"락인(Lock-in)은 고객을 묶어 두는 전략이에요. 첫 물결 IPTV 홈 셋톱 경쟁의 목적이었어요."}],"pass3":[{"kind":"look","walked":1},{"kind":"compare","head":"세 단계 정리","cols":["단계","시기","주인공","누가, 왜"],"rows":[["1단계","2010년대 초, 중반","**IPTV 홈 셋톱(IPTV)**","통신 3사, 유선 결합 가입자 **락인(Lock-in)**"],["2단계","2017~2019년","**AI 스피커(AI Speaker)**","통신사와 빅테크, 음성 인터페이스 주도권"],["3단계","2020~2022년","가전 IoT 앱","가전 제조사(**SmartThings(스마트싱스)**, **LG ThinQ(LG 씽큐)**), 팬데믹 집콕"]]},{"kind":"bg","src":"일반 상식","lines":["튜링 테스트는 앨런 튜링이 1950년에 제안했어요. 기계가 사람처럼 대화하는지 가리는 시험이에요.","인공지능(AI)이라는 이름은 1956년 다트머스 회의에서 처음 쓰였어요.","빅테크는 구글, 애플 같은 거대 IT 기업을 말해요."]}],"pass4":[{"kind":"check","q":"스마트홈 확산 2단계에서 AI 스피커를 사은품으로까지 뿌린 이유는?","choices":["음성 인터페이스 주도권을 먼저 잡으려고","TV 셋톱 재고를 없애려고","Matter 표준 인증을 받으려고","월패드를 대체하라는 법 때문에"],"a":0,"why":"말로 명령받는 창구를 먼저 차지하면 그 회사 서비스를 계속 쓰게 되니까요."},{"kind":"check","q":"\"스마트홈은 기술이 완성되어서 퍼졌다.\" 맞을까요?","choices":["틀려요","맞아요"],"a":0,"why":"인사이트 문장이 반대로 말해요. 기술적 완성도보다 기업들이 플랫폼 패권을 노리고 마케팅으로 밀어붙인 시기였어요."},{"kind":"warn","head":"헷갈리기 쉬운 순서","items":["1단계 주인공은 AI 스피커가 아니라 IPTV 홈 셋톱이에요.","순서는 TV 상자, 스피커, 앱. 첫 글자로 '티, 스, 앱' 하고 외워요.","SmartThings는 삼성, ThinQ는 LG예요."]},{"kind":"english","head":"답안 문장: 확산 3단계","en":"스마트홈은 IPTV 홈 셋톱 경쟁(통신사 락인), AI 스피커 보급전(음성 인터페이스 주도권), 가전 IoT와 팬데믹 특수(가전 앱 원격 제어) 3단계로 확산되었다.","ko":"단계 이름 뒤 괄호에 누가 무엇을 노렸는지 붙이면 서술형 답이 돼요.","tip":"티, 스, 앱 순서에 목적 한 단어씩: 락인, 주도권, 원격 제어."}],"pass5":[],"walk":{"head":{"b":[0.0673,0.1116,0.5258,0.1012],"c":[0.041,0.0956,0.5783,0.1332],"r":6.14,"img":"img/I1/walk/p008_h.jpg"},"parts":[{"b":[0.077,0.227,0.27,0.232],"c":[0.0635,0.211,0.297,0.264],"r":1.591,"img":"img/I1/walk/p008_30_01.jpg","say":"1단계(2010년대 초, 중반) IPTV 홈 셋톱 경쟁: 통신 3사가 유선 결합 가입자 락인을 위해 TV 거실 화면을 홈 대시보드로 삼았어요."},{"b":[0.366,0.227,0.27,0.232],"c":[0.3525,0.211,0.297,0.264],"r":1.591,"img":"img/I1/walk/p008_30_02.jpg","say":"2단계(2017~2019년) AI 스피커 보급전: 통신사와 빅테크가 음성 인터페이스 주도권을 노리고 결합상품 사은품으로 스마트 스피커를 뿌렸어요."},{"b":[0.655,0.227,0.271,0.232],"c":[0.6414,0.211,0.2981,0.264],"r":1.5969,"img":"img/I1/walk/p008_30_03.jpg","say":"3단계(2020~2022년) 가전 IoT와 팬데믹 특수: 집콕 트렌드와 가전 호조로 SmartThings, ThinQ 중심 스마트폰 앱 원격 제어가 대중화됐어요."},{"b":[0.107,0.535,0.807,0.071],"c":[0.0667,0.4808,0.8877,0.1793],"r":7.0017,"img":"img/I1/walk/p008_30_04.jpg","say":"기술 완성도보다 통신사, 빅테크, 가전 제조사가 플랫폼 패권을 잡으려고 마케팅으로 스마트홈 개념을 각인시킨 시기였어요."},{"b":[0.107,0.624,0.736,0.042],"c":[0.0702,0.5632,0.8096,0.1636],"r":6.9985,"img":"img/I1/walk/p008_30_05.jpg","say":"생각거리: 튜링 테스트, 다트머스 회의가 각각 몇 년도였는지 묻고 있어요."}]}},{"p":9,"title":"1.1.2 스마트홈 정착 한계 원인 분석","terms":["Smart Home","Manual Control","App Fragmentation","Paradox of Technology","AI@Home"],"pass1":[{"kind":"say","lines":["그렇게 많이 퍼졌는데, 왜 금방 안 쓰게 됐을까요?","까닭은 셋이에요.","매번 내가 시켜야 했고, 회사마다 앱이 따로였고, 편하려고 샀는데 배울 게 더 많았어요.","이 막힌 곳을 뚫는 사람이 여러분이라고 슬라이드가 말해요."]}],"pass2":[{"kind":"points","head":"세 가지 한계를 한 줄씩","items":["**기기 중심의 수동 제어(Manual Control)**: 내가 앱을 열거나 말을 해야만 움직여요. 기기는 방에 누가 있는지 몰라요.","**브랜드별 앱 파편화(App Fragmentation)**: 회사마다 앱이 따로라 휴대폰에 앱이 우르르 쌓여요.","**기술의 역설(Paradox of Technology)**: 편하려고 들였는데 설정법과 오류 해결법을 공부해야 해요."]},{"kind":"check","q":"\"조명은 A 앱, 에어컨은 B 앱, 센서는 C 앱으로 따로 켜야 해서 피곤하다.\" 어떤 한계일까요?","choices":["브랜드별 앱 파편화","기술의 역설","기기 중심의 수동 제어","락인"],"a":0,"why":"제조사별 전용 앱이 흩어진 상황이라 **브랜드별 앱 파편화(App Fragmentation)**예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"compare","head":"한계와 AI@Home의 답","cols":["한계","무엇이 문제","AI@Home은"],"rows":[["**기기 중심의 수동 제어(Manual Control)**","명령해야만 움직여요","수동 조작을 빼고 센서로 스스로 반응해요(10쪽)"],["**브랜드별 앱 파편화(App Fragmentation)**","앱이 흩어져 관리가 복잡해요","Matter, Thread, IPv6 통합 통신을 지향해요(11쪽)"],["**기술의 역설(Paradox of Technology)**","배울 게 늘어나요","사람이 기술을 배우지 않아도 공간이 맞춰 줘요"]]}],"pass4":[{"kind":"check","q":"스마트홈 정착 한계 원인으로 슬라이드에 나오지 않은 것은?","choices":["기기 중심의 수동 제어","브랜드별 앱 파편화","기술의 역설","전기 요금 누진세"],"a":3,"why":"세 가지는 수동 제어, 앱 파편화, 기술의 역설이에요. 누진세는 1.2강 절감 가치에 나와요."},{"kind":"warn","head":"비슷해 보이는 두 용어","items":["**기술의 역설(Paradox of Technology)**은 '편하려다 오히려 공부거리가 늘었다'는 역효과예요.","**브랜드별 앱 파편화(App Fragmentation)**는 '앱이 여러 개로 흩어졌다'는 구조 문제예요."]},{"kind":"english","head":"답안 문장: 정착 한계 (15쪽 Q1과 같은 답)","en":"사용자가 앱이나 음성으로 일일이 명령해야 하는 기기 중심의 수동 제어 구조와 제조사별 전용 앱의 파편화, 그리고 설정법과 오류 대처를 배워야 하는 기술의 역설 때문이다.","ko":"수동 제어, 앱 파편화 두 가지는 꼭 쓰고, 기술의 역설을 더하면 완성이에요.","tip":"'수, 파, 역' 세 글자로 외워요."}],"pass5":[],"walk":{"head":{"b":[0.0669,0.1116,0.3838,0.1012],"c":[0.0477,0.0956,0.4222,0.1332],"r":4.4826,"img":"img/I1/walk/p009_h.jpg"},"parts":[{"b":[0.093,0.224,0.8,0.04],"c":[0.053,0.1551,0.88,0.1778],"r":6.9996,"img":"img/I1/walk/p009_30_01.jpg","say":"기기 중심의 수동 제어: 앱을 직접 열거나 음성을 발화해야만 구동되어, 기기가 거주자의 공간 맥락을 인지하지 못해요."},{"b":[0.093,0.283,0.836,0.073],"c":[0.0512,0.2266,0.9196,0.1858],"r":6.9996,"img":"img/I1/walk/p009_30_02.jpg","say":"브랜드별 앱 파편화: 제조사별 전용 앱이 분산되어, 여러 기기 연동 때 통합 관리가 복잡하고 사용자 피로도가 커져요."},{"b":[0.093,0.374,0.825,0.04],"c":[0.0517,0.3023,0.9075,0.1833],"r":7.0017,"img":"img/I1/walk/p009_30_03.jpg","say":"기술의 역설: 일상 편의를 위해 도입했지만 기기별 설정법과 통신 오류 대처법을 학습해야 하는 역효과가 생겨요."},{"b":[0.077,0.439,0.849,0.139],"c":[0.0345,0.4142,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p009_30_04.jpg","say":"인사이트: 이 한계를 넘어 거주자의 일상과 기술을 자연스럽게 융합하는 것이 AI@Home 전문가가 필요한 이유예요."}]}},{"p":10,"title":"1.1.3 AI@Home (자율 지능형 공간)의 등장과 정의","terms":["AI@Home","Smart Home","비식별 센서","Manual Control","Connected","Autonomous"],"pass1":[{"kind":"say","lines":["새 집은 휴대폰을 열지 않아요.","집이 사는 사람을 알아보고, 스스로 불을 켜고 공기를 바꿔요."]},{"kind":"analogy","head":"집을 한 사람의 몸으로 봐요","scene":"집을 한 사람의 몸이라고 생각해 보세요. 천장의 센서는 눈과 피부처럼 방 안의 움직임과 온도를 느껴요. 두뇌 역할의 인공지능이 '어두운데 사람이 들어왔네' 하고 판단해요. 그러면 조명과 환기 장치가 손발처럼 움직여요.","map":[["눈과 피부","센서"],["두뇌","인공지능(AI)의 판단"],["손발","조명, 환기 장치 같은 기기"]]},{"kind":"say","lines":["이렇게 스스로 반응하는 집을 **지능형 홈(AI@Home)**이라고 불러요."]}],"pass2":[{"kind":"compare","head":"스마트홈과 AI@Home","cols":["구분","**스마트홈(Smart Home)**","**지능형 홈(AI@Home)**"],"rows":[["누가 시작","내가 앱이나 말로 명령해요","공간이 알아채고 반응해요"],["사람의 역할","조종사","그냥 사는 사람"],["한 단어로","**연결(Connected)**","**자율(Autonomous)**"]]},{"kind":"points","head":"정의 문장을 네 조각으로","items":["거주자의 수동 조작을 뺀다: **기기 중심의 수동 제어(Manual Control)**를 없앤다는 뜻이에요.","공간 안의 **비식별 센서**가 행동과 환경 데이터를 모은다: 얼굴을 찍지 않고 사람이 있는지만 알아채요.","AI 알고리즘으로 최적 환경을 스스로 맞춘다: 판단과 실행을 집이 해요.","디지털 신(新) 주거 공간 체계: 새로운 방식의 집 전체 시스템이라는 말이에요."]},{"kind":"check","q":"'비식별 센서'의 뜻으로 알맞은 것은?","choices":["누구인지 알아보지 않고 사람이 있는지, 환경이 어떤지만 모으는 센서","얼굴을 찍어 가족을 구별하는 카메라","지문으로 문을 여는 센서","전기 누전을 찾는 센서"],"a":0,"why":"비식별은 '누구인지 알아보지 않는다'는 뜻이에요. 욕실, 침실에서도 사생활을 지켜요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"정의를 더 정확히","items":["패러다임은 생각의 틀이에요. 집을 '조작하는 물건'에서 '스스로 반응하는 환경'으로 보는 틀이 바뀌었다는 말이에요.","용어해설집의 **스마트홈(Smart Home)**: 월패드 같은 중앙 제어 장치를 중심으로 기기를 잇고, 사용자 명령(앱, 음성)으로 원격 제어와 단순 자동화를 하는 주거 환경이에요.","**지능형 홈(AI@Home)**의 부제는 '자율 지능형 공간'이에요.","정의 속 **비식별 센서**는 2주차 '비식별 센싱'으로 이어져요."]}],"pass4":[{"kind":"check","q":"AI@Home 학술 정의에 들어가지 않는 내용은?","choices":["거주자의 수동 조작 배제","비식별 센서의 행동, 환경 데이터 수집","AI 알고리즘 기반 최적 환경 자율 조율","스마트폰 앱으로 기기마다 직접 명령"],"a":3,"why":"앱으로 직접 명령하는 것은 스마트홈(연결) 방식이에요. AI@Home은 그 수동 조작을 빼요."},{"kind":"english","head":"답안 문장: AI@Home 정의","en":"AI@Home은 거주자의 수동 조작을 배제하고, 공간 내 비식별 센서가 행동 및 환경 데이터를 수집하여 AI 알고리즘 기반으로 최적 환경을 자율 조율하는 디지털 신(新) 주거 공간 체계이다.","ko":"배제(수동 조작), 수집(비식별 센서), 조율(AI 자율), 체계(신 주거 공간) 네 동사를 순서대로.","tip":"'빼고, 모으고, 맞추는 새 집' 으로 줄여 외워요."},{"kind":"warn","head":"시험에서 주의","items":["정의 문장에서 '비식별'을 빠뜨리기 쉬워요.","실기 가이드북 2권 앞머리는 '지능형홈'을 기존 '스마트홈'에 AI를 접목한 미래지향 개념으로 보되, 현 단계에서는 구체적 차이가 없어 같은 것으로 봐도 된다고 적어요.","수업에서는 연결(스마트홈)과 자율(AI@Home)을 구별하니, 수업 시험에서는 차이를 써야 해요."]}],"pass5":[],"walk":{"head":{"b":[0.0681,0.111,0.5585,0.061],"c":[0.0402,0.095,0.6143,0.093],"r":9.3415,"img":"img/I1/walk/p010_h.jpg"},"parts":[{"b":[0.071,0.174,0.379,0.033],"c":[0.0521,0.1355,0.4169,0.11],"r":5.3599,"img":"img/I1/walk/p010_30_01.jpg","say":"부제: 조작 대상에서 스스로 반응하는 자율 환경으로의 패러다임 전환이에요."},{"b":[0.071,0.224,0.571,0.129],"c":[0.0424,0.208,0.6281,0.161],"r":5.5173,"img":"img/I1/walk/p010_30_02.jpg","say":"큰 글씨: 스마트폰을 열지 않는다. 공간이 사용자를 이해하고 스스로 반응한다."},{"b":[0.077,0.381,0.849,0.139],"c":[0.0345,0.3562,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p010_30_03.jpg","say":"AI@Home 학술 정의: 거주자의 수동 조작을 배제하고, 비식별 센서가 행동 및 환경 데이터를 수집해 AI 알고리즘으로 최적 환경을 자율 조율하는 디지털 신(新) 주거 공간 체계예요."}]}},{"p":11,"title":"1.1.4 스마트홈 진화 흐름과 패러다임 전환","terms":["RS-485","Wall Pad","Wi-Fi","Zigbee","Matter","Thread","IPv6","AI Cognitive Loop","AI@Home","User Experience"],"pass1":[{"kind":"say","lines":["똑똑한 집은 세 세대로 자라 왔어요.","첫 세대는 벽의 조종판과 줄, 둘째 세대는 기기마다 따로 쓰는 무선이에요.","앞으로 갈 곳은 모두 같은 말을 쓰고, 인공지능이 스스로 조율하는 집이에요."]},{"kind":"figure","head":"세 세대 한눈에","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect class=\"box\" x=\"10\" y=\"40\" width=\"140\" height=\"180\" rx=\"3\"/><text class=\"tb\" x=\"80\" y=\"70\" font-size=\"16\" text-anchor=\"middle\">첫 세대<\/text><rect class=\"n\" x=\"45\" y=\"95\" width=\"70\" height=\"36\" rx=\"2\"/><text class=\"tl\" x=\"80\" y=\"119\" font-size=\"14\" text-anchor=\"middle\">벽 조종판<\/text><line class=\"e\" x1=\"80\" y1=\"131\" x2=\"80\" y2=\"170\"/><text class=\"tm\" x=\"80\" y=\"195\" font-size=\"14\" text-anchor=\"middle\">줄로 연결<\/text><rect class=\"box b2\" x=\"170\" y=\"40\" width=\"140\" height=\"180\" rx=\"3\"/><text class=\"tb b2\" x=\"240\" y=\"70\" font-size=\"16\" text-anchor=\"middle\">둘째 세대<\/text><circle class=\"n3 b2\" cx=\"200\" cy=\"120\" r=\"16\"/><circle class=\"n3 b2\" cx=\"240\" cy=\"150\" r=\"16\"/><circle class=\"n3 b2\" cx=\"280\" cy=\"120\" r=\"16\"/><text class=\"tm b2\" x=\"240\" y=\"195\" font-size=\"14\" text-anchor=\"middle\">회사마다 다른 무선<\/text><rect class=\"box2 b3\" x=\"330\" y=\"40\" width=\"140\" height=\"180\" rx=\"3\"/><text class=\"tb b3\" x=\"400\" y=\"70\" font-size=\"16\" text-anchor=\"middle\">AI@Home<\/text><circle class=\"n2 b3\" cx=\"400\" cy=\"125\" r=\"22\"/><text class=\"tl b3\" x=\"400\" y=\"130\" font-size=\"14\" text-anchor=\"middle\">AI<\/text><line class=\"e2 b3\" x1=\"360\" y1=\"165\" x2=\"440\" y2=\"165\"/><text class=\"tm b3\" x=\"400\" y=\"195\" font-size=\"14\" text-anchor=\"middle\">한 언어 + 스스로<\/text><\/svg>","caption":"줄로 잇던 집, 무선이 흩어진 집, 한 언어로 묶이고 스스로 판단하는 집","builds":3},{"kind":"analogy","head":"프로토콜은 서로 쓰는 언어예요","scene":"친구들이 저마다 다른 나라 말만 쓰는 교실이 있어요. 옆자리와도 쪽지가 안 통해요. 반 전체가 한 가지 말을 쓰기로 약속하면 누구와도 바로 이야기가 통해요. 둘째 세대 집이 앞의 교실이고, **Matter(매터)**는 그 공통 약속이에요.","map":[["나라마다 다른 말","회사마다 다른 무선 방식"],["반 전체의 공통 말","Matter 같은 공통 표준"],["쪽지가 바로 통함","회사가 달라도 기기끼리 연동"]]}],"pass2":[{"kind":"points","head":"첫 세대와 둘째 세대의 용어","items":["**세대단말기(Wall Pad)**: 현관이나 거실 벽에 붙은 집 조종 화면이에요. 흔히 월패드라고 불러요.","**RS-485**: 월패드와 설비를 잇는 옛날식 유선 줄이에요. 무선이 아니에요.","**Wi-Fi(와이파이)**: 집에서 인터넷 쓰는 무선이에요.","**Zigbee(지그비)**: 전기를 조금 먹고 센서끼리 손잡고 연결하는 무선이에요."]},{"kind":"points","head":"AI@Home 세대의 용어","items":["**Matter(매터)**: 회사가 달라도 기기끼리 말이 통하게 해 주는 공통 약속이에요.","**Thread(스레드)**: Matter 기기들이 쓰는 저전력 무선 그물망이에요.","**IPv6**: 기기마다 인터넷 주소를 하나씩 붙여 줄 수 있는 새 주소 체계예요.","**AI 인지 루프(AI Cognitive Loop)**: 센서가 보고, AI가 판단하고, 기기가 움직이는 반복이에요."]},{"kind":"steps","head":"AI 인지 루프를 주문으로","steps":["감지: 센서가 느껴요","전달: 네트워크가 신호를 날라요","판단: 허브와 플랫폼(AI)이 무엇을 할지 정해요","실행: 기기가 움직여요","다시 감지로 돌아가 한 바퀴를 계속 돌아요"],"answer":"센서가 느끼고, 네트워크가 나르고, 허브와 플랫폼이 판단하고, 기기가 움직여요."},{"kind":"check","q":"월패드와 설비를 줄로 잇는 첫 세대의 통신 방식은?","choices":["RS-485","Zigbee","Thread","Matter"],"a":0,"why":"**RS-485**는 유선이에요. Zigbee, Thread는 무선, Matter는 공통 연결 표준이에요."}],"pass3":[{"kind":"look","walked":1},{"kind":"compare","head":"세대 비교표 그대로","cols":["구분","1세대 유선 홈네트워크","2세대 개별 무선 IoT","AI@Home 미래 지향점"],"rows":[["통신 매체","월패드 중심 **RS-485** 유선 직렬","**Wi-Fi(와이파이)**, **Zigbee(지그비)** 개별 파편화 무선","**Matter(매터)**, **Thread(스레드)**, **IPv6** 통합 통신"],["제어 방식","벽면 중앙 수동 패널 제어","스마트폰 앱 및 음성 스피커 명령","**AI 인지 루프(AI Cognitive Loop)** 기반 자율 조율"],["공간 가치","단지 내 중앙 통제 및 방범","기기 단위 기능 원격 작동","거주자 UX 맞춤 공간 케어"]]},{"kind":"points","head":"표 속 낱말 풀이","items":["직렬: 기기를 한 줄에 차례로 이어 붙이는 연결이에요. **RS-485**는 두 가닥 꼬임선을 쓰는 유선 직렬 통신이에요.","**세대단말기(Wall Pad)**는 이 줄의 중심이라 '월패드 중심'이라고 적었어요.","UX는 **거주자 경험(User Experience)**이에요. 맞춤 공간 케어는 사는 사람에 맞춰 공간이 돌봐 준다는 뜻이에요.","**Thread(스레드)**는 **IPv6** 기반 저전력 메시 기술이고, **Matter(매터)**에서 저전력 기기 연결에 쓰여요."]},{"kind":"bg","src":"기초 다지기 6, 7단원","lines":["유선은 전선으로, 무선은 전파로 신호를 보내요.","프로토콜은 기기끼리 정한 대화 규칙이에요. 규칙이 다르면 연결돼도 말이 안 통해요.","IP 주소는 인터넷에서 기기를 찾는 번지수예요."]}],"pass4":[{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 18번","q":"지능형 홈 구현에 사용되는 무선 통신 기술에 해당하지 않는 것은? (① Thread ② Z-Wave ③ RS-485 ④ Zigbee)","qko":"넷 중에서 무선이 아닌 것 하나를 고르는 문제예요.","solve":["표의 1세대 칸을 떠올려요. RS-485는 월패드 중심 '유선' 직렬이에요.","Thread, Zigbee는 표의 무선 칸에 있어요. Z-Wave도 저전력 무선 메시 기술이에요.","그래서 무선이 아닌 것은 RS-485예요."],"answer":"③ RS-485"},{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 23번","q":"Matter 환경에서 저전력 IoT 기기 연결에 쓰이는 Thread의 특징으로 가장 적절하지 않은 것은? (① IPv6 기반 ② 저전력 메시 네트워크 지원 ③ VPN 기반 암호화 무선 통신 기술 ④ Zigbee처럼 IEEE 802.15.4 기반)","qko":"Thread 설명 중 틀린 것 하나를 고르는 문제예요.","solve":["Thread의 핵심 특징은 IPv6 기반, 저전력 메시, IEEE 802.15.4 기반 세 가지예요.","VPN(가상사설망)은 인터넷 위에 암호화된 통로를 만드는 보안 기술이에요. Thread를 설명하는 말이 아니에요.","그래서 틀린 것은 ③이에요."],"answer":"③ VPN 기반의 암호화 무선 통신 기술이다"},{"kind":"check","q":"AI@Home 세대의 통신 매체로 표에 적힌 조합은?","choices":["Matter, Thread, IPv6 통합 통신","RS-485 유선 직렬","Wi-Fi, Zigbee 개별 파편화 무선","IPTV 셋톱 결합"],"a":0,"why":"1세대 RS-485, 2세대 Wi-Fi와 Zigbee, AI@Home은 Matter, Thread, IPv6예요."},{"kind":"english","head":"답안 문장: 15쪽 Q2와 같은 답","en":"안정적인 2세대(개별 무선 IoT) 실무 지식을 기본으로 삼고, AI가 자율 조율하는 AI@Home의 가치를 지향해야 한다.","ko":"현재 시장은 2세대 무선 IoT 위에 AI를 안전하게 접목하는 전환기라는 인사이트가 근거예요.","tip":"'2세대가 바닥, AI@Home이 목표'."}],"pass5":[{"kind":"points","head":"실기 가이드북 2권, 1-3 지능형홈 기기구성 (지능형홈 연동 표준)","items":["**Matter(매터)**는 IP 기반의 응용 계층 IoT 통합 표준이에요.","개별 기기를 구분하는 데 **IPv6**를 써요.","IP를 쓰지 않는 기존 **Zigbee(지그비)** 장치는 Bridge 장치가 있어야 Matter에 붙어요.","데이터 통신은 **Wi-Fi(와이파이)**, **Thread(스레드)**, Zigbee via Bridge 등, 기기 등록(Provisioning)은 Bluetooth, QR code, NFC 등이 맡아요."]},{"kind":"check","q":"실기 가이드북에서 Matter 환경에 기존 Zigbee 장치를 붙이려면 필요하다고 한 장치는?","choices":["Bridge 장치","월패드","RS-485 배선","IPTV 셋톱"],"a":0,"why":"Zigbee는 IP를 쓰지 않아서 중간에서 이어 주는 Bridge 장치가 필요해요."}],"walk":{"head":{"b":[0.0681,0.1116,0.4573,0.0666],"c":[0.0452,0.0956,0.503,0.0986],"r":7.2146,"img":"img/I1/walk/p011_h.jpg"},"parts":[{"b":[0.077,0.202,0.849,0.059],"c":[0.0345,0.1372,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p011_30_01.jpg","say":"비교 기준 세 줄: 통신 매체, 제어 방식, 공간 가치. 열은 1세대, 2세대, AI@Home이에요."},{"b":[0.179,0.268,0.229,0.182],"c":[0.167,0.252,0.253,0.214],"r":1.672,"img":"img/I1/walk/p011_30_02.jpg","say":"1세대(유선 홈네트워크): 월패드 중심 RS-485 유선 직렬, 벽면 중앙 수동 패널 제어, 단지 내 중앙 통제 및 방범"},{"b":[0.414,0.268,0.246,0.182],"c":[0.4017,0.252,0.2706,0.214],"r":1.7883,"img":"img/I1/walk/p011_30_03.jpg","say":"2세대(개별 무선 IoT): Wi-Fi, Zigbee 개별 파편화 무선, 스마트폰 앱 및 음성 스피커 명령, 기기 단위 기능 원격 작동"},{"b":[0.664,0.268,0.261,0.182],"c":[0.6509,0.252,0.2871,0.214],"r":1.8973,"img":"img/I1/walk/p011_30_04.jpg","say":"AI@Home(미래 지향점): Matter, Thread, IPv6 통합 통신, AI 인지 루프 기반 자율 조율, 거주자 UX 맞춤 공간 케어"},{"b":[0.077,0.48,0.849,0.199],"c":[0.0345,0.464,0.9339,0.231],"r":5.7175,"img":"img/I1/walk/p011_30_05.jpg","say":"인사이트: 지금 시장은 개별 무선 IoT(2세대) 위에 AI를 어떻게 안전하게 접목할지 고민하는 전환기예요."}]}},{"p":12,"title":"1.1.5 글로벌 플랫폼 생태계 분석 1: 빅테크 및 가전 주도 생태계","terms":["Google Home","Apple Home","SmartThings","LG ThinQ","Matter","Multimodal","Made for iPhone/iPad/iPod","Home Hub"],"pass1":[{"kind":"say","lines":["집 안 기기를 자기 편으로 묶으려는 큰 회사가 넷 있어요.","구글, 애플, 삼성, LG예요. 회사마다 잘하는 것과 아쉬운 것이 달라요."]},{"kind":"analogy","head":"허브는 반 반장이에요","scene":"교실에 친구가 많을 때 선생님이 한 명씩 따로 부르면 시간이 오래 걸려요. 반장이 친구들 말을 모아 선생님께 전하고, 선생님 말을 친구들에게 나눠 주면 금방 끝나요. 삼성은 큰 가전에 이 반장, 곧 **홈 허브(Home Hub)**를 붙였어요.","map":[["반 친구들","집 안 여러 기기"],["반장","홈 허브(Home Hub)"],["선생님","스마트홈 플랫폼, 앱"]]}],"pass2":[{"kind":"compare","head":"네 회사 한 줄 비교","cols":["회사","잘하는 것","아쉬운 것"],"rows":[["**Google Home(구글 홈)**","여러 회사 기기와 잘 어울려요","회사마다 반응 속도가 달라 들쭉날쭉해요"],["**Apple Home(애플 홈)**","사생활 보안, 쓰기 편한 화면","인증이 비싸고 문이 좁아요"],["**SmartThings(스마트싱스)**","큰 가전과 **홈 허브(Home Hub)**를 묶었어요","건축, 인테리어 현장과의 협업이 약해요"],["**LG ThinQ(LG 씽큐)**","가전 자체 완성도","다른 회사 기기, 센서로 넓히기가 약해요"]]},{"kind":"points","head":"이 쪽의 새 용어","items":["**Matter(매터)**: 회사가 달라도 기기끼리 말이 통하게 하는 공통 약속이에요. 구글과 삼성의 강점에 나와요.","**멀티모달(Multimodal)**: 말, 손짓, 화면 터치를 한꺼번에 알아듣는 AI 방식이에요.","**MFi(Made for iPhone/iPad/iPod)**: 애플 기기와 짝이 되려면 받아야 하는 인증 도장이에요.","서드파티: 플랫폼 회사가 아닌 다른 회사 제품이에요."]},{"kind":"check","q":"'멀티모달(Multimodal) AI'의 뜻은?","choices":["음성, 제스처, 터치 같은 여러 입력을 함께 처리하는 AI","한 가지 기기만 제어하는 AI","전기를 적게 쓰는 AI","인터넷 없이만 동작하는 AI"],"a":0,"why":"모달은 입력의 형태예요. 여러 형태를 동시에 받아들이는 방식이 멀티모달이에요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"낱말과 숫자 정리","items":["로컬 제어: 인터넷 서버를 거치지 않고 집 안에서 바로 기기를 제어하는 것이에요.","**MFi(Made for iPhone/iPad/iPod)**는 애플의 공식 주변기기 품질인증이에요. 연회비 99달러에 기기 하나마다 로열티가 붙어요.","B2B는 회사와 회사 사이 거래예요. 삼성은 건설사, 인테리어 업체와의 연계가 약하다는 말이에요.","LG는 2024년 아톰(Athom) 지분 80%를 인수했어요."]}],"pass4":[{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 1번","q":"스피커, 디스플레이, 카메라, 온도조절기 등 자체 기기와 다양한 제조사 IoT 기기를 한 플랫폼에서 연동하고, 자연어 명령과 AI로 생태계를 넓히는 IoT 플랫폼 사례는? (① 모비우스 ② 테슬라 ③ 구글 ④ 제너럴 일렉트릭)","qko":"여러 회사 기기를 한데 묶고 말로 부리는 AI 플랫폼 회사를 고르는 문제예요.","solve":["슬라이드의 Google Home 강점: 개방형 생태계, 멀티모달 AI 연동, 방대한 서드파티 호환성이에요.","지문의 '다양한 제조사 기기 연동'이 서드파티 호환성, '자연어 명령과 AI'가 AI 연동과 겹쳐요.","모비우스는 전자부품연구원(KETI)이 만든 개방형 IoT 플랫폼이라 자체 스피커, 카메라를 가진 기업 사례가 아니에요."],"answer":"③ 구글(Google)의 사물인터넷 플랫폼"},{"kind":"check","q":"Apple Home의 '한계'로 슬라이드에 적힌 것은?","choices":["고가의 MFi 인증 장벽과 폐쇄적 생태계","약한 프라이버시 보안","Matter 표준 미지원으로 인한 파편화","대형 가전 부족"],"a":0,"why":"애플은 보안이 오히려 강점이에요. 한계는 비싼 인증과 닫힌 생태계예요."},{"kind":"check","q":"LG가 아톰(Athom) 지분을 인수한 목적으로 슬라이드에 적힌 것은?","choices":["오픈 생태계 약점 정면 돌파","TV 셋톱 사업 확대","MFi 인증 획득","RS-485 월패드 생산"],"a":0,"why":"LG의 한계가 오픈 생태계 확장성이라, Homey 개발사를 사서 약점을 메우려는 시도예요."},{"kind":"warn","head":"강점과 한계를 뒤바꾸기 쉬워요","items":["구글: 강점 개방성, 한계 로컬 제어 편차. 애플: 강점 보안, 한계 폐쇄성.","삼성: 강점 가전과 허브, 한계 현장 B2B. LG: 강점 가전 완성도, 한계 오픈 생태계."]}],"pass5":[{"kind":"points","head":"실기 가이드북 2권, 1-1 지능형홈 요건분석 #3 서비스 모델 선정","items":["스마트싱스, 홈킷, 구글홈은 'IoT 클라우드 모델'로 분류돼요. 대다수 제조업체가 이 모델을 써요.","장점: 서비스 제공자가 기기 종류와 상관없이 여러 스마트홈 서비스를 개발할 수 있어요.","단점: 작동 딜레이가 생길 수 있고, 플랫폼 서버에 문제가 나면 먹통이 돼요.","서로 다른 IoT 클라우드에 묶인 기기끼리의 협업 서비스에는 제한이 있어요. 그래서 앞으로 Matter와의 연결성을 고려해 모델을 고르라고 해요."]},{"kind":"check","q":"실기 가이드북에서 구글홈, 스마트싱스가 속한다고 한 서비스 모델은?","choices":["IoT 클라우드 모델","스마트게이트웨이 모델","하이브리드 모델","RS-485 모델"],"a":0,"why":"제조사 서버(클라우드)를 거쳐 제어하는 모델이라, 서버 장애 때 먹통이 되는 약점이 있어요."}],"walk":{"head":{"b":[0.0681,0.1116,0.6819,0.0666],"c":[0.034,0.0956,0.7501,0.0986],"r":10.7588,"img":"img/I1/walk/p012_h.jpg"},"parts":[{"b":[0.077,0.2,0.417,0.267],"c":[0.0561,0.184,0.4587,0.299],"r":2.1696,"img":"img/I1/walk/p012_30_01.jpg","say":"구글: 강점은 Matter 표준 지원 개방형 생태계, 멀티모달 AI 연동, 방대한 서드파티 호환성. 한계는 하드웨어 제어 파편화, 제조사 간 반응속도, 안정성 편차로 일관된 로컬 제어 경험 부족이에요."},{"b":[0.509,0.2,0.417,0.267],"c":[0.4882,0.184,0.4587,0.299],"r":2.1696,"img":"img/I1/walk/p012_30_02.jpg","say":"애플: 강점은 강력한 프라이버시 보안, 프리미엄 UX, 홈앱 중심 직관적 제어. 한계는 고가의 인증 장벽(MFi, 연회비 99달러에 개당 로열티), 폐쇄적 생태계로 제한된 기기 선택지예요."},{"b":[0.077,0.485,0.417,0.345],"c":[0.0561,0.4677,0.4587,0.3795],"r":1.7094,"img":"img/I1/walk/p012_30_03.jpg","say":"삼성: 강점은 대형 가전과 허브 결합, 개방형 Matter 표준 적극 수용, 폭넓은 인지도. 한계는 건축, 인테리어 마감 현장과의 긴밀한 B2B 연계 설계 부족이에요."},{"b":[0.509,0.485,0.417,0.212],"c":[0.4882,0.469,0.4587,0.244],"r":2.6586,"img":"img/I1/walk/p012_30_04.jpg","say":"LG: 강점은 프리미엄 가전 자체의 압도적 완성도와 가전 중심 연동 시나리오. 한계는 오픈 생태계 확장성과 독립형 IoT 센서 생태계 구축이에요."},{"b":[0.509,0.702,0.417,0.128],"c":[0.4882,0.686,0.4587,0.16],"r":4.0544,"img":"img/I1/walk/p012_30_05.jpg","say":"LG 최근 동향: 2024년 네덜란드 스마트홈 기업 아톰(Athom, 'Homey' 개발사) 지분 80% 인수. 오픈 생태계 약점을 정면 돌파하려는 시도예요."}]}},{"p":13,"title":"1.1.6 글로벌 플랫폼 생태계 분석 2: 전문 브랜드 및 스타트업 생태계","terms":["KNX","Zigbee","Matter","Home Assistant"],"pass1":[{"kind":"say","lines":["큰 회사 말고도 한 분야를 깊게 판 회사들이 있어요."]},{"kind":"points","head":"네 곳을 한 줄씩","items":["융: 독일의 아주 비싸고 튼튼한 벽 스위치 회사예요.","아카라: 값싼 센서를 많이 파는 회사예요.","고퀄: 우리나라 집에 맞춘 스위치와 조명을 만들어요.","스타트업: 누구나 고쳐 쓰는 공개 프로그램으로 자유롭게 자동화를 만들어요."]}],"pass2":[{"kind":"compare","head":"네 곳 강점과 한계","cols":["브랜드","강점","한계"],"rows":[["융(Jung, 독일)","고급 스위치와 **KNX** 유선의 안정성","아주 비싸고 무선으로 넓히기 어려워요"],["아카라(Aqara, 중국 기반)","싼값에 좋은 센서, Matter 호환","중국 서버 연동이라 보안, 사생활 걱정"],["고퀄(Gowell, 국내)","우리 집에 맞춘 **Zigbee(지그비)** 스위치, 조명","AI 대규모 연산 생태계로 넓히기 어려워요"],["스마트홈 스타트업","**Home Assistant(홈 어시스턴트)** 같은 오픈소스로 자유로운 자동화","회사가 오래갈지 불확실, 공식 AS 부족"]]},{"kind":"points","head":"이 쪽의 새 용어","items":["**KNX**: 독일 고급 스위치가 쓰는 튼튼한 유선 건물 제어 방식이에요.","**Home Assistant(홈 어시스턴트)**: 누구나 고쳐 쓸 수 있는 무료 공개 스마트홈 프로그램이에요. 강의 계획의 HA가 이것이에요.","오픈소스: 프로그램 설계도(소스)가 공개되어 누구나 고쳐 쓸 수 있는 것이에요.","**Matter(매터)** 호환: 회사가 달라도 연동되는 공통 약속을 지킨다는 뜻이에요."]},{"kind":"check","q":"'KNX'를 쓰는 브랜드와 그 방식이 바르게 짝지어진 것은?","choices":["융(Jung), 유선","아카라(Aqara), 무선","고퀄(Gowell), Zigbee","스타트업, 오픈소스"],"a":0,"why":"융은 건축 마감재 수준 수동 스위치와 유선(KNX)의 안정성이 강점이에요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"12쪽과 13쪽을 한 번에","items":["빅테크, 가전(12쪽): 구글, 애플, 삼성, LG.","전문 브랜드, 스타트업(13쪽): 융, 아카라, 고퀄, 스타트업.","유선 쪽 강자는 융(**KNX**), 무선 센서 가성비는 아카라, 국내 인테리어 밀착은 고퀄(**Zigbee(지그비)**)이에요.","홈킷(HomeKit)은 애플의 스마트홈 체계 이름이에요."]}],"pass4":[{"kind":"check","q":"\"중국 서버 연동에 따른 국내 소비자의 보안, 프라이버시 우려\"가 한계인 곳은?","choices":["아카라(Aqara)","융(Jung)","고퀄(Gowell)","애플(Apple Home)"],"a":0,"why":"아카라는 중국 기반 글로벌 IoT 브랜드예요. 센서 가성비가 강점이에요."},{"kind":"check","q":"국내 주거 환경 맞춤형 Zigbee 스위치, 조명과 인테리어 B2B 밀착이 강점인 곳은?","choices":["고퀄(Gowell)","아카라(Aqara)","LG ThinQ","융(Jung)"],"a":0,"why":"고퀄은 국내 스마트홈 전문 브랜드예요. 한계는 AI 대규모 연산 생태계 확장이에요."},{"kind":"warn","head":"헷갈리는 점","items":["융은 무선이 아니라 유선(KNX)이 강점이에요. 무선 확장성은 오히려 한계예요.","스타트업의 한계는 기술이 아니라 회사가 오래갈지, 공식 AS가 있는지예요."]}],"pass5":[{"kind":"compare","head":"실기 가이드북 2권, 1-1 #3 지능형홈 서비스 모델 세 가지","cols":["모델","예","특징"],"rows":[["스마트게이트웨이 모델","건설사 아파트 유선 플랫폼","아주 안정적, 주차 제어, 엘리베이터 호출 가능, 게이트웨이가 통신 방식을 바꿔 외부 제어"],["IoT 클라우드 모델","스마트싱스, 홈킷, 구글홈","기기 종류와 상관없이 서비스 개발, 딜레이 가능, 서버 문제 시 먹통"],["하이브리드 모델","**Home Assistant(홈 어시스턴트)**(HA)","확장성이 뛰어나 가장 많은 제품 지원, 개인 서버라 반응이 빠름"]]},{"kind":"points","head":"하이브리드 모델(HA)의 약점도 외워요","items":["개발 언어 지식이 없으면 스스로 구축하기 어려워요.","**Zigbee(지그비)**, Z-Wave 같은 통신은 직접 연결이 힘들어 허브 같은 부가 장치가 필요해요."]},{"kind":"check","q":"실기 가이드북에서 '개인 서버를 이용할 수 있어 반응이 빠르다'고 한 모델은?","choices":["하이브리드 모델(홈 어시스턴트)","IoT 클라우드 모델","스마트게이트웨이 모델","IPTV 셋톱 모델"],"a":0,"why":"Home Assistant는 집 안 개인 서버에서 돌아서 반응이 빨라요. 대신 구축 난도가 높아요."}],"walk":{"head":{"b":[0.0681,0.1116,0.7292,0.0666],"c":[0.0316,0.0956,0.8022,0.0986],"r":11.506,"img":"img/I1/walk/p013_h.jpg"},"parts":[{"b":[0.077,0.2,0.417,0.23],"c":[0.0561,0.184,0.4587,0.262],"r":2.476,"img":"img/I1/walk/p013_30_01.jpg","say":"융(Jung, 독일 하이엔드): 강점은 건축 마감재 수준의 최고급 수동 스위치와 유선(KNX) 기반의 높은 안정성. 한계는 초고가 비용, 무선 확장성의 한계, 폐쇄적 시공 구조예요."},{"b":[0.509,0.2,0.417,0.23],"c":[0.4882,0.184,0.4587,0.262],"r":2.476,"img":"img/I1/walk/p013_30_02.jpg","say":"아카라(Aqara, 중국 기반 글로벌 IoT): 강점은 루미(Lumi) 기반의 압도적인 센서 가성비, 홈킷/Matter 호환. 한계는 중국 서버 연동에 따른 국내 소비자의 보안, 프라이버시 우려예요."},{"b":[0.077,0.448,0.417,0.23],"c":[0.0561,0.432,0.4587,0.262],"r":2.476,"img":"img/I1/walk/p013_30_03.jpg","say":"고퀄(Gowell, 국내 스마트홈 전문): 강점은 국내 주거 환경 맞춤형 Zigbee 스위치, 조명과 인테리어 B2B 밀착. 한계는 글로벌 빅테크 수준의 AI 대규모 연산 생태계 확장이에요."},{"b":[0.509,0.448,0.417,0.23],"c":[0.4882,0.432,0.4587,0.262],"r":2.476,"img":"img/I1/walk/p013_30_04.jpg","say":"스마트홈 스타트업(Innovative Startup): 강점은 오픈소스(Home Assistant 등) 기반의 극대화된 유연성과 맞춤형 커스텀 자동화. 한계는 기업 영속성의 불확실성, 공식 AS와 대규모 양산 인프라 부족이에요."}]}},{"p":14,"title":"1.1.7 공간 전문가 관점의 핵심 병목: BM 상세 분석","terms":["Business Model","Lock-in","Architect","User Experience"],"pass1":[{"kind":"analogy","head":"지휘자 없는 오케스트라","scene":"오케스트라에 바이올린, 트럼펫, 드럼 연주자가 다 모였어요. 그런데 지휘자가 없으면 저마다 자기 악보만 크게 연주해요. 소리는 크지만 노래 한 곡이 되지 않아요. 지금 스마트홈 시장이 이 모습이에요.","map":[["각자 연주하는 사람들","통신사, 건설사, 제조사, 인테리어"],["자기 악보만 보기","각자 돈 버는 방식만 챙기기"],["지휘자","지능형 공간 Architect"]]},{"kind":"figure","head":"아무도 맡지 않은 가운데 칸","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect class=\"n\" x=\"20\" y=\"20\" width=\"130\" height=\"50\" rx=\"2\"/><text class=\"tl\" x=\"85\" y=\"51\" font-size=\"15\" text-anchor=\"middle\">통신사: 회선<\/text><rect class=\"n\" x=\"330\" y=\"20\" width=\"130\" height=\"50\" rx=\"2\"/><text class=\"tl\" x=\"395\" y=\"51\" font-size=\"15\" text-anchor=\"middle\">건설사: 분양<\/text><rect class=\"n\" x=\"20\" y=\"200\" width=\"130\" height=\"50\" rx=\"2\"/><text class=\"tl\" x=\"85\" y=\"231\" font-size=\"15\" text-anchor=\"middle\">제조사: 판매<\/text><rect class=\"n\" x=\"330\" y=\"200\" width=\"130\" height=\"50\" rx=\"2\"/><text class=\"tl\" x=\"395\" y=\"231\" font-size=\"15\" text-anchor=\"middle\">인테리어: 마감<\/text><rect class=\"hl b2\" x=\"165\" y=\"100\" width=\"150\" height=\"70\" rx=\"3\"/><text class=\"tb b2\" x=\"240\" y=\"130\" font-size=\"16\" text-anchor=\"middle\">공간 전체 UX<\/text><text class=\"tm b2\" x=\"240\" y=\"155\" font-size=\"14\" text-anchor=\"middle\">아무도 안 맡은 빈칸<\/text><rect class=\"n2 b3\" x=\"175\" y=\"185\" width=\"130\" height=\"36\" rx=\"2\"/><text class=\"tl b3\" x=\"240\" y=\"209\" font-size=\"15\" text-anchor=\"middle\">Architect<\/text><\/svg>","caption":"네 업종이 각자 일하고, 가운데 공간 전체 경험은 비어 있어요.","builds":3}],"pass2":[{"kind":"points","head":"먼저 용어","items":["**비즈니스 모델(Business Model)**: 회사가 돈을 버는 방법이에요. 줄여서 BM이에요.","회사는 돈 버는 일에 집중하니, 그 밖의 일은 잘 안 챙겨요. 그게 병목이에요.","병목: 병의 목처럼 좁아서 전체 흐름이 막히는 곳이에요."]},{"kind":"compare","head":"네 업종이 못 챙기는 것","cols":["업종","돈 버는 방식","빠진 것"],"rows":[["통신사","가입자 **락인(Lock-in)**과 월 요금","집 안 공간과 사는 사람의 생활 방식"],["건설사","아파트 분양과 한꺼번에 짓기","입주민 한 사람 한 사람의 요구"],["제조사","기기를 많이 팔기","여러 브랜드를 엮은 공간 전체 서비스"],["인테리어","마감 공사","전기, 무선, AI를 도면에서 합치는 공학 실력"]]},{"kind":"check","q":"'비즈니스 모델(Business Model)'의 뜻은?","choices":["회사가 돈을 버는 방법","건물 설계 도면","무선 통신 규격","AI 학습 방식"],"a":0,"why":"BM은 수익을 내는 구조예요. 업종마다 BM이 달라 공간 전체 경험을 아무도 책임지지 않아요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"낱말 풀이","items":["트래픽: 통신망을 오가는 데이터 양이에요. 통신사는 이것으로 돈을 벌어요.","턴키: 열쇠만 돌리면 되게 한꺼번에 지어 넘기는 계약이에요.","후시공: 건물이 다 지어진 뒤에 들어가는 공사예요.","이종 브랜드: 서로 다른 회사 제품이에요. UX는 **거주자 경험(User Experience)**이에요."]}],"pass4":[{"kind":"check","q":"인테리어 BM의 한계로 슬라이드에 적힌 것은?","choices":["L1 전기, L3 무선, L4 AI를 도면에서 통합 설계할 공학 역량 부족","가입자 락인에만 집중","1,000세대 단위 최저가 입찰","단품 판매량 극대화"],"a":0,"why":"인테리어는 공간 기획은 탁월하지만 시각적 마감에 치우쳐요. 나머지 보기는 통신사, 건설사, 제조사 이야기예요."},{"kind":"check","q":"\"1,000세대 단위 일괄 시공과 최저가 입찰\" 때문에 개인 맞춤 요구를 못 담는 업종은?","choices":["건설사(Builder)","통신사(Telco)","제조사(Manufacturer)","인테리어(Interior)"],"a":0,"why":"분양, 준공 턴키 BM이라 한꺼번에 싸게 짓는 구조예요."},{"kind":"english","head":"답안 문장: 15쪽 Q3과 같은 답","en":"시장의 공백을 채우는 핵심 전문가는 거주자 UX 관점에서 전기, 공간, 무선, AI 기술을 도면 위에서 통합 지휘하는 '지능형 공간 Architect'이다.","ko":"통신사, 건설사, 제조사, 인테리어 BM의 한계 때문에 공간 전체 UX를 맡는 주체가 비어 있어요.","tip":"'네 업종의 빈칸을 지휘자가 채운다'로 기억해요."}],"pass5":[],"walk":{"head":{"b":[0.0681,0.111,0.7362,0.0722],"c":[0.0313,0.095,0.8098,0.1042],"r":10.9908,"img":"img/I1/walk/p014_h.jpg"},"parts":[{"b":[0.077,0.198,0.418,0.172],"c":[0.0561,0.182,0.4598,0.204],"r":3.1876,"img":"img/I1/walk/p014_30_01.jpg","say":"통신사(Telco), 회선/트래픽 BM: 가입자 락인(Lock-in)과 월정액 회선 수익에 최우선 집중. 세대 내부 공간 맥락이나 거주자별 라이프스타일 디자인에는 개입하기 어려워요."},{"b":[0.507,0.198,0.419,0.172],"c":[0.4861,0.182,0.4609,0.204],"r":3.1952,"img":"img/I1/walk/p014_30_02.jpg","say":"건설사(Builder), 분양/준공 턴키 BM: 1,000세대 단위 일괄 시공과 최저가 입찰 관행. 입주민 개인의 맞춤형 무선 인프라와 AI 케어 요구를 반영할 수 없어요."},{"b":[0.077,0.386,0.418,0.17],"c":[0.0561,0.37,0.4598,0.202],"r":3.2191,"img":"img/I1/walk/p014_30_03.jpg","say":"제조사(Manufacturer), 기기 판매 BM: 개별 하드웨어(가전, 디바이스) 단품 판매량 극대화에 집중. 이종 브랜드 간 공간 전체 서비스를 엮는 통합 UX 설계가 결여돼요."},{"b":[0.507,0.386,0.419,0.17],"c":[0.4861,0.37,0.4609,0.202],"r":3.2268,"img":"img/I1/walk/p014_30_04.jpg","say":"인테리어(Interior), 후시공 마감 BM: 거주자 맞춤 공간 기획은 탁월하지만 시각적 마감에 편중. L1 전기, L3 무선 통신, L4 AI 자동화를 도면에서 통합 설계할 공학 역량이 부족해요."},{"b":[0.077,0.568,0.849,0.122],"c":[0.0345,0.5347,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p014_30_05.jpg","say":"인사이트: 공간 UX 케어를 통합 추진하는 주체가 비어 있어요. 공간 디자이너가 총괄자(Architect)로서 핵심 위상을 어떻게 확보할지 묻고 있어요."}]}},{"p":15,"title":"1.1강 CHECKPOINT","terms":["Manual Control","App Fragmentation","AI@Home","Architect"],"pass1":[{"kind":"say","lines":["1.1강 복습 문제 세 개예요.","답을 손으로 가리고 먼저 말해 본 뒤 확인해요."]},{"kind":"recap","items":["스마트홈이 막힌 까닭: 매번 내가 시켜야 하고, 앱이 회사마다 따로였어요.","지금 할 일: 오늘의 무선 기술을 튼튼히 알고, 스스로 움직이는 집을 목표로 삼아요.","시장의 빈칸을 채우는 사람: 네 층을 지휘하는 지능형 공간 Architect예요."]}],"pass2":[{"kind":"points","head":"문제마다 돌아가 볼 쪽","items":["Q1 정착 한계: 9쪽 **기기 중심의 수동 제어(Manual Control)**, **브랜드별 앱 파편화(App Fragmentation)**","Q2 올바른 시각: 11쪽 세대 비교표와 인사이트","Q3 핵심 전문가: 14쪽 BM 병목과 **지능형 공간 Architect**"]},{"kind":"check","q":"Q2의 답에서 '기본 지식'으로 삼으라고 한 것은?","choices":["안정적인 2세대 실무 지식","1세대 RS-485 배선 기술만","AI 알고리즘 코딩","IPTV 셋톱 영업"],"a":0,"why":"지금 시장은 2세대 무선 IoT 위에 AI를 얹는 전환기라서, 2세대를 기본으로 **지능형 홈(AI@Home)**을 지향해요."}],"pass3":[{"kind":"look","walked":1}],"pass4":[{"kind":"check","q":"Q1 답의 두 핵심어로 알맞은 조합은?","choices":["수동 제어 구조, 앱 파편화","락인, 사은품","Matter, Thread","분양, 최저가 입찰"],"a":0,"why":"**기기 중심의 수동 제어(Manual Control)**와 **브랜드별 앱 파편화(App Fragmentation)**예요."},{"kind":"check","q":"Q3의 답 '지능형 공간 Architect'가 하는 일은?","choices":["전기, 공간, 무선, AI를 도면 위에서 통합 지휘","전선을 직접 결선","AI 알고리즘만 개발","통신 회선 개통"],"a":0,"why":"직접 시공하는 사람이 아니라 네 기술을 지휘하는 통합 기획자예요. 32쪽에서 다시 나와요."}],"pass5":[],"walk":{"head":{"b":[0.0681,0.1116,0.2642,0.0666],"c":[0.0549,0.0956,0.2907,0.0986],"r":4.1695,"img":"img/I1/walk/p015_h.jpg"},"parts":[{"b":[0.077,0.21,0.849,0.115],"c":[0.0345,0.1732,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p015_30_01.jpg","say":"Q1 정착 못 한 핵심 요인. A: 앱이나 음성으로 일일이 명령해야 하는 수동 제어 구조와 제조사별 전용 앱의 파편화 등"},{"b":[0.077,0.354,0.849,0.115],"c":[0.0345,0.3172,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p015_30_02.jpg","say":"Q2 AI@Home과 무선 IoT 생태계를 보는 올바른 시각. A: 안정적인 2세대 실무 지식을 기본으로 삼고 AI가 자율 조율하는 AI@Home의 가치를 지향하는 것 등"},{"b":[0.077,0.497,0.849,0.114],"c":[0.0345,0.4597,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p015_30_03.jpg","say":"Q3 BM 한계로 생긴 공백을 채우는 전문가. A: 거주자 UX 관점에서 전기, 공간, 무선, AI 기술을 도면 위에서 통합 지휘하는 '지능형 공간 Architect'"}]}},{"p":16,"title":"[1.2강] 지능형 공간의 재정의와 4대 가치 (R-BD)","terms":["Home Network","Connected","Autonomous","4 Core Values of AI@Home Design","Resident-Experience Backward Design"],"pass1":[{"kind":"say","lines":["1.2강은 '똑똑한 공간이 무엇인가'를 다시 정해요.","옛 아파트 방식이 왜 모자란지 보고, 장면 세 개로 느껴 봐요.","그다음 네 가지 약속을 배우고, 사는 사람의 기분에서 거꾸로 설계하는 방법으로 끝내요."]}],"pass2":[{"kind":"points","head":"일곱 조각을 용어로","items":["1.2.1~1.2.2: 아파트 **지능형 홈네트워크(Home Network)**의 본질과 한계","1.2.3: 장면으로 이해하는 세 가지 핵심 시나리오","1.2.4: **연결(Connected)**과 **자율(Autonomous)**의 차이","1.2.5~1.2.6: **지능형홈 설계 4대 가치(4 Core Values of AI@Home Design)**, 편의, 안전, 쾌적, 절감","1.2.7: **거주자 경험 역산 설계(Resident-Experience Backward Design)**, 줄여서 R-BD"]}],"pass3":[{"kind":"look","walked":1}],"pass4":[{"kind":"check","q":"1.2강에서 배우는 지능형 공간의 4대 가치가 아닌 것은?","choices":["속도","편의","안전","절감"],"a":0,"why":"4대 가치는 편의, 안전, 쾌적, 절감이에요."}],"pass5":[],"walk":{"head":{"b":[0.0696,0.111,0.5431,0.0722],"c":[0.0425,0.095,0.5974,0.1042],"r":8.1081,"img":"img/I1/walk/p016_h.jpg"},"parts":[{"b":[0.093,0.222,0.471,0.111],"c":[0.0695,0.206,0.5181,0.143],"r":5.1239,"img":"img/I1/walk/p016_30_01.jpg","say":"1.2.1 본질과 패러다임 격차, 1.2.2 구조적 한계와 패러다임 격차. 둘 다 지능형홈네트워크 이야기예요."},{"b":[0.093,0.364,0.486,0.111],"c":[0.0687,0.348,0.5346,0.143],"r":5.287,"img":"img/I1/walk/p016_30_02.jpg","say":"1.2.3 3대 핵심 시나리오, 1.2.4 '연결(Connected)'과 '자율(Autonomous)'의 차이예요."},{"b":[0.093,0.503,0.429,0.113],"c":[0.0716,0.487,0.4719,0.145],"r":4.6026,"img":"img/I1/walk/p016_30_03.jpg","say":"1.2.5 편의와 안전, 1.2.6 쾌적과 절감. 4대 가치를 두 쪽에 둘씩 나눠요."},{"b":[0.093,0.644,0.371,0.042],"c":[0.0744,0.61,0.4081,0.11],"r":5.2468,"img":"img/I1/walk/p016_30_04.jpg","say":"1.2.7 거주자 경험 역산 설계(R-BD) 방법론이에요."}]}},{"p":17,"title":"1.2.1 지능형홈네트워크의 본질과 패러다임 격차","terms":["Wall Pad","RS-485","Home Network"],"pass1":[{"kind":"say","lines":["아파트 벽에 붙은 집 조종 화면을 본 적 있나요? 월패드라고 불러요.","옛날 것은 버튼 패널, 요즘 것은 휴대폰처럼 터치 화면이에요.","화면은 좋아졌지만, 벽의 조종판을 중심으로 집을 다루는 뼈대는 그대로예요."]}],"pass2":[{"kind":"compare","head":"옛 월패드와 새 월패드","cols":["구분","과거 구형","현재 최신형"],"rows":[["연결","**RS-485** 유선 줄","슬라이드에 따로 적혀 있지 않아요"],["조작","벽의 버튼 패널을 손으로","터치 화면, 영상, 음악 연동"],["목적","준공 뒤 하자관리, 단지 중앙 통제","더 편한 화면과 멀티미디어"]]},{"kind":"points","head":"이 쪽 용어","items":["**세대단말기(Wall Pad)**: 아파트 벽면에서 방범, 조명, 난방 같은 설비를 통합 제어하는 장치예요.","**RS-485**: 월패드와 설비를 잇는 옛날식 유선 줄이에요.","**지능형 홈네트워크(Home Network)**: 아파트 단지와 우리 집 설비를 잇는 줄과 장비 전체예요."]},{"kind":"check","q":"구형 월패드가 만들어진 주된 목적은?","choices":["준공 후 하자관리와 단지 중앙 통제","거주자 개인 맞춤 AI 케어","기기 판매량 늘리기","Matter 표준 인증"],"a":0,"why":"왼쪽 카드 설명이에요. 사는 사람보다 관리하는 쪽에 맞춘 출발이에요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"정의를 정확히","items":["용어해설집의 **세대단말기(Wall Pad)**: 세대 내 조명, 환기, 난방 등 홈네트워크 연동 설비를 벽면 중앙 장치에서 통합 제어, 모니터링하는 세대 내 종합 제어 단말기예요.","기술기준의 세대단말기: 세대 및 공용부 설비의 기능과 성능을 제어하고 확인하는 사용자 인터페이스 장치예요.","UI는 사용자 인터페이스, 사람이 기계를 다루는 화면과 버튼이에요.","준공은 공사를 마치는 것, 하자관리는 공사 뒤 고장이나 결함을 고치는 일이에요."]}],"pass4":[{"kind":"warn","head":"시험에서 헷갈리는 점","items":["최신형 월패드의 개선점은 '터치 UI와 멀티미디어'예요. 사는 사람을 알아채는 자율 기능이 아니에요.","**RS-485**는 무선이 아니라 유선이에요. 2026 제3회 18번에서 '무선이 아닌 것'으로 나왔어요."]},{"kind":"check","q":"\"최신형 스마트 월패드는 거주자 맥락을 인지해 스스로 조율한다.\" 슬라이드와 맞나요?","choices":["맞지 않아요","맞아요"],"a":0,"why":"슬라이드는 최신형의 개선점을 고도화된 터치 UI와 멀티미디어 연동으로만 적어요. 자율 조율은 AI@Home의 특징이에요."}],"pass5":[],"walk":{"head":{"b":[0.0681,0.1116,0.5231,0.0666],"c":[0.0419,0.0956,0.5754,0.0986],"r":8.253,"img":"img/I1/walk/p017_h.jpg"},"parts":[{"b":[0.077,0.194,0.414,0.059],"c":[0.0563,0.1685,0.4554,0.11],"r":5.8549,"img":"img/I1/walk/p017_30_01.jpg","say":"왼쪽 제목: 과거 구형 월패드(RS-485 유선 기반)"},{"b":[0.093,0.265,0.384,0.38],"c":[0.0738,0.246,0.4224,0.418],"r":1.4291,"img":"img/I1/walk/p017_30_02.jpg","say":"사진 자리가 비어 대체 글자 '구형 월패드'만 보여요. 원본 파일에서 그림이 빠졌어요."},{"b":[0.077,0.657,0.414,0.051],"c":[0.0563,0.6275,0.4554,0.11],"r":5.8549,"img":"img/I1/walk/p017_30_03.jpg","say":"준공 후 하자관리 및 단지 중앙 통제 목적의 유선 수동 패널이에요."},{"b":[0.511,0.194,0.415,0.059],"c":[0.4903,0.1685,0.4565,0.11],"r":5.8691,"img":"img/I1/walk/p017_30_04.jpg","say":"오른쪽 제목: 현재 최신형 스마트 월패드"},{"b":[0.511,0.657,0.415,0.081],"c":[0.4903,0.641,0.4565,0.113],"r":5.7132,"img":"img/I1/walk/p017_30_05.jpg","say":"고도화된 터치 UI와 멀티미디어 연동 기능을 제공하는 최신 월패드 시스템이에요."}]}},{"p":18,"title":"1.2.2 지능형홈네트워크의 구조적 한계와 패러다임 격차","terms":["Home Network","단지서버","Wall Pad","AI@Home","Home Gateway"],"pass1":[{"kind":"say","lines":["아파트 홈네트워크는 처음부터 '관리하기 편한 집'을 목표로 만들었어요.","지능형 공간은 '사는 사람을 돌보는 집'이 목표예요. 출발점이 달라요."]},{"kind":"figure","head":"아파트 홈네트워크의 뼈대","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect class=\"n\" x=\"160\" y=\"15\" width=\"160\" height=\"44\" rx=\"2\"/><text class=\"tl\" x=\"240\" y=\"43\" font-size=\"16\" text-anchor=\"middle\">단지 큰 컴퓨터<\/text><line class=\"e2 b2\" x1=\"240\" y1=\"59\" x2=\"240\" y2=\"99\"/><polygon class=\"arrow b2\" points=\"233,95 240,107 247,95\"/><rect class=\"n2 b2\" x=\"160\" y=\"107\" width=\"160\" height=\"44\" rx=\"2\"/><text class=\"tl b2\" x=\"240\" y=\"135\" font-size=\"16\" text-anchor=\"middle\">벽 조종판<\/text><line class=\"e2 b3\" x1=\"240\" y1=\"151\" x2=\"80\" y2=\"200\"/><line class=\"e2 b3\" x1=\"240\" y1=\"151\" x2=\"240\" y2=\"200\"/><line class=\"e2 b3\" x1=\"240\" y1=\"151\" x2=\"400\" y2=\"200\"/><rect class=\"n3 b3\" x=\"30\" y=\"200\" width=\"100\" height=\"40\" rx=\"2\"/><text class=\"tl b3\" x=\"80\" y=\"226\" font-size=\"15\" text-anchor=\"middle\">방범<\/text><rect class=\"n3 b3\" x=\"190\" y=\"200\" width=\"100\" height=\"40\" rx=\"2\"/><text class=\"tl b3\" x=\"240\" y=\"226\" font-size=\"15\" text-anchor=\"middle\">조명<\/text><rect class=\"n3 b3\" x=\"350\" y=\"200\" width=\"100\" height=\"40\" rx=\"2\"/><text class=\"tl b3\" x=\"400\" y=\"226\" font-size=\"15\" text-anchor=\"middle\">난방<\/text><\/svg>","caption":"단지 전체를 관리하는 컴퓨터가 집마다 벽 조종판을 거쳐 설비를 줄줄이 다뤄요.","builds":3}],"pass2":[{"kind":"steps","head":"아파트 시스템 백본을 위에서 아래로","steps":["**단지서버**: 아파트 단지 전체를 관리하는 큰 컴퓨터예요.","단지 인프라: 주차게이트, CCTV, 로비폰이 단지서버와 연동돼요.","**세대단말기(Wall Pad)**: 집마다 벽에 붙은 조종판이에요.","세대 설비: 월패드 중심으로 방범, 조명, 난방을 줄줄이 제어해요."],"answer":"단지서버 - 월패드 - 세대 내 설비가 **지능형 홈네트워크(Home Network)**의 백본이에요."},{"kind":"compare","head":"두 가지 분석","cols":["분석","어느 쪽 한계","무엇이 문제"],"rows":[["기술적 분석","공급 측(만드는 쪽)","센서가 몇 종류 없고 유선망이 닫혀 있어 입주 뒤 개인 맞춤 무선 확장이 안 돼요"],["가치적 분석","수요 측(사는 쪽) UX","정해진 일괄 시나리오만 있어 사는 사람이 체감하는 자율 자동화가 어려워요"]]},{"kind":"check","q":"'백본(backbone)'을 이 쪽에서 가장 잘 풀어 쓴 말은?","choices":["시스템 전체를 받치는 중심 줄기","벽에 붙은 스위치 하나","휴대폰 앱","AI 학습 데이터"],"a":0,"why":"백본은 등뼈라는 뜻이에요. 단지서버 - 월패드 - 설비로 이어지는 중심 줄기예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"정의와 낱말","items":["기술기준의 **단지서버**: 홈네트워크 설비를 총괄 관리하고, 여기서 생기는 데이터의 저장, 관리, 서비스를 제공하는 장비예요.","CCTV는 폐쇄회로 카메라, 로비폰은 공동현관 인터폰이에요.","직렬 제어: 월패드 한 곳에서 설비를 줄줄이 이어 제어한다는 말이에요.","공급 측은 만드는 건설사 쪽, 수요 측은 사는 거주자 쪽이에요."]}],"pass4":[{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 9번","q":"「지능형 홈네트워크 설비 설치 및 기술기준」의 '홈네트워크 설비' 정의: (A)의 성능과 주거의 질 향상을 위하여 세대 또는 주택단지 내 기기의 상호 연계로 (B)를 제공하는 설비로, (C)망, (C)장비, (C)사용기기로 구분한다. 알맞은 조합은?","qko":"고시 원문의 빈칸 세 개를 채우는 문제예요.","solve":["이 고시는 주택법에 근거해요. 그래서 (A)는 빌딩이 아니라 주택이에요.","기기를 하나로 묶는 것이 목적이라 (B)는 독립된 서비스가 아니라 통합된 주거서비스예요.","(C)는 홈네트워크예요. 홈네트워크망, 홈네트워크장비, 홈네트워크사용기기로 나눠요."],"answer":"③ (A) 주택 / (B) 통합된 주거서비스 / (C) 홈네트워크"},{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 10번","q":"세대 전유부분에 설치되어 세대 내 홈네트워크 기기를 유무선으로 연결하고, 세대망과 단지망 또는 통신사업자의 기간통신망을 상호 접속하는 장치는? (① 공유기 ② 110블록 ③ 멀티플렉서 ④ 홈 게이트웨이)","qko":"우리 집 네트워크와 단지 네트워크를 이어 주는 장치 이름을 고르는 문제예요.","solve":["이 쪽 백본에서 집(세대)과 단지를 잇는 자리를 떠올려요.","기술기준에서 그 장치를 **홈게이트웨이(Home Gateway)**라고 정의해요.","공유기는 고시에 정의된 장비가 아니고, 110블록은 전화선 단자, 멀티플렉서는 신호를 합치는 장치예요."],"answer":"④ 홈 게이트웨이"},{"kind":"check","q":"**홈게이트웨이(Home Gateway)**가 서로 이어 주는 두 망은?","choices":["세대망과 단지망","Wi-Fi와 Zigbee","전기선과 수도관","TV와 스피커"],"a":0,"why":"세대 전유부분에 설치되어 세대망과 단지망(또는 통신사 기간망)을 상호 접속해요."},{"kind":"english","head":"답안 문장: 구조적 한계","en":"아파트 지능형홈네트워크는 건설사의 유지보수, 중앙통제형 유선 설비에서 출발하여 센서 다양성 부족과 폐쇄적 유선망(공급 측), 고정된 일괄 시나리오(수요 측)의 한계를 가지므로 거주자를 자율 케어하는 AI@Home과 설계 출발점이 다르다.","ko":"공급 측 한계 하나, 수요 측 한계 하나, 출발점 차이 한 줄로 쓰면 돼요.","tip":"'관리하는 집 vs 돌보는 집'."}],"pass5":[{"kind":"points","head":"실기 가이드북 2권, 1-1 #3 스마트게이트웨이 모델","items":["건설사 아파트 유선 플랫폼에서 많이 써요. 이 쪽의 단지서버 - 월패드 구조와 같은 계열이에요.","상당히 안정적이고, 다른 플랫폼에서 어려운 주차 제어, 엘리베이터 호출 같은 일이 돼요.","홈네트워크 안의 스마트게이트웨이가 스마트 기기 정보와 상태를 받아 플랫폼으로 보내고, 플랫폼의 제어 신호를 기기로 다시 보내요.","집 안팎의 서로 다른 통신 프로토콜을 변환해 외부에서 집 기기를 제어하게 해 줘요."]},{"kind":"check","q":"실기 가이드북에서 '주차 제어, 엘리베이터 호출'이 가능한 장점으로 든 서비스 모델은?","choices":["스마트게이트웨이 모델","IoT 클라우드 모델","하이브리드 모델","논허브 모델"],"a":0,"why":"건설사 아파트 유선 플랫폼 기반이라 단지 설비와 연동이 강해요."}],"walk":{"head":{"b":[0.0681,0.1116,0.6069,0.0666],"c":[0.0377,0.0956,0.6676,0.0986],"r":9.5755,"img":"img/I1/walk/p018_h.jpg"},"parts":[{"b":[0.077,0.218,0.849,0.106],"c":[0.0345,0.1767,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p018_30_01.jpg","say":"이슈: 건설사의 유지보수, 중앙통제형 유선 설비와 거주자의 삶을 자율 케어하는 AI@Home 지능형 공간은 설계 출발점 자체가 달라요."},{"b":[0.077,0.351,0.456,0.165],"c":[0.0542,0.335,0.5016,0.197],"r":3.6009,"img":"img/I1/walk/p018_30_02.jpg","say":"아파트 지능형홈 네트워크 시스템 백본: 단지 서버 - 월패드 - 세대 내 설비 연동. 단지 인프라는 주차게이트, CCTV, 로비폰 연동, 세대 백본은 월패드 중심 방범, 조명, 난방 직렬 제어예요."},{"b":[0.304,0.564,0.216,0.04],"c":[0.292,0.529,0.24,0.11],"r":3.0856,"img":"img/I1/walk/p018_30_03.jpg","say":"링크 버튼 '코콤 공식 홈네트워크 시스템 구성도 보기'. 실제 구성도는 링크로 연결돼 있어요."},{"b":[0.554,0.351,0.372,0.126],"c":[0.5354,0.335,0.4092,0.158],"r":3.6627,"img":"img/I1/walk/p018_30_04.jpg","say":"기술적 분석(공급 측 한계): 센서 다양성 부족과 폐쇄적 유선망으로 입주 후 개인 맞춤형 무선 확장이 불가해요."},{"b":[0.554,0.491,0.372,0.127],"c":[0.5354,0.475,0.4092,0.159],"r":3.6396,"img":"img/I1/walk/p018_30_05.jpg","say":"가치적 분석(수요 측 UX): 고정된 일괄 시나리오에 국한되어 거주자 체감형 자율 자동화 구현에 한계가 있어요."}]}},{"p":19,"title":"1.2.3 장면으로 이해하는 지능형 공간: 3대 핵심 시나리오","terms":["Automation Scenario","AI@Home","Trigger","Sensor","Actuator"],"pass1":[{"kind":"say","lines":["이제 똑똑한 공간을 장면으로 느껴 볼 차례예요."]},{"kind":"points","head":"슬라이드에 나온 장면 셋","items":["집에 돌아올 때","잠자리에 들 때","평일 아침 집을 나설 때"]},{"kind":"say","lines":["이렇게 장면마다 미리 묶어 둔 자동 행동을 **자동화 시나리오(Automation Scenario)**라고 해요.","장면이 오면 집이 알아서 움직여요. 내가 스위치를 하나하나 누르지 않아요."]}],"pass2":[{"kind":"points","head":"장면 이름 읽기","items":["개별귀가모드: 귀가, 집에 돌아오는 장면이에요.","개별취침모드: 취침, 잠자리에 드는 장면이에요.","평일출근모드: 평일 아침 출근하는 장면이에요.","모드는 여러 기기의 동작을 한 번에 묶은 설정 묶음이에요."]},{"kind":"steps","head":"자동화 시나리오가 도는 순서 (귀가 장면 예)","steps":["감지: **센서(Sensor)**가 사람이 들어온 것을 느껴요.","전달: 네트워크가 그 신호를 날라요.","판단: 허브와 플랫폼이 '귀가 장면'이라고 판단해요. 이 출발 신호를 **트리거(Trigger)**라고 해요.","실행: 조명 같은 **액추에이터(Actuator)**, 곧 손발 기기가 움직여요."],"answer":"센서가 느끼고, 네트워크가 나르고, 허브와 플랫폼이 판단하고, 기기가 움직여요."},{"kind":"check","q":"'트리거(Trigger)'의 뜻으로 알맞은 것은?","choices":["자동화를 시작하게 만드는 입력 조건","조명을 끄는 스위치 모양","무선 채널 번호","월패드 화면"],"a":0,"why":"방아쇠라는 뜻이에요. '사람이 들어오면'처럼 자동화를 출발시키는 조건이에요."}],"pass3":[{"kind":"look","walked":1},{"kind":"warn","head":"슬라이드에 없는 것","items":["각 모드가 정확히 어떤 기기를 어떻게 움직이는지는 슬라이드에 적혀 있지 않아요.","시뮬레이터 [0-0 자동화]를 실행해서 직접 확인하세요."]}],"pass4":[{"kind":"check","q":"슬라이드의 3대 핵심 시나리오가 아닌 것은?","choices":["주말청소모드","개별귀가모드","개별취침모드","평일출근모드"],"a":0,"why":"세 가지는 개별귀가모드, 개별취침모드, 평일출근모드예요. 시뮬레이터 번호는 [SIM 0-0]이에요."}],"pass5":[{"kind":"steps","head":"실기 가이드북 2권, 1-1 #5 구축 및 자동화: 자동화 3단계","steps":["시작조건(필수): 자동화를 출발시키는 **트리거(Trigger)**예요. 예) 움직임이 감지될 때","조건만족(선택): 추가로 맞아야 하는 조건이에요. 예) 어두우면","동작(필수): 실행될 스마트 기기의 동작이에요. 예) 불을 켜라"],"answer":"\"시작조건일 때 조건만족이 되면 동작을 실행해라.\""},{"kind":"points","head":"자동화가 안 될 때 점검 순서 (같은 쪽)","items":["1. 시작조건은 명확한가?","2. 조건만족과 여러 시작조건의 and/or를 제대로 만족시켰는가?","3. 동작에 이상은 없는가?","'거실에 사람이 있으면 켜고, 없으면 꺼라'는 자동화 두 개(감지될 때 켜기, 감지 안 될 때 끄기)로 나눠 만들어요."]},{"kind":"check","q":"실기 가이드북의 자동화 필수 구성요소 두 가지는?","choices":["시작조건, 동작","조건만족, 동작","시작조건, 조건만족","타이머, 알림"],"a":0,"why":"필수는 시작조건과 동작이고, 조건만족은 선택 요소예요."}],"walk":{"head":{"b":[0.0681,0.1116,0.6438,0.0604],"c":[0.0359,0.0956,0.7082,0.0924],"r":10.8394,"img":"img/I1/walk/p019_h.jpg"},"parts":[{"b":[0.071,0.174,0.257,0.034],"c":[0.0582,0.136,0.2827,0.11],"r":3.6346,"img":"img/I1/walk/p019_30_01.jpg","say":"[SIM 0-0]은 시뮬레이터 실습 번호예요. 자동화 모드 연동 시나리오를 분석해요."},{"b":[0.077,0.226,0.273,0.083],"c":[0.0634,0.21,0.3003,0.115],"r":3.693,"img":"img/I1/walk/p019_30_02.jpg","say":"개별귀가모드"},{"b":[0.365,0.226,0.273,0.083],"c":[0.3514,0.21,0.3003,0.115],"r":3.693,"img":"img/I1/walk/p019_30_03.jpg","say":"개별취침모드"},{"b":[0.651,0.226,0.274,0.083],"c":[0.6373,0.21,0.3014,0.115],"r":3.7065,"img":"img/I1/walk/p019_30_04.jpg","say":"평일출근모드"},{"b":[0.077,0.335,0.849,0.153],"c":[0.0345,0.3172,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p019_30_05.jpg","say":"시뮬레이터 연계: 지능형홈 학습 시뮬레이터(charles-kim79.github.io/aihome_simul)에 접속해 [0-0 자동화]를 실행해 보라고 해요."}]}},{"p":20,"title":"1.2.4 '연결(Connected)'과 '자율(Autonomous)'의 차이","terms":["Smart Home","AI@Home","Connected","Autonomous","AI Cognitive Loop"],"pass1":[{"kind":"say","lines":["스마트홈은 기기를 이어만 두고, 내가 리모컨처럼 조종하는 집이에요.","똑똑한 공간은 집이 스스로 느끼고 판단해서 움직이는 집이에요."]},{"kind":"figure","head":"내가 조종하는 집, 스스로 도는 집","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect class=\"box\" x=\"10\" y=\"20\" width=\"210\" height=\"230\" rx=\"3\"/><text class=\"tb\" x=\"115\" y=\"48\" font-size=\"16\" text-anchor=\"middle\">연결: 내가 조종<\/text><circle class=\"n\" cx=\"55\" cy=\"130\" r=\"24\"/><text class=\"tl\" x=\"55\" y=\"135\" font-size=\"14\" text-anchor=\"middle\">사람<\/text><line class=\"e\" x1=\"79\" y1=\"130\" x2=\"140\" y2=\"130\"/><polygon class=\"arrow\" points=\"138,123 150,130 138,137\"/><rect class=\"n3\" x=\"150\" y=\"108\" width=\"56\" height=\"44\" rx=\"2\"/><text class=\"tl\" x=\"178\" y=\"135\" font-size=\"14\" text-anchor=\"middle\">기기<\/text><text class=\"tm\" x=\"115\" y=\"200\" font-size=\"14\" text-anchor=\"middle\">명령해야 움직여요<\/text><rect class=\"box2 b2\" x=\"260\" y=\"20\" width=\"210\" height=\"230\" rx=\"3\"/><text class=\"tb b2\" x=\"365\" y=\"48\" font-size=\"16\" text-anchor=\"middle\">자율: 스스로 돎<\/text><circle class=\"n2 b2\" cx=\"365\" cy=\"80\" r=\"20\"/><text class=\"tl b2\" x=\"365\" y=\"85\" font-size=\"14\" text-anchor=\"middle\">느낌<\/text><circle class=\"n2 b2\" cx=\"425\" cy=\"165\" r=\"20\"/><text class=\"tl b2\" x=\"425\" y=\"170\" font-size=\"14\" text-anchor=\"middle\">판단<\/text><circle class=\"n2 b2\" cx=\"305\" cy=\"165\" r=\"20\"/><text class=\"tl b2\" x=\"305\" y=\"170\" font-size=\"14\" text-anchor=\"middle\">실행<\/text><line class=\"e2 b2\" x1=\"380\" y1=\"95\" x2=\"413\" y2=\"147\"/><line class=\"e2 b2\" x1=\"405\" y1=\"165\" x2=\"325\" y2=\"165\"/><line class=\"e2 b2\" x1=\"317\" y1=\"147\" x2=\"350\" y2=\"95\"/><text class=\"tm b2\" x=\"365\" y=\"220\" font-size=\"14\" text-anchor=\"middle\">센서 고리가 계속 돌아요<\/text><\/svg>","caption":"왼쪽은 연결, 오른쪽은 자율이에요.","builds":2}],"pass2":[{"kind":"compare","head":"연결과 자율","cols":["구분","**스마트홈(Smart Home)**","**지능형 홈(AI@Home)**"],"rows":[["한 단어","**연결(Connected)**","**자율(Autonomous)**"],["어떻게","기기를 네트워크로 묶고 사람이 직접 수동 제어","센서 고리로 AI가 맥락을 알아채고 스스로 조율"],["출발","사람의 명령","센서가 느낀 상황"]]},{"kind":"points","head":"정의 문장을 둘로 쪼개요","items":["\"가정 내 기기를 연결하고\": 여기까지가 **연결(Connected)**이에요.","\"인공지능 기반으로 조명, 가전 등이 자율적으로 작동하여\": 여기가 **자율(Autonomous)**이에요.","\"개인 맞춤형 서비스를 제공하는 디지털 신 주거환경\": 목표는 사는 사람에게 맞추는 거예요.","자율이 도는 고리가 **AI 인지 루프(AI Cognitive Loop)**예요."]},{"kind":"check","q":"'자율(Autonomous)'을 가장 잘 설명한 것은?","choices":["센서 루프로 AI가 맥락을 인지하고 스스로 조율하는 방식","기기를 네트워크로 묶고 사람이 직접 조종하는 방식","월패드 버튼으로 켜는 방식","통신사 결합상품"],"a":0,"why":"두 번째 보기는 연결(Connected)이에요. 스스로 조율하면 자율이에요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"더 정확히","items":["위 정의 문장은 정부 관계부처 합동 자료(2023년 8월 9일)의 지능형 홈 정의를 인용한 거예요.","맥락: 지금 누가, 어디서, 무엇을 하는지 같은 상황 정보예요.","센서 루프: **센서(Sensor)**가 느낀 값으로 판단하고, 실행 결과를 다시 센서가 느끼는 고리예요.","그래서 **AI 인지 루프(AI Cognitive Loop)**를 AI@Home의 제어 방식이라고 해요(11쪽 표)."]}],"pass4":[{"kind":"check","q":"\"퇴근길에 휴대폰 앱으로 에어컨을 켰다.\" 연결과 자율 중 어느 쪽일까요?","choices":["연결(Connected)","자율(Autonomous)"],"a":0,"why":"사람이 직접 명령했으니 연결이에요. 집이 도착을 알아채고 스스로 켰다면 자율이에요."},{"kind":"english","head":"답안 문장: 연결과 자율","en":"스마트홈은 기기를 네트워크로 묶고 사용자가 직접 수동 제어하는 '연결(Connected)' 방식이고, AI@Home은 센서 루프를 통해 AI가 맥락을 인지하고 스스로 조율하는 '자율(Autonomous)' 방식이다.","ko":"주어(스마트홈, AI@Home), 방식(수동 제어, 스스로 조율), 이름(연결, 자율)을 짝지어 써요.","tip":"'연결은 내가, 자율은 집이'."},{"kind":"warn","head":"거꾸로 쓰기 쉬워요","items":["연결(Connected)은 스마트홈, 자율(Autonomous)은 AI@Home이에요.","필기 기출 분석에서도 '스마트홈(명령 기반 원격 제어, 단순 자동화)과 지능형 홈(AI가 학습, 예측해 선제 제공)의 차이'를 꼭 외우라고 해요."]}],"pass5":[],"walk":{"head":{"b":[0.0681,0.111,0.65,0.0722],"c":[0.0356,0.095,0.715,0.1042],"r":9.7042,"img":"img/I1/walk/p020_h.jpg"},"parts":[{"b":[0.071,0.192,0.854,0.051],"c":[0.0283,0.1226,0.9394,0.1898],"r":6.9996,"img":"img/I1/walk/p020_30_01.jpg","say":"인용 정의: 가정 내 기기를 '연결'하고, 인공지능 기반으로 조명, 가전 등이 '자율적으로 작동'하여 개인 맞춤형 서비스를 제공하는 디지털 신 주거환경"},{"b":[0.077,0.256,0.417,0.174],"c":[0.0561,0.24,0.4587,0.206],"r":3.1491,"img":"img/I1/walk/p020_30_02.jpg","say":"스마트홈 = 연결(Connected): 기기를 네트워크로 묶고 사용자가 직접 수동 제어하는 방식"},{"b":[0.508,0.256,0.418,0.174],"c":[0.4871,0.24,0.4598,0.206],"r":3.1566,"img":"img/I1/walk/p020_30_03.jpg","say":"AI@Home(지능형 공간) = 자율(Autonomous): 센서 루프(Loop)를 통해 AI가 맥락을 인지하고 스스로 조율하는 방식"},{"b":[0.077,0.445,0.849,0.459],"c":[0.0345,0.422,0.9339,0.5049],"r":2.6159,"img":"img/I1/walk/p020_30_04.jpg","say":"그림이 깨져 제목만 보여요. 출처는 '지능형 홈(AI@Home) 구축, 확산 방안, 관계부처 합동(2023.8.9)'이에요."}]}},{"p":21,"title":"1.2.5 지능형 공간의 핵심 가치: 편의와 안전","terms":["4 Core Values of AI@Home Design","Convenience","Safety","mmWave Presence Sensor","비식별 센서","Electrical, Infrastructure Layer","Passive Infrared Sensor","Sensor"],"pass1":[{"kind":"say","lines":["똑똑한 공간이 지켜야 할 약속은 네 가지예요.","이 쪽은 앞의 두 가지, 편함과 안전함이에요."]},{"kind":"analogy","head":"숨결까지 느끼는 감각기관","scene":"눈을 감고 가만히 누워 있어도 옆 사람이 숨 쉬는 건 느낄 수 있어요. 좋은 센서도 그래요. 책을 읽느라 꼼짝 않는 사람의 작은 숨결까지 느끼면, 집은 '아직 사람이 있네' 하고 불을 끄지 않아요. 이 예민한 감각기관이 레이더 센서예요.","map":[["숨결을 느끼는 감각","레이더 센서"],["사람이 있다고 알아챔","재실 감지"],["불을 켜 둠","편의"]]},{"kind":"points","head":"두 가지 약속","items":["**편의(Convenience)**: 스위치를 찾지 않아도 되는 편함이에요.","**안전(Safety)**: 위험을 먼저 막아 주는 든든함이에요."]}],"pass2":[{"kind":"points","head":"편의: 손을 쓸 일을 없애요","items":["수동 조작 삭제: 사람이 들어오면 센서가 알아채 불이 켜져요.","정적 재실 포착: 가만히 책 읽는 사람도 놓치지 않아요. 여기에 **mmWave 재실센서(mmWave Presence Sensor)**를 써요.","미니멀 월: 벽의 스위치 개수를 줄여 벽면 디자인을 깔끔하게 해요."]},{"kind":"points","head":"안전: 먼저 막아요","items":["선제적 물리 차단: 가스나 불이 감지되면 밸브를 잠그고 환기를 돌려요.","비식별 프라이버시: 욕실, 침실에 카메라 없이 레이더로 넘어짐을 알아채요. **비식별 센서**의 좋은 예예요.","비상 인프라: 정전에 대비한 피난 유도 조명과 비상 전원선을 미리 확보해요."]},{"kind":"check","q":"'mmWave 재실센서(mmWave Presence Sensor)'가 편의 가치에서 맡는 일은?","choices":["움직임이 거의 없는 사람도 계속 감지해 불이 꺼지지 않게 해요","가스 밸브를 잠가요","전기 요금을 계산해요","벽 스위치를 늘려요"],"a":0,"why":"미세한 호흡까지 감지해 독서나 휴식 중인 사람을 놓치지 않아요. 그래서 '정적 재실 포착'이에요."}],"pass3":[{"kind":"look","walked":1},{"kind":"compare","head":"편의와 안전 전체 항목","cols":["가치","항목","슬라이드 내용"],"rows":[["**편의(Convenience)**","수동 조작 삭제","스위치 탐색 없이 생체/재실 센싱으로 자동 점등"],["**편의(Convenience)**","정적 재실 포착, 미니멀 월","**mmWave 재실센서(mmWave Presence Sensor)**로 미세 호흡 감지 유지, 스위치 수량 축소"],["**안전(Safety)**","선제적 물리 차단","가스/화재 감지 시 밸브 차단 및 환기 배기 가동"],["**안전(Safety)**","비식별 프라이버시","욕실, 침실에 카메라 없이 레이더로 낙상 감지"],["**안전(Safety)**","비상 인프라","**L1 전기 및 인프라 계층(Electrical, Infrastructure Layer)** 쪽 일. 정전 대비 피난 유도 조명 및 비상 전원선 확보"]]},{"kind":"points","head":"낱말 풀이","items":["재실: 방에 사람이 있는 상태예요. 정적 재실은 움직임 없이 있는 상태예요.","mmWave는 밀리미터파, 아주 짧은 파장의 전파예요. 레이더처럼 쏘아 미세한 움직임을 재요.","낙상은 넘어지거나 떨어지는 사고예요.","선제적은 일이 커지기 전에 먼저 움직인다는 뜻이에요."]}],"pass4":[{"kind":"check","q":"욕실, 침실에서 카메라 없이 레이더로 낙상을 감지하는 항목은 어느 가치에 속할까요?","choices":["안전: 비식별 프라이버시","편의: 미니멀 월","쾌적: 빌트인 센싱","절감: 자율 전력 회수"],"a":0,"why":"위험(낙상)을 막으면서 얼굴을 찍지 않는 비식별 방식이라 안전 가치의 비식별 프라이버시예요."},{"kind":"check","q":"안전 가치의 '비상 인프라'는 4-Layer 중 어느 층 일로 적혀 있나요?","choices":["L1 전기 및 인프라","L2 공간 및 기기 배치","L3 연결 및 네트워크","L4 지능 및 자동화"],"a":0,"why":"슬라이드에 '비상 인프라(L1)'라고 적혀 있어요. 비상 전원선은 전기 층 일이에요."},{"kind":"warn","head":"헷갈리는 점","items":["'미니멀 월'은 안전이 아니라 편의예요. 스위치를 줄여 벽을 정돈해요.","필기 가이드북 1권은 4대 가치를 '안전, 편리, 절감, 쾌적' 순서로 적어요. 이름은 같은 네 가지예요."]}],"pass5":[{"kind":"points","head":"실기 가이드북 2권, 1-1 #1, #2 사례: 스마트 주방 센서 선정","items":["요구: 식탁에 앉으면 식탁등 켜고 앉아 있는 동안 유지, 싱크대에서 일하면 싱크대등 켜기예요.","알맞은 기기는 사람을 감지하는 모션, 동작 감지 센서예요.","주의 1: 모션 감지 영역이 120도라서 감지 각도를 못 맞추면 오작동해요.","주의 2: **PIR 센서(Passive Infrared Sensor)**는 사람이 움직이지 않으면 없는 것으로 보고 오작동해요. 앉아 있는 동안 유지하려면 이 문제를 풀어야 해요."]},{"kind":"check","q":"실기 가이드북이 지적한 PIR 센서의 문제로 '정적 재실 포착'과 이어지는 것은?","choices":["움직이지 않으면 사람이 없는 것으로 간주한다","카메라라서 사생활을 침해한다","유선이라 설치가 어렵다","전기를 너무 많이 쓴다"],"a":0,"why":"그래서 편의 가치의 정적 재실 포착에는 미세 호흡까지 재는 mmWave 재실센서를 써요."}],"walk":{"head":{"b":[0.0681,0.1116,0.5612,0.0666],"c":[0.04,0.0956,0.6173,0.0986],"r":8.854,"img":"img/I1/walk/p021_h.jpg"},"parts":[{"b":[0.089,0.214,0.246,0.081],"c":[0.0767,0.198,0.2706,0.113],"r":3.3866,"img":"img/I1/walk/p021_30_01.jpg","say":"가치 1 편의(Convenience): 수동 개입의 완전한 제거"},{"b":[0.107,0.301,0.379,0.075],"c":[0.088,0.2835,0.4169,0.11],"r":5.3599,"img":"img/I1/walk/p021_30_02.jpg","say":"수동 조작 삭제: 스위치 탐색 없이 생체/재실 센싱으로 자동 점등"},{"b":[0.107,0.381,0.379,0.072],"c":[0.088,0.362,0.4169,0.11],"r":5.3599,"img":"img/I1/walk/p021_30_03.jpg","say":"정적 재실 포착: mmWave로 독서, 휴식 중 미세 호흡을 감지해 재실 유지"},{"b":[0.107,0.46,0.357,0.039],"c":[0.0891,0.4245,0.3927,0.11],"r":5.0488,"img":"img/I1/walk/p021_30_04.jpg","say":"미니멀 월: 다수 스위치 수량을 축소해 벽면 디자인 정돈"},{"b":[0.521,0.214,0.207,0.081],"c":[0.509,0.198,0.231,0.113],"r":2.891,"img":"img/I1/walk/p021_30_05.jpg","say":"가치 2 안전(Safety): 타협 없는 선제적 물리 보호"},{"b":[0.543,0.301,0.375,0.232],"c":[0.5243,0.285,0.4125,0.264],"r":2.2097,"img":"img/I1/walk/p021_30_06.jpg","say":"선제적 물리 차단(가스/화재 감지 시 밸브 차단, 환기 배기 가동), 비식별 프라이버시(욕실, 침실에 카메라 없이 레이더로 낙상 감지), 비상 인프라 L1(정전 대비 피난 유도 조명, 비상 전원선 확보)"}]}},{"p":22,"title":"1.2.6 지능형 공간의 핵심 가치: 쾌적과 절감","terms":["4 Core Values of AI@Home Design","Comfort","Saving","Energy Recovery Ventilator","Carbon Dioxide Sensor","Circadian Lighting","Household Distribution Board","Trigger"],"pass1":[{"kind":"say","lines":["나머지 두 약속은 기분 좋은 공기와 빛, 그리고 아끼기예요."]},{"kind":"analogy","head":"집의 코가 먼저 알아채요","scene":"방에 사람이 오래 있으면 공기가 조금씩 답답해져요. 우리 코는 한참 지나서야 '답답하네' 하고 느껴요. 집의 코 역할을 하는 센서는 그보다 먼저 알아채고 환기 장치를 돌려요. 그래서 사람이 답답함을 느끼기도 전에 공기가 바뀌어 있어요.","map":[["코","공기 상태를 재는 센서"],["창문 여는 손","환기 장치"],["답답해지기 전에 환기","쾌적"]]},{"kind":"points","head":"두 가지 약속","items":["**쾌적(Comfort)**: 공기와 빛이 늘 기분 좋은 상태예요.","**절감(Saving)**: 안 쓰는 전기를 알아서 끄는 알뜰함이에요."]}],"pass2":[{"kind":"points","head":"쾌적: 좋은 환경을 스스로 지켜요","items":["선제적 환기: **CO2 센서(Carbon Dioxide Sensor)**가 공기가 탁해지는 걸 재면, 답답함을 느끼기 전에 **ERV(Energy Recovery Ventilator)**를 돌려요.","**서카디안 조명(Circadian Lighting)**: 해가 뜨고 지는 흐름에 맞춰 빛 색깔과 밝기를 바꿔요.","빌트인 센싱: 환경 센서를 인테리어 마감 속에 숨겨 넣어요."]},{"kind":"points","head":"절감: 낭비를 먼저 끊어요","items":["자율 전력 회수: 한동안 사람이 없으면 냉난방과 조명을 자동으로 꺼요.","누진세 예방: **세대분전반(Household Distribution Board)**에서 전기 사용량을 실시간으로 재서, 요금이 비싸지는 구간 전에 사용을 조절해요.","클라이언트 제안: 얼마나 아꼈는지 숫자 자료로 의뢰인에게 보여 줘요."]},{"kind":"check","q":"'ERV(Energy Recovery Ventilator)'는 무엇일까요?","choices":["창문을 열지 않고 바깥 공기로 바꿔 주는 환기 장치","해 궤적에 맞춰 빛을 바꾸는 조명","전기를 방마다 나눠 주는 분전반","사람 숨결을 재는 레이더"],"a":0,"why":"쾌적 가치의 선제적 환기에서 CO2 센서 값이 오르면 가동하는 설비예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"compare","head":"쾌적과 절감 숫자까지","cols":["가치","항목","슬라이드 내용"],"rows":[["**쾌적(Comfort)**","선제적 환기","CO2 농도 상승 시 **ERV(Energy Recovery Ventilator)** 가동"],["**쾌적(Comfort)**","서카디안 조명, 빌트인 센싱","태양 궤적에 맞춰 색온도, 조도 동기화 / 센서를 마감 내 매립"],["**절감(Saving)**","자율 전력 회수","10분 무감지 시 냉난방, 조명 자동 차단"],["**절감(Saving)**","누진세 예방","**세대분전반(Household Distribution Board)** 실시간 계측으로 누진 구간 전 소비 조율"],["**절감(Saving)**","클라이언트 제안","월간 에너지 15~20% 절감 정량 데이터(ROI) 제시"]]},{"kind":"points","head":"낱말 풀이","items":["색온도: 빛이 노르스름한지 푸르스름한지 나타내는 값이에요. 조도: 밝기예요.","누진세(누진제): 전기를 많이 쓸수록 단가가 올라가는 요금 구조예요.","ROI는 투자 대비 효과예요. 설치비 대비 얼마나 아끼는지 숫자로 보여 줘요.","**CO2 센서(Carbon Dioxide Sensor)**는 환기 자동화의 **트리거(Trigger)**, 곧 출발 신호를 줘요."]}],"pass4":[{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 34번","q":"스마트 스위치로 기존 조명을 원격 제어, 자동화할 때 효과로 가장 적절하지 않은 것은? (① 조명 교체 없이 원격 제어 ② 여러 조명 동시 제어는 되지만 전력 절감엔 도움 안 됨 ③ 앱으로 원격 점등, 소등 ④ 예약, 외출 모드 자동화)","qko":"스마트 스위치 효과 중 틀린 말 하나를 고르는 문제예요.","solve":["이 쪽의 절감 가치를 떠올려요. 무감지 시 자동 차단처럼 자동화는 낭비 전력을 줄여요.","여러 조명을 한꺼번에 끄거나 외출 모드로 켜진 채 방치되는 조명을 줄이면 전력이 줄어요.","그래서 '전력 절감에 도움이 되지 않는다'는 ②가 틀렸어요."],"answer":"② 여러 조명기기를 동시에 제어할 수 있지만, 불필요한 전력 사용을 줄이는 데에는 도움이 되지 않는다"},{"kind":"check","q":"절감 가치 '자율 전력 회수'의 기준 시간은?","choices":["10분 무감지","1분 무감지","30분 무감지","24시간 무감지"],"a":0,"why":"10분 동안 감지가 없으면 냉난방, 조명을 자동 차단해요."},{"kind":"check","q":"클라이언트 제안에서 제시하는 월간 에너지 절감 수치는?","choices":["15~20%","5~10%","30~40%","50% 이상"],"a":0,"why":"월간 에너지 15~20% 절감 정량 데이터(ROI)를 제시해요."},{"kind":"english","head":"답안 문장: 4대 가치 (24쪽 Q2와 같은 답)","en":"지능형 공간의 4대 핵심 가치는 편의(Convenience), 안전(Safety), 쾌적(Comfort), 절감(Saving)이다.","ko":"각 가치의 부제까지 쓰면 더 좋아요. 편의(수동 개입 제거), 안전(선제적 물리 보호), 쾌적(최적 환경 자율 유지), 절감(낭비 능동 차단).","tip":"'편, 안, 쾌, 절'."}],"pass5":[{"kind":"steps","head":"실기 가이드북 2권, 1-1 #5 자동화 구상 실습: 에어컨 쾌적 자동화","steps":["목표: 실내 28도 이상이면 에어컨 켜기, 22도가 되면 송풍 전환, 송풍 1시간 지속되면 끄기","한 자동화에 연속 동작과 타이머를 몰아넣으면 앱에서 오류가 나 실행되지 않아요.","자동화 1: 온도 센서 28도 이상일 때 → 에어컨 작동","자동화 2: 22도 이하일 때 → 에어컨이 작동 중이면(선택) → 송풍 모드 전환","자동화 3: 송풍 모드이고 22도 이하일 때 → 1시간 후(선택) → 꺼짐"],"answer":"시작조건을 나누고, 시작조건마다 동작을 따로 만들어야 정상 동작해요."},{"kind":"check","q":"실기 가이드북에서 여러 단계 자동화가 오류 날 때 해결법은?","choices":["시작조건을 나눠 자동화를 여러 개로 만든다","센서를 더 산다","Wi-Fi를 끈다","타이머를 모든 동작에 넣는다"],"a":0,"why":"하나의 자동화에 연속 동작을 넣지 말고, 시작조건별로 따로 만들어요."}],"walk":{"head":{"b":[0.0681,0.1116,0.5623,0.0666],"c":[0.04,0.0956,0.6185,0.0986],"r":8.8712,"img":"img/I1/walk/p022_h.jpg"},"parts":[{"b":[0.089,0.214,0.211,0.081],"c":[0.077,0.198,0.235,0.113],"r":2.9411,"img":"img/I1/walk/p022_30_01.jpg","say":"가치 3 쾌적(Comfort): 최적 실내 환경의 자율 유지"},{"b":[0.107,0.301,0.364,0.037],"c":[0.0888,0.2645,0.4004,0.11],"r":5.1478,"img":"img/I1/walk/p022_30_02.jpg","say":"선제적 환기: CO2 농도 상승 시 답답함 느끼기 전 ERV 가동"},{"b":[0.107,0.345,0.357,0.036],"c":[0.0891,0.308,0.3927,0.11],"r":5.0488,"img":"img/I1/walk/p022_30_03.jpg","say":"서카디안 조명: 태양 궤적에 맞춰 색온도, 조도 자율 동기화"},{"b":[0.107,0.389,0.357,0.037],"c":[0.0891,0.3525,0.3927,0.11],"r":5.0488,"img":"img/I1/walk/p022_30_04.jpg","say":"빌트인 센싱: 환경 센서를 인테리어 마감 내로 매립 일체화"},{"b":[0.521,0.214,0.204,0.081],"c":[0.509,0.198,0.228,0.113],"r":2.8535,"img":"img/I1/walk/p022_30_05.jpg","say":"가치 4 절감(Saving): 에너지 낭비의 능동적 차단"},{"b":[0.543,0.301,0.371,0.162],"c":[0.5245,0.285,0.4081,0.194],"r":2.975,"img":"img/I1/walk/p022_30_06.jpg","say":"자율 전력 회수(10분 무감지 시 냉난방/조명 자동 차단), 누진세 예방(분전반 실시간 계측으로 누진 구간 전 소비 조율), 클라이언트 제안(월간 에너지 15~20% 절감 정량 데이터(ROI) 제시)"}]}},{"p":23,"title":"1.2.7 거주자 경험 역산 설계 (R-BD) 방법론","terms":["Resident-Experience Backward Design","User Experience","mmWave Presence Sensor","Sensor","Electrical, Infrastructure Layer","Spatial, Interior Layer"],"pass1":[{"kind":"say","lines":["기기부터 사지 않아요. 사는 사람이 느낄 기분부터 정해요.","그 기분을 만들려면 무엇을 알아야 하는지, 어떤 기계가 필요한지, 벽과 전기가 받쳐 줄지를 차례로 거꾸로 정해요.","이 방법을 **거주자 경험 역산 설계(Resident-Experience Backward Design)**라고 해요."]},{"kind":"figure","head":"거꾸로 네 걸음","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect class=\"n2\" x=\"5\" y=\"95\" width=\"105\" height=\"70\" rx=\"2\"/><text class=\"tl\" x=\"57\" y=\"125\" font-size=\"15\" text-anchor=\"middle\">느낄 기분<\/text><text class=\"tl\" x=\"57\" y=\"147\" font-size=\"14\" text-anchor=\"middle\">목표<\/text><polygon class=\"arrow b2\" points=\"112,122 122,130 112,138\"/><rect class=\"n b2\" x=\"124\" y=\"95\" width=\"105\" height=\"70\" rx=\"2\"/><text class=\"tl b2\" x=\"176\" y=\"125\" font-size=\"15\" text-anchor=\"middle\">알아야 할<\/text><text class=\"tl b2\" x=\"176\" y=\"147\" font-size=\"14\" text-anchor=\"middle\">데이터<\/text><polygon class=\"arrow b3\" points=\"231,122 241,130 231,138\"/><rect class=\"n b3\" x=\"243\" y=\"95\" width=\"105\" height=\"70\" rx=\"2\"/><text class=\"tl b3\" x=\"295\" y=\"125\" font-size=\"15\" text-anchor=\"middle\">필요한<\/text><text class=\"tl b3\" x=\"295\" y=\"147\" font-size=\"14\" text-anchor=\"middle\">기계<\/text><polygon class=\"arrow b4\" points=\"350,122 360,130 350,138\"/><rect class=\"n3 b4\" x=\"362\" y=\"95\" width=\"113\" height=\"70\" rx=\"2\"/><text class=\"tl b4\" x=\"418\" y=\"125\" font-size=\"15\" text-anchor=\"middle\">벽과 전기<\/text><text class=\"tl b4\" x=\"418\" y=\"147\" font-size=\"14\" text-anchor=\"middle\">확인<\/text><text class=\"t b4\" x=\"240\" y=\"220\" font-size=\"16\" text-anchor=\"middle\">기기에서 시작하지 않고, 기분에서 거꾸로<\/text><\/svg>","caption":"목표 기분에서 출발해 벽과 전기 확인까지 가요.","builds":4}],"pass2":[{"kind":"steps","head":"수면 예시로 네 단계 따라가기","steps":["경험 목표: \"자는 동안 쾌적한 환경 유지\". 이것이 **거주자 경험(User Experience)** 목표예요.","필요 데이터: 사람이 가만히 누워 있는지(정적 재실), 방 온도와 습도가 어떤지 알아야 해요.","기술 사양: 가만히 있는 사람을 재는 **mmWave 재실센서(mmWave Presence Sensor)**와 온습도 **센서(Sensor)**를 골라요.","물리 검증: 침대 위쪽에 늘 전기가 들어오는 콘센트 자리와 마감재를 확인해요."],"answer":"목표 → 데이터 → 기술 → 물리 순서로 거꾸로 내려와요."},{"kind":"points","head":"왜 거꾸로 할까요","items":["벽 속 전선, 천장 자리는 공사가 끝나면 고치기 어려워요.","기기부터 사면 나중에 '전기가 없다', '달 자리가 없다'는 실수가 생겨요.","경험에서 시작하면 그런 실수를 설계 단계에서 미리 막아요."]},{"kind":"check","q":"R-BD의 첫 단계는?","choices":["경험 목표(UX Goal) 정하기","기술 사양 도출","물리 검증","기기 구매"],"a":0,"why":"**거주자 경험 역산 설계(Resident-Experience Backward Design)**는 경험 목표에서 출발해요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"네 번째 상자를 더 정확히","items":["L1/L2는 **L1 전기 및 인프라 계층(Electrical, Infrastructure Layer)**과 **L2 공간 및 기기 배치 계층(Spatial, Interior Layer)**이에요.","상시전원: 스위치와 상관없이 늘 전기가 들어오는 전원이에요. 센서가 쉬지 않고 재려면 필요해요.","마감재: 벽, 천장 겉면 재료예요. 센서를 숨기거나 전파가 지나가는 데 영향을 줘요.","착오를 원천 차단: 실수가 생길 뿌리부터 막는다는 뜻이에요."]}],"pass4":[{"kind":"check","q":"R-BD 네 단계 순서로 맞는 것은?","choices":["경험 목표 → 필요 데이터 식별 → 기술 사양 도출 → 물리 검증","기술 사양 도출 → 경험 목표 → 물리 검증 → 필요 데이터 식별","물리 검증 → 기술 사양 도출 → 필요 데이터 식별 → 경험 목표","필요 데이터 식별 → 경험 목표 → 기술 사양 도출 → 물리 검증"],"a":0,"why":"목표에서 데이터, 기술, 물리로 내려와요. '목, 데, 기, 물'."},{"kind":"english","head":"답안 문장: R-BD 정의 (24쪽 Q3)","en":"거주자 경험 역산 설계(R-BD)는 거주자가 체감할 최종 공간 경험(UX) 목표로부터 필요한 데이터와 기술 요구사항을 역으로 도출하여, 시공 후 수정이 불가능한 물리 인프라의 착오를 원천 차단하는 기획 방법론이다.","ko":"출발(UX 목표), 방향(역으로 도출), 목적(물리 인프라 착오 차단) 세 조각이에요.","tip":"'목, 데, 기, 물' 네 단계를 덧붙이면 서술형 만점 답이 돼요."},{"kind":"warn","head":"헷갈리는 점","items":["R-BD는 '생각하는 순서'가 거꾸로예요. 33쪽 Bottom-Up은 '현장에서 짓는 순서'예요.","물리 검증 단계에 적힌 층은 L1/L2예요. L3, L4가 아니에요."]}],"pass5":[{"kind":"points","head":"실기 가이드북 2권, 1-1 지능형홈 구축 5대 고려사항","items":["#1 지능형홈 구상: 가족 구성원 수, 행동 양식, 동선을 관찰해 사용 장면(Scene)을 그려요. 관리하기 편한 집이 아니라 쓰는 사람의 삶을 편하게 하는 컨셉이에요.","#2 IoT 디바이스 선정: 구축 시 체감이 큰 부분 → 가장 필요한 부분 → 공식적인 장치 선정. 고객 예산에 맞춰요.","#3 서비스 모델 선정, #4 가옥 구조에 맞는 네트워크 구상, #5 구축 및 자동화예요.","R-BD의 '경험 목표에서 출발'이 #1 구상과 같은 방향이에요."]},{"kind":"check","q":"실기 가이드북의 디바이스 선정 우선순위로 맞는 것은?","choices":["구축 시 체감이 큰 부분 → 가장 필요한 부분 → 공식적인 장치 선정","가장 싼 장치 → 가장 비싼 장치 → 체감","공식 장치 → 체감 → 필요","브랜드 → 색상 → 크기"],"a":0,"why":"처음부터 한꺼번에 많이 붙이지 말고, 시간과 필요성, 고객 예산을 먼저 고려해요."}],"walk":{"head":null,"parts":[{"b":[0.071,0.119,0.471,0.088],"c":[0.0474,0.103,0.5181,0.12],"r":6.1059,"img":"img/I1/walk/p023_30_01.jpg","say":"영문 이름 Resident-Experience Backward Design. 머리글자로 R-BD예요."},{"b":[0.077,0.232,0.849,0.141],"c":[0.0345,0.2082,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p023_30_02.jpg","say":"정의: 기기를 무작정 도입하지 않고, 거주자가 체감할 최종 공간 경험(UX) 목표에서 필요한 데이터와 기술 요구사항을 역으로 도출해, 시공 후 수정이 불가능한 물리 인프라의 착오를 원천 차단하는 핵심 기획 방법론이에요."},{"b":[0.077,0.416,0.185,0.176],"c":[0.065,0.4,0.209,0.208],"r":1.421,"img":"img/I1/walk/p023_30_03.jpg","say":"1. 경험 목표(UX Goal): \"수면 중 쾌적 환경 유지\""},{"b":[0.298,0.433,0.185,0.143],"c":[0.286,0.417,0.209,0.175],"r":1.689,"img":"img/I1/walk/p023_30_04.jpg","say":"2. 필요 데이터 식별: 정적 재실 + 실내 온습도"},{"b":[0.519,0.433,0.185,0.143],"c":[0.507,0.417,0.209,0.175],"r":1.689,"img":"img/I1/walk/p023_30_05.jpg","say":"3. 기술 사양 도출: mmWave 레이더 + 센서"},{"b":[0.741,0.399,0.185,0.212],"c":[0.729,0.383,0.209,0.244],"r":1.2114,"img":"img/I1/walk/p023_30_06.jpg","say":"4. 물리 검증(L1/L2): 침대 상부 상시전원 & 마감재"}]}},{"p":24,"title":"1.2강 CHECKPOINT","terms":["mmWave Presence Sensor","Passive Infrared Sensor","4 Core Values of AI@Home Design","Resident-Experience Backward Design"],"pass1":[{"kind":"say","lines":["1.2강 복습 문제 세 개예요. 답을 가리고 먼저 말해 봐요."]},{"kind":"recap","items":["가만히 있는 사람까지 알아채는 센서: 숨결을 재는 레이더 센서","똑똑한 공간의 네 약속: 편의, 안전, 쾌적, 절감","기분에서 거꾸로 기계를 고르는 설계 방법: 거주자 경험 역산 설계"]}],"pass2":[{"kind":"points","head":"문제마다 돌아가 볼 쪽","items":["Q1 정적 재실 센서: 21쪽 편의 가치의 **mmWave 재실센서(mmWave Presence Sensor)**","Q2 4대 가치: 21, 22쪽 **지능형홈 설계 4대 가치(4 Core Values of AI@Home Design)**","Q3 역산 설계: 23쪽 **거주자 경험 역산 설계(Resident-Experience Backward Design)**"]}],"pass3":[{"kind":"look","walked":1},{"kind":"compare","head":"PIR 센서와 mmWave 재실센서","cols":["구분","**PIR 센서(Passive Infrared Sensor)**","**mmWave 재실센서(mmWave Presence Sensor)**"],"rows":[["재는 것","적외선(체온 열)의 변화","밀리미터파 전파로 미세한 움직임"],["가만히 있는 사람","움직임이 없으면 놓칠 수 있어요","호흡, 흉부 움직임까지 감지해요"],["이 강의에서","L2 배치 항목(28쪽)","편의 가치의 정적 재실 포착(21쪽)"]]}],"pass4":[{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 31번","q":"센서를 착용하거나 접촉하지 않고 거실의 사람 움직임을 감지하려 한다. 가장 적합하지 않은 센서는? (① PIR 센서 ② UWB 센서 ③ 적외선 이미지 센서 ④ 피부 접촉식 생체 신호 센서)","qko":"몸에 닿지 않고 사람을 감지하는 방법이 아닌 것을 고르는 문제예요.","solve":["조건은 '착용하거나 접촉하지 않은 상태'예요.","PIR 센서는 적외선 변화, UWB 센서는 전파, 적외선 이미지 센서는 열 영상으로 떨어져서 감지해요.","피부 접촉식 센서는 몸에 붙여야 작동하니 조건에 맞지 않아요."],"answer":"④ 피부 접촉식 생체 신호 센서"},{"kind":"english","head":"답안 문장: Q1","en":"독서나 수면처럼 움직임이 없는 정적 재실 상태는 미세 호흡과 흉부 움직임을 감지하는 mmWave(밀리미터파) 레이더 센서로 감지한다.","ko":"PIR은 움직임이 있을 때만 반응해서 정적 재실을 놓쳐요. 그래서 mmWave가 답이에요.","tip":"'가만히 = 밀리미터파'."},{"kind":"warn","head":"헷갈리는 점","items":["정적 재실 문제에 PIR 센서를 쓰면 틀려요. **PIR 센서(Passive Infrared Sensor)**는 움직일 때만 반응해요.","4대 가치 영어 철자: Convenience, Safety, Comfort, Saving. Saving을 Energy로 쓰지 않아요."]}],"pass5":[{"kind":"points","head":"실기 가이드북 2권, 1-1 PIR 센서에 대해서","items":["**PIR 센서(Passive Infrared Sensor)**는 인체 36.5도에서 나오는 원적외선을 감지하는 수동형 적외선 모션 센서예요.","① 주변 온도에 따라 감지 속도가 달라요. ② 5도 이상 급격한 주변 온도 변화에도 동작해요.","③ 움직임이 없거나 미세하면 감지하지 못해요. ④ 센서 수신부에 대한 수직 움직임은 정확도가 낮아요.","⑤ 렌즈 패턴에 따라 다르지만 PIR 센서 하나는 120도 감지 범위를 가져요."]},{"kind":"check","q":"실기 가이드북에서 PIR 센서 하나의 감지 범위는?","choices":["120도","360도","45도","180도"],"a":0,"why":"렌즈 패턴에 따라 다르지만 보통 120도예요. 배치할 때 이 각도를 맞춰야 오작동이 없어요."}],"walk":{"head":{"b":[0.0681,0.1116,0.2708,0.0666],"c":[0.0545,0.0956,0.2978,0.0986],"r":4.2714,"img":"img/I1/walk/p024_h.jpg"},"parts":[{"b":[0.077,0.21,0.849,0.115],"c":[0.0345,0.1732,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p024_30_01.jpg","say":"Q1 독서나 수면처럼 움직임 없는 정적 재실 상태를 감지하는 핵심 센서 기술은? 정답: 미세 호흡 및 흉부 움직임을 감지하는 mmWave(밀리미터파) 레이더 센서"},{"b":[0.077,0.354,0.849,0.115],"c":[0.0345,0.3172,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p024_30_02.jpg","say":"Q2 지능형 공간의 4대 핵심 가치는? 정답: 편의(Convenience), 안전(Safety), 쾌적(Comfort), 절감(Saving)"},{"b":[0.077,0.497,0.849,0.114],"c":[0.0345,0.4597,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p024_30_03.jpg","say":"Q3 기기를 먼저 사지 않고 거주자 경험 목표에서 하드웨어를 역으로 설계하는 방법론은? 정답: 거주자 경험 역산 설계, R-BD(Resident-Experience Backward Design)"}]}},{"p":25,"title":"[1.3강] 4-Layer 적층구조와 Architect의 역할","terms":["4-Layer Architecture","Electrical, Infrastructure Layer","Spatial, Interior Layer","Connectivity, Network Layer","Intelligence, AI Layer","Foundation-Control Relationship","Architect","Bottom-Up"],"pass1":[{"kind":"say","lines":["1.3강은 집을 네 층으로 나눠 보는 시간이에요.","층마다 무슨 일을 하는지 보고, 층끼리 어떻게 기대는지, 지휘자가 무엇을 하는지 배워요."]}],"pass2":[{"kind":"points","head":"여덟 조각을 네 묶음으로","items":["1.3.1: **4-Layer 적층구조(4-Layer Architecture)** 전체 그림","1.3.2~1.3.5: 층별로 L1 전기, L2 공간, L3 연결, L4 지능","1.3.6~1.3.7: **기반-제어 관계(Foundation-Control Relationship)**와 **지능형 공간 Architect**","1.3.8: 현장에서 짓는 순서 **Bottom-Up**과 수업에서 배우는 순서"]}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"목차에만 나오는 표현","items":["마감재 전파 감쇠: 벽, 천장 재료가 무선 신호를 약하게 만드는 현상이에요. **L2 공간 및 기기 배치 계층(Spatial, Interior Layer)** 목차 이름에 들어 있어요.","층 이름 네 개는 아래부터 전기, 공간, 연결, 지능이에요. 정식 이름은 26쪽에서 하나씩 봐요.","대칭 구조: 짓는 순서와 배우는 순서가 서로 다르게 짜여 있다는 뜻이에요."]}],"pass4":[],"pass5":[],"walk":{"head":{"b":[0.0696,0.111,0.5273,0.0722],"c":[0.0433,0.095,0.58,0.1042],"r":7.8719,"img":"img/I1/walk/p025_h.jpg"},"parts":[{"b":[0.093,0.224,0.429,0.04],"c":[0.0716,0.189,0.4719,0.11],"r":6.0671,"img":"img/I1/walk/p025_30_01.jpg","say":"1.3.1 4-Layer Architecture 개요와 수직 적층 체계"},{"b":[0.093,0.293,0.407,0.253],"c":[0.0726,0.277,0.4477,0.285],"r":2.2216,"img":"img/I1/walk/p025_30_02.jpg","say":"1.3.2 [L1] 전기, 인프라 및 IoT 조명/전원, 1.3.3 [L2] 공간, 기기 배치층과 마감재 전파 감쇠, 1.3.4 [L3] 연결, 네트워크층과 무선 프로토콜, 1.3.5 [L4] 지능, 자동화층과 AI 인지 루프"},{"b":[0.093,0.574,0.5,0.115],"c":[0.068,0.558,0.55,0.147],"r":5.2913,"img":"img/I1/walk/p025_30_03.jpg","say":"1.3.6 기반-제어 관계(Foundation-Control Relationship), 1.3.7 공간 전문가의 정체성, 오케스트라의 지휘자"},{"b":[0.093,0.715,0.386,0.042],"c":[0.0737,0.681,0.4246,0.11],"r":5.4589,"img":"img/I1/walk/p025_30_04.jpg","say":"1.3.8 실무 구축 vs 커리큘럼 학습의 대칭 구조"}]}},{"p":26,"title":"1.3.1 4-Layer Architecture 개요","terms":["4-Layer Architecture","Electrical, Infrastructure Layer","Spatial, Interior Layer","Connectivity, Network Layer","Intelligence, AI Layer","AI Cognitive Loop","Sensor","Actuator"],"pass1":[{"kind":"analogy","head":"네 층 건물","scene":"네 층짜리 건물을 지어요. 1층은 전기가 안전하게 들어오는지 챙겨요. 2층은 가구와 기계 자리를 정하고, 3층은 기계끼리 끊기지 않게 선을 이어요. 꼭대기 4층 두뇌가 정보를 모아 집을 어떻게 맞출지 정해요.","map":[["1층 전기실","전기 및 인프라 계층"],["2층 가구 배치","공간 및 기기 배치 계층"],["3층 연결선","연결 및 네트워크 계층"],["4층 두뇌","지능 및 자동화 계층"]]},{"kind":"figure","head":"아래에서 위로 쌓은 네 층","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect class=\"n3\" x=\"90\" y=\"210\" width=\"300\" height=\"46\" rx=\"2\"/><text class=\"tl\" x=\"240\" y=\"239\" font-size=\"16\" text-anchor=\"middle\">1층 전기 (L1)<\/text><rect class=\"n b2\" x=\"90\" y=\"158\" width=\"300\" height=\"46\" rx=\"2\"/><text class=\"tl b2\" x=\"240\" y=\"187\" font-size=\"16\" text-anchor=\"middle\">2층 공간, 기기 배치 (L2)<\/text><rect class=\"n b3\" x=\"90\" y=\"106\" width=\"300\" height=\"46\" rx=\"2\"/><text class=\"tl b3\" x=\"240\" y=\"135\" font-size=\"16\" text-anchor=\"middle\">3층 연결, 무선 (L3)<\/text><rect class=\"n2 b4\" x=\"90\" y=\"54\" width=\"300\" height=\"46\" rx=\"2\"/><text class=\"tl b4\" x=\"240\" y=\"83\" font-size=\"16\" text-anchor=\"middle\">4층 지능, AI (L4)<\/text><text class=\"tm b4\" x=\"240\" y=\"35\" font-size=\"15\" text-anchor=\"middle\">아래층이 위층을 받쳐요<\/text><\/svg>","caption":"이 네 층 그림이 4-Layer 적층구조예요.","builds":4}],"pass2":[{"kind":"points","head":"층마다 한 줄","items":["**L1 전기 및 인프라 계층(Electrical, Infrastructure Layer)**: 맨 아래, 전기가 잘 들어오는지 챙겨요.","**L2 공간 및 기기 배치 계층(Spatial, Interior Layer)**: 센서를 집 어디에 달지 정해요.","**L3 연결 및 네트워크 계층(Connectivity, Network Layer)**: 기기끼리 끊기지 않게 무선을 이어요.","**L4 지능 및 자동화 계층(Intelligence, AI Layer)**: AI가 생각하고 결정해요."]},{"kind":"steps","head":"주문과 네 층 짝짓기","steps":["센서가 느끼고: **센서(Sensor)**를 제자리에 다는 일은 L2예요.","네트워크가 나르고: 신호를 나르는 무선은 L3예요.","허브와 플랫폼이 판단하고: 판단하는 두뇌는 L4예요.","기기가 움직여요: **액추에이터(Actuator)**가 움직이려면 모두 L1 전기가 받쳐야 해요."],"answer":"이 한 바퀴가 **AI 인지 루프(AI Cognitive Loop)**이고, 네 층을 모두 지나가요."},{"kind":"check","q":"센서를 어디에 달아야 사각지대가 없을지 정하는 층은?","choices":["L2 공간 및 기기 배치 계층","L1 전기 및 인프라 계층","L3 연결 및 네트워크 계층","L4 지능 및 자동화 계층"],"a":0,"why":"L2는 동선 분석과 사각지대 제거로 기기 위치를 설계해요."}],"pass3":[{"kind":"look","walked":1},{"kind":"compare","head":"네 층 영어 이름까지","cols":["층","한국어","그림 속 영어","하는 일"],"rows":[["L4","지능 및 자동화","Intelligence","생활 패턴 학습, AI 자동 판단, 제어"],["L3","연결 및 네트워크","Connectivity","무선 인프라, 간섭 회피, 통신 신뢰성"],["L2","공간 및 기기 배치","Spatial","동선 분석, 사각지대 제거, 기기 위치"],["L1","전기 및 인프라","Electrical","배선 진단, 전력 공급 점검, 물리적 안전성"]]}],"pass4":[{"kind":"check","q":"4-Layer에서 '무선 인프라 구축 및 간섭 회피를 통한 통신 신뢰성 확보'를 맡는 층은?","choices":["L3","L1","L2","L4"],"a":0,"why":"L3 연결 및 네트워크 계층(Connectivity, Network Layer)이에요."},{"kind":"check","q":"\"동선 분석 및 사각지대 제거\"는 어느 층 설명일까요?","choices":["L2 공간 및 기기 배치","L3 연결 및 네트워크","L1 전기 및 인프라","L4 지능 및 자동화"],"a":0,"why":"공간 디자인 관점에서 기기 최적 위치를 설계하는 L2예요."},{"kind":"warn","head":"번호와 이름을 섞기 쉬워요","items":["L2가 공간(Spatial), L3가 연결(Connectivity)이에요. 무선이 2층이 아니에요.","외우는 법: 아래부터 '전, 공, 연, 지(전기, 공간, 연결, 지능)'."]}],"pass5":[],"walk":{"head":{"b":[0.0673,0.1116,0.3946,0.1012],"c":[0.0476,0.0956,0.4341,0.1332],"r":4.609,"img":"img/I1/walk/p026_h.jpg"},"parts":[{"b":[0.077,0.226,0.499,0.14],"c":[0.0521,0.21,0.5489,0.172],"r":4.5132,"img":"img/I1/walk/p026_30_01.jpg","say":"L4 지능 및 자동화 계층: 거주자 생활 패턴을 학습해 최적 환경을 AI가 자동 판단, 제어하는 최상위 단계"},{"b":[0.077,0.376,0.499,0.106],"c":[0.0521,0.36,0.5489,0.138],"r":5.6252,"img":"img/I1/walk/p026_30_02.jpg","say":"L3 연결 및 네트워크 계층: 무선 인프라 구축과 간섭 회피로 기기 간 끊김 없는 통신 신뢰성 확보"},{"b":[0.077,0.492,0.499,0.105],"c":[0.0521,0.476,0.5489,0.137],"r":5.6662,"img":"img/I1/walk/p026_30_03.jpg","say":"L2 공간 및 기기 배치 계층: 동선 분석과 사각지대 제거로 공간 디자인 관점의 기기 최적 위치 설계"},{"b":[0.077,0.606,0.499,0.108],"c":[0.0521,0.59,0.5489,0.14],"r":5.5448,"img":"img/I1/walk/p026_30_04.jpg","say":"L1 전기 및 인프라 계층: 전기 배선 진단과 전력 공급 점검으로 하드웨어 물리적 안전성 보장"},{"b":[0.593,0.226,0.333,0.488],"c":[0.5763,0.2016,0.3663,0.5368],"r":0.965,"img":"img/I1/walk/p026_30_05.jpg","say":"오른쪽 그림: 아래부터 L1 Electrical, L2 Spatial, L3 Connectivity, L4 Intelligence. 제목은 '수직 적층 및 유기적 상호 작용 체계도'예요."}]}},{"p":27,"title":"1.3.2 [L1] 전기 및 인프라 계층 (Electrical, Infrastructure Layer)","terms":["Electrical, Infrastructure Layer","Electric Leakage","잔광 현상","Neutral Line","Switching Mode Power Supply","Rated Capacity","Electric Power","Earth Leakage Circuit Breaker","3-Wire Wiring"],"pass1":[{"kind":"say","lines":["맨 아래 1층은 전기예요.","전기가 안전하게 잘 들어와야 위층 기계가 모두 돌아가요.","이 층에서는 전선에 문제가 없는지 살피고, 전기가 넉넉히 들어오는지 확인해요."]},{"kind":"points","head":"1층에서 배우는 네 가지","items":["전기의 기초와 실내 건축에 쓰는 법","전기가 새거나, 꺼진 조명이 희미하게 빛나는 문제 찾기","똑똑한 스위치에 꼭 필요한 전선 미리 깔기","조명용 전원 장치를 넉넉한 크기로 고르기"]}],"pass2":[{"kind":"points","head":"이 층 용어 하나하나","items":["**누전(Electric Leakage)**: 전기가 새서 엉뚱한 곳으로 흐르는 위험한 상황이에요.","**잔광 현상**: 불을 껐는데도 LED가 희미하게 빛나는 현상이에요.","**중성선(Neutral Line)**: 전기가 돌아 나가는 길이에요. 스마트 스위치에 꼭 필요해요.","**SMPS(Switching Mode Power Supply)**: 콘센트 전기를 LED가 먹기 좋은 전기로 바꿔 주는 전원장치예요.","**정격 용량(Rated Capacity)**: 기계가 오래 버틸 수 있는 최대 힘이에요."]},{"kind":"check","q":"'잔광 현상'의 뜻은?","choices":["스위치를 꺼도 LED가 희미하게 빛나거나 깜빡이는 현상","전선에서 전기가 새는 현상","무선 신호가 겹치는 현상","센서가 사람을 못 보는 구석"],"a":0,"why":"잔류 전류 때문에 LED가 흐릿하게 켜지는 현상이에요. 전기가 새는 건 **누전(Electric Leakage)**이에요."}],"pass3":[{"kind":"look","walked":1},{"kind":"steps","head":"여유율 20% 손계산 (쉬운 숫자 예시)","steps":["LED 조명들이 쓰는 **전력(Electric Power)**을 모두 더해요. 예) 50W","여유율 20%를 더해요. 50W의 20%는 10W예요.","50W + 10W = 60W","그래서 **SMPS(Switching Mode Power Supply)**의 **정격 용량(Rated Capacity)**은 60W 이상으로 골라요."],"answer":"필요 전력 × 1.2 이상. 50W면 60W 이상이에요.","given":"LED 합계 50W, 여유율 20% 이상"},{"kind":"bg","src":"기초 다지기 1단원","lines":["W(와트)는 전력의 단위, V(볼트)는 전압, A(암페어)는 전류예요.","전력 P = V × I. 전압과 전류를 곱하면 전력이에요.","1A = 1000mA예요."]}],"pass4":[{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 33번","q":"역률을 1로 가정할 수 있는 가전의 동작 전압이 200V이고 측정 전류가 100mA일 때 소비전력은? (① 5W ② 10W ③ 20W ④ 30W)","qko":"전압과 전류를 곱해 전력을 구하는 계산 문제예요.","solve":["역률이 1이면 **전력(Electric Power)** P = V × I를 그대로 써요.","전류 단위를 A로 바꿔요. 100mA = 0.1A","P = 200V × 0.1A = 20W","mA를 그대로 곱하면 20000이 나와 틀려요."],"answer":"③ 20W"},{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 39번","q":"분전반에 설치할 누전차단기의 전기적 선정 기준으로 가장 적절하지 않은 것은? (① 정격 전류 ② 정격 전압 ③ 정격 감도 전류 ④ 통신 방식)","qko":"**누전차단기(Earth Leakage Circuit Breaker)**를 고를 때 보지 않는 항목을 고르는 문제예요.","solve":["**누전차단기(Earth Leakage Circuit Breaker)**는 **누전(Electric Leakage)**을 감지해 전기를 끊는 L1 장치예요.","고르는 기준은 정격 전압, 정격 전류, 정격 감도 전류(누전을 감지해 끊는 기준 전류)처럼 전기 값이에요.","통신 방식은 IoT 기기용 기준이라 회로 보호와 관계가 없어요."],"answer":"④ 통신 방식"},{"kind":"check","q":"SMPS 정격 용량 계산에서 슬라이드가 요구한 여유율은?","choices":["20% 이상","5% 이상","50% 이상","여유 없이 딱 맞게"],"a":0,"why":"1-4 항목에 '여유율 20% 이상'이라고 적혀 있어요."}],"pass5":[{"kind":"points","head":"실기 가이드북 2권, 2-1 지능형홈 구축: 스마트 스위치 배선","items":["우리나라 조명 스위치는 보통 2선식이지만, 스마트 스위치는 상시 전원이 필요해 활선(Live), **중성선(Neutral Line)**, 부하선(Load)으로 된 **3선식 배선(3-Wire Wiring)**을 채택해요.","2선식 스마트 스위치는 부하선으로 미세 전류를 흘려 전원을 얻어서 LED에 **잔광 현상**이 생겨요. 잔광 제거 콘덴서나 노이즈 필터로 해결해요.","3선식은 공급과 차단이 100%와 0%라 잔광이 없어요.","스마트 스위치 안은 릴레이부, 제어부(MCU), 직류 전원 공급부(**SMPS(Switching Mode Power Supply)**)로 나뉘어요."]},{"kind":"compare","head":"전선 색 (가이드북, 2021년 1월부터 시행된 한국전기설비규정 KEC)","cols":["선","역할","색"],"rows":[["활선, 부하선","전기가 들어오고 전등으로 가는 선","갈색, 흑색, 회색"],["중성선(N)","전류가 되돌아가는 선","청색"],["접지선","누설 전류를 땅으로 보내는 선","녹색과 노란색이 섞인 선"]]},{"kind":"check","q":"실기 가이드북에서 2선식 스마트 스위치의 잔광 현상을 없애는 부품은?","choices":["잔광 제거 콘덴서, 노이즈 필터","Zigbee 리피터","누전차단기","PIR 센서"],"a":0,"why":"콘덴서나 노이즈 필터를 등기구의 컨버터(안정기) 선이나 천장 전원선에 연결해요."}],"walk":{"head":{"b":[0.0681,0.1116,0.7523,0.0713],"c":[0.0305,0.0956,0.8275,0.1033],"r":11.3289,"img":"img/I1/walk/p027_h.jpg"},"parts":[{"b":[0.077,0.194,0.849,0.111],"c":[0.0345,0.1552,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p027_30_01.jpg","say":"정의: 모든 시스템의 근간인 전기 배선의 이상 여부를 진단하고, 전력 공급 상태를 점검해 하드웨어의 물리적 안전성을 보장하는 기초 단계"},{"b":[0.093,0.335,0.389,0.04],"c":[0.0735,0.3,0.4279,0.11],"r":5.5014,"img":"img/I1/walk/p027_30_02.jpg","say":"1-1: 전기, 전력 기초 이론 및 실내건축 적용 원리"},{"b":[0.093,0.396,0.393,0.04],"c":[0.0733,0.361,0.4323,0.11],"r":5.5579,"img":"img/I1/walk/p027_30_03.jpg","say":"1-2: 전기 배선 이상 진단 및 누전, 잔광 현상 분석"},{"b":[0.093,0.457,0.404,0.04],"c":[0.0728,0.422,0.4444,0.11],"r":5.7135,"img":"img/I1/walk/p027_30_04.jpg","say":"1-3: 지능형홈 전기 배선 설계 및 중성선(N선) 확보"},{"b":[0.093,0.517,0.493,0.04],"c":[0.0684,0.482,0.5423,0.11],"r":6.9722,"img":"img/I1/walk/p027_30_05.jpg","say":"1-4: LED 전원장치(SMPS) 정격 용량 계산(여유율 20% 이상)"}]}},{"p":28,"title":"1.3.3 [L2] 공간 및 기기 배치 계층 (Spatial, Interior Layer)","terms":["Spatial, Interior Layer","감지 사각지대","Passive Infrared Sensor","mmWave Presence Sensor","Sensor"],"pass1":[{"kind":"analogy","head":"센서 눈에도 안 보이는 구석이 있어요","scene":"교실 맨 뒤 기둥 옆에 앉으면 선생님 눈에 잘 안 띄어요. 센서의 눈도 똑같이 못 보는 구석이 있어요. 그 구석에서 사람이 책을 읽으면 집은 아무도 없다고 여기고 불을 꺼 버려요. 그래서 센서를 어디에 달지 정하는 일이 공간 디자이너의 몫이에요.","map":[["선생님 눈","센서"],["기둥 옆 구석","감지 사각지대"],["자리를 옮겨 앉기","센서 위치 설계"]]},{"kind":"say","lines":["2층은 공간이에요. 센서와 기기를 집 어디에 둘지 정하는 층이에요."]}],"pass2":[{"kind":"points","head":"이 층이 하는 일","items":["사람이 집 안에서 움직이는 길, 곧 동선을 먼저 살펴요.","**센서(Sensor)**가 못 보는 구석, **감지 사각지대**를 없애요.","공간 디자인 눈으로 기기를 가장 좋은 자리에 놓아요."]},{"kind":"points","head":"모듈 세 개를 쉬운 말로","items":["2-1: 기기 구성 원리를 알고 평면도를 읽어요.","2-2: 거실, 침실, 욕실마다 사람 감지 센서를 알맞게 놓아요. **PIR 센서(Passive Infrared Sensor)**와 **mmWave 재실센서(mmWave Presence Sensor)**를 써요.","2-3: 기기를 인테리어 마감재와 함께 시공해요."]},{"kind":"check","q":"'감지 사각지대'를 없애려고 먼저 분석하는 것은?","choices":["공간 구조와 거주자 동선","통신사 요금제","전기 요금 누진 구간","AI 학습 데이터"],"a":0,"why":"L2 정의 첫머리가 '공간 구조와 거주자 동선을 분석하여'예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"이 층과 이어지는 내용","items":["강의 계획에서 L2는 5주차(공간 센서 기술, 감지 범위 분석)와 14주차(센서 화각, 음영 지역 배치)예요.","화각은 센서가 볼 수 있는 각도, 음영 지역은 신호나 시야가 닿지 않는 곳이에요.","목차 이름 '마감재 전파 감쇠': 마감재가 무선 신호를 약하게 만드는 것도 **L2 공간 및 기기 배치 계층(Spatial, Interior Layer)**에서 살펴요."]}],"pass4":[{"kind":"check","q":"L2 모듈 2-2에서 공간별 배치를 다루는 센서 두 가지는?","choices":["PIR, mmWave","CO2, 온습도","가스, 누수","자이로, 가속도"],"a":0,"why":"거실, 침실, 욕실별 감지 센서(PIR/mmWave) 최적 배치예요."},{"kind":"warn","head":"헷갈리는 점","items":["L2 이름은 '공간 및 기기 배치(Spatial, Interior)'예요. 무선 연결은 L3예요.","**PIR 센서(Passive Infrared Sensor)**는 움직일 때만, **mmWave 재실센서(mmWave Presence Sensor)**는 가만히 있어도 감지해요."]}],"pass5":[{"kind":"points","head":"실기 가이드북 2권, 1-1 #4 네트워크 구상: 재질과 무선 신호","items":["무선 신호는 전파가 지나는 공간에 어떤 물체가 있느냐에 영향을 받아요. 장애물 없는 빈 공간이 가장 좋아요.","장애물 밀도가 높을수록 신호가 약해져요. 벽돌, 돌이 석고보드, 목재 벽보다 더 약하게 만들어요.","금속 문, 금속 덕트, 금속 가구 같은 전도체는 신호를 거의 완벽히 막고 일부를 반사해요.","거울도 안쪽 금속 때문에 신호를 막을 수 있어요. 투명 유리창은 빛처럼 신호도 잘 통과해요."]},{"kind":"points","head":"실기 가이드북 2권, 1-1 스마트 주방 센서 배치 풀이","items":["식탁 모션 센서는 120도 감지 범위로 식탁을 비춰요.","싱크대 모션 센서는 감지 범위를 90도로 맞춰, 식탁 쪽 통로를 지날 때 감지되지 않게 설치해요.","감지 각도를 공간에 맞춰야 오작동을 줄여요. 이것이 L2의 사각지대, 오감지 설계예요."]},{"kind":"check","q":"실기 가이드북에서 무선 신호를 거의 완벽히 막는다고 한 재질은?","choices":["금속 같은 전도체","투명 유리창","얇은 블라인드","석고보드"],"a":0,"why":"전도체는 신호를 차단하고 반사해요. 금속 마감재 근처에는 무선 기기 위치를 조심해요."}],"walk":{"head":{"b":[0.0681,0.1116,0.6738,0.0713],"c":[0.0344,0.0956,0.7412,0.1033],"r":10.1474,"img":"img/I1/walk/p028_h.jpg"},"parts":[{"b":[0.077,0.194,0.849,0.077],"c":[0.0345,0.1382,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p028_30_01.jpg","say":"정의: 공간 구조와 거주자 동선을 분석해 센서의 감지 사각지대를 제거하고, 공간 디자인 관점에서 기기의 최적 위치를 설계하는 단계"},{"b":[0.093,0.301,0.4,0.04],"c":[0.073,0.266,0.44,0.11],"r":5.6569,"img":"img/I1/walk/p028_30_02.jpg","say":"2-1: 지능형홈 기기 구성 원리 및 평면도 분석 기초"},{"b":[0.093,0.362,0.529,0.04],"c":[0.0665,0.3232,0.5819,0.1176],"r":6.9978,"img":"img/I1/walk/p028_30_03.jpg","say":"2-2: 공간별(거실, 침실, 욕실) 감지 센서(PIR/mmWave) 최적 배치"},{"b":[0.093,0.422,0.429,0.04],"c":[0.0716,0.387,0.4719,0.11],"r":6.0671,"img":"img/I1/walk/p028_30_04.jpg","say":"2-3: 지능형홈 기기 구성과 인테리어 마감재 연동 시공"}]}},{"p":29,"title":"1.3.4 [L3] 연결 및 네트워크 계층 (Connectivity, Network Layer)","terms":["Connectivity, Network Layer","Zigbee","Thread","Matter","Channel Interference","2.4 GHz Band","Access Point","Mesh Network","Commissioning","Home Hub"],"pass1":[{"kind":"say","lines":["3층은 연결이에요. 기기끼리 끊기지 않고 이야기하게 무선을 잇는 층이에요."]},{"kind":"analogy","head":"메시 네트워크는 친구끼리 쪽지 릴레이","scene":"교실 맨 앞에서 맨 뒤까지 쪽지를 보내고 싶어요. 한 번에 던지면 중간에 떨어져요. 옆 친구, 그 옆 친구에게 차례로 건네면 끝자리까지 닿아요. 한 친구가 자리를 비워도 다른 친구를 거쳐 돌아가면 돼요.","map":[["쪽지를 건네는 친구들","신호를 이어 주는 기기들"],["차례로 건네기","메시 네트워크"],["다른 친구로 돌아가기","끊겨도 다른 길로 연결"]]},{"kind":"analogy","head":"주파수 대역은 라디오 채널","scene":"라디오에서 두 방송국이 같은 채널을 쓰면 소리가 섞여 둘 다 안 들려요. 채널을 조금 비켜 맞추면 각자 또렷해져요. 집 안 무선도 같은 채널에 몰리면 서로 방해해요.","map":[["라디오 채널","주파수 대역"],["소리가 섞임","채널 간섭"],["채널 비켜 맞추기","간섭이 적은 채널로 조정"]]}],"pass2":[{"kind":"points","head":"이 층 용어 (1)","items":["**Zigbee(지그비)**: 전기를 조금 먹고 센서끼리 손잡고 연결하는 무선이에요.","**Thread(스레드)**: Matter 기기들이 쓰는 저전력 무선 그물망이에요.","**Matter(매터)**: 회사가 달라도 기기끼리 말이 통하게 하는 공통 약속이에요.","**채널 간섭(Channel Interference)**: 같은 길을 쓰는 무선끼리 부딪혀 말이 안 들리는 거예요."]},{"kind":"points","head":"이 층 용어 (2)","items":["**2.4GHz 대역(2.4 GHz Band)**: Wi-Fi와 Zigbee가 함께 쓰는 붐비는 라디오 채널 묶음이에요.","**AP(Access Point)**: 무선 인터넷을 뿌려 주는 기지국 상자예요.","**메시 네트워크(Mesh Network)**: 기기들이 서로 신호를 이어 주는 그물망이에요.","**커미셔닝(Commissioning)**: 새 기기를 우리 집 시스템에 정식 등록하는 절차예요. **홈 허브(Home Hub)**에 연결할 때 해요."]},{"kind":"check","q":"'커미셔닝(Commissioning)'의 뜻은?","choices":["새 기기를 허브나 플랫폼에 등록해 제어 관계를 만드는 절차","전선을 벽에 묻는 공사","센서 감지 각도 조정","전기 요금 계산"],"a":0,"why":"Matter 표준에서 쓰는 말이에요. Zigbee에서는 같은 절차를 페어링이라고 불러요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"정확히 알아 둘 것","items":["**Zigbee(지그비)**는 IEEE 802.15.4 표준 기반 저전력 메시 기술이에요. 코디네이터, 라우터, 엔드 디바이스로 이뤄져요.","**Thread(스레드)**는 IPv6 기반 저전력 메시이고, Zigbee처럼 IEEE 802.15.4 기반이에요.","**Matter(매터)**는 제조사와 상관없이 상호운용성을 주는 IP 기반 개방형 연결 표준이에요.","강의 계획에서 L3는 3, 4주차(허브 연결, 무선 간섭 진단)예요."]},{"kind":"bg","src":"기초 다지기 4, 6단원","lines":["주파수는 전파가 1초에 몇 번 떨리는지예요. 단위 Hz, GHz는 10억 Hz예요.","같은 주파수 근처를 여러 기기가 쓰면 신호가 겹쳐 품질이 떨어져요.","메시는 여러 노드가 그물처럼 서로 연결된 모양이에요."]}],"pass4":[{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 25번","q":"Wi-Fi가 활발한 곳에서 Zigbee 기기가 자주 끊긴다. 간섭을 줄이는 조치로 알맞은 것은? (① Zigbee 출력 항상 최대 ② Zigbee를 AP 바로 옆에 설치 ③ Zigbee를 없애고 유선 LAN만 ④ 간섭이 적은 채널로 조정)","qko":"Wi-Fi와 Zigbee가 서로 방해할 때 올바른 해결책을 고르는 문제예요.","solve":["Wi-Fi와 Zigbee는 둘 다 **2.4GHz 대역(2.4 GHz Band)**을 써서 채널이 겹치면 **채널 간섭(Channel Interference)**이 생겨요.","라디오 채널 비유처럼 겹치지 않는 채널로 비켜 맞추면 돼요.","출력만 올리거나 AP 옆에 두면 간섭이 더 심해질 수 있고, 모두 없애는 건 해결이 아니에요."],"answer":"④ 간섭이 적은 채널로 조정한다"},{"kind":"exam","src":"2026 정기 제3회 지능형홈관리사 필기 36번","q":"서로 다른 통신 방식 기기를 연동하려고 허브나 게이트웨이를 둔다. 역할로 가장 적절하지 않은 것은? (① 연결 중계 ② 상태 정보 수집, 전달 ③ 제어 명령 전달 ④ 모든 기기의 통신 규격, 기능을 자동으로 동일하게 변경)","qko":"허브가 할 수 없는 일을 고르는 문제예요.","solve":["**홈 허브(Home Hub)**는 반장처럼 신호를 모으고 전하고, 통역사처럼 서로 다른 통신을 번역해요.","하지만 기기 자체의 통신 규격을 바꾸지는 못해요. Zigbee 기기는 여전히 Zigbee로 통신해요.","그래서 ④가 틀렸어요."],"answer":"④ 연결된 모든 기기의 통신 규격과 기능을 자동으로 동일하게 변경한다"},{"kind":"check","q":"Thread의 특징이 아닌 것은? (2026 제3회 23번 복습)","choices":["VPN 기반 암호화 무선 통신 기술","IPv6 기반","저전력 메시 네트워크","IEEE 802.15.4 기반"],"a":0,"why":"VPN은 인터넷 위의 암호화 터널 기술이에요. Thread 설명이 아니에요."}],"pass5":[{"kind":"points","head":"실기 가이드북 2권, 1-2 지능형홈 네트워크 설계 및 구성: Zigbee 네트워크","items":["**Zigbee(지그비)**는 코디네이터, 라우터, 엔드 디바이스로 이뤄져요.","코디네이터는 같은 Zigbee 네트워크를 묶고 유무선 공유기와도 연결해서, 판매할 때 'Zigbee 허브', 'Zigbee 게이트웨이'라고 불러요.","라우터는 신호를 강하게 이어 줘서 'Zigbee 리피터'라고도 불러요. 예) Zigbee 스마트플러그(Zigbee router)","누수 센서, 도어 센서, 스마트 버튼 같은 배터리형 기기는 엔드 디바이스예요."]},{"kind":"points","head":"Wi-Fi 네트워크 세 단계 (같은 장)","items":["1. 네트워크 생성: 인터넷에 연결된 Wi-Fi 공유기가 Wi-Fi 네트워크를 만들어요.","2. 네트워크 확장: Wi-Fi 리피터로 신호 세기를 넓혀요.","3. 네트워크 참여: Wi-Fi 기기가 그 네트워크에 들어와요."]},{"kind":"check","q":"실기 가이드북 문항에서 Zigbee **메시 네트워크(Mesh Network)** 확장을 위해 도면에 배치해야 할 기기로 정답이 된 것은?","choices":["Zigbee 스마트플러그(Zigbee router)","Zigbee 도어센서(End device)","Zigbee 누수센서(Battery type)","AI 스피커"],"a":0,"why":"라우터 역할을 하는 상시 전원 기기가 신호를 중계해 네트워크를 넓혀요."}],"walk":{"head":{"b":[0.0681,0.1116,0.7623,0.0713],"c":[0.03,0.0956,0.8385,0.1033],"r":11.4795,"img":"img/I1/walk/p029_h.jpg"},"parts":[{"b":[0.077,0.194,0.849,0.077],"c":[0.0345,0.1382,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p029_30_01.jpg","say":"정의: 기기 간 끊김 없는 소통을 위해 무선 네트워크 인프라를 구축하고, 신호 간섭을 회피해 통신 신뢰성을 확보하는 단계"},{"b":[0.093,0.301,0.418,0.04],"c":[0.0721,0.266,0.4598,0.11],"r":5.9115,"img":"img/I1/walk/p029_30_02.jpg","say":"3-1: 통신 프로토콜 이해(Zigbee, Thread, Matter)"},{"b":[0.093,0.362,0.389,0.04],"c":[0.0735,0.327,0.4279,0.11],"r":5.5014,"img":"img/I1/walk/p029_30_03.jpg","say":"3-2: 무선 채널 간섭 분석 및 2.4GHz 대역 최적화"},{"b":[0.093,0.422,0.425,0.04],"c":[0.0718,0.387,0.4675,0.11],"r":6.0105,"img":"img/I1/walk/p029_30_04.jpg","say":"3-3: AP 배치와 메시 네트워크(Mesh Network) 구성"},{"b":[0.093,0.483,0.375,0.04],"c":[0.0742,0.448,0.4125,0.11],"r":5.3034,"img":"img/I1/walk/p029_30_05.jpg","say":"3-4: 지능형홈 허브 연결 설정 및 커미셔닝 실습"}]}},{"p":30,"title":"1.3.5 [L4] 지능 및 자동화 계층 (Intelligence, AI Layer)","terms":["Intelligence, AI Layer","AI Stack","AI Cognitive Loop","Automation Scenario","Trigger","Sensor","Actuator"],"pass1":[{"kind":"say","lines":["꼭대기 4층은 두뇌예요.","사는 사람이 매일 어떻게 지내는지 배우고, 지금 상황에 맞게 집을 알아서 맞춰요."]},{"kind":"points","head":"4층이 다루는 두 묶음","items":["실제 자동화 만들기: 넘어짐 알아채기, 외출하면 전기 아끼기, 공기가 탁하면 환기","두뇌 설계: 인공지능 기술을 어떻게 쌓아 집과 더 넓은 공간에 쓸지"]}],"pass2":[{"kind":"compare","head":"두 모듈","cols":["모듈","무엇","연결되는 가치"],"rows":[["자동화 실무 모듈","4-1 재실 기반 낙상 감지, 4-2 외출 감지 기반 절전, 4-3 공기질 기반 환기","안전, 절감, 쾌적"],["**AI 스택(AI Stack)** 설계 모듈","4-4 AI 기술 체계와 인지 루프, 4-5 주거 공간, 4-6 확장 공간","공간에 맞는 AI 기술 조합"]]},{"kind":"points","head":"이 층 용어","items":["**AI 스택(AI Stack)**: AI가 일하는 데 필요한 기술을 층층이 쌓은 묶음이에요.","**AI 인지 루프(AI Cognitive Loop)**: **센서(Sensor)**가 보고, AI가 판단하고, **액추에이터(Actuator)**가 움직이는 반복이에요.","**자동화 시나리오(Automation Scenario)**: 낙상, 외출, 공기질 같은 상황마다 정해 둔 자동 행동이에요."]},{"kind":"check","q":"\"외출 감지 기반 절전\" 자동화는 4대 가치 중 무엇과 가장 가까울까요?","choices":["절감","편의","안전","쾌적"],"a":0,"why":"사람이 없을 때 전기를 끊는 일이라 절감(Saving)이에요. 낙상 감지는 안전, 공기질 환기는 쾌적이에요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"앞쪽과 이어 보기","items":["4-1 낙상 감지: 21쪽 안전 가치의 '비식별 프라이버시(레이더로 낙상 감지)'와 같은 장면이에요.","4-2 외출 절전: 22쪽 절감 가치의 '자율 전력 회수'와 이어져요.","4-3 공기질 환기: 22쪽 쾌적 가치의 'CO2 상승 시 ERV 가동'과 이어져요. CO2 값이 **트리거(Trigger)**예요.","강의 계획에서 L4는 6, 9, 12주차(AI 기술 I, II, III)예요. 33쪽 표에는 6, 9주차로 적혀 있어요."]}],"pass4":[{"kind":"check","q":"L4 'AI 스택 설계 모듈'에 속하지 않는 것은?","choices":["4-3 공기질 기반 환기","4-4 AI 기술 체계 이해 및 인지 루프","4-5 AI 스택 설계(주거 공간)","4-6 AI 스택 설계(확장 공간)"],"a":0,"why":"4-1~4-3은 자동화 실무 모듈, 4-4~4-6이 AI 스택 설계 모듈이에요."},{"kind":"warn","head":"헷갈리는 점","items":["'생활 패턴을 학습하여 AI가 자동 판단, 제어'는 L4 정의예요. L3(통신)과 섞지 않아요.","4-4의 '인지 루프'는 2주차 1-Loop 주제로 이어져요."]}],"pass5":[{"kind":"steps","head":"실기 가이드북 2권, 1-1 #5 자동화 동작 구성도 문항","steps":["목표: \"어두울 때 모션 센서가 감지되면 불을 켜고, 동작이 감지되지 않으면 30초 뒤 불을 꺼라\"","3단계 틀: **트리거(Trigger)**(시작조건) → 조건(조건만족) → 동작","자동화 1: 시작조건 모션이 감지될 때 / 조건만족 어두우면 / 동작 불이 켜진다","자동화 2: 시작조건 모션이 감지되지 않을 때 / 조건만족 없음 / 동작 불이 꺼진다"],"answer":"켜기와 끄기는 시작조건이 달라서 자동화 두 개로 나눠요."},{"kind":"check","q":"위 문항에서 '어두우면'은 자동화 3단계 중 어디에 들어가나요?","choices":["조건만족","시작조건","동작","들어가지 않음"],"a":0,"why":"출발 신호는 모션 감지이고, '어두우면'은 추가로 맞아야 하는 조건이에요."}],"walk":{"head":{"b":[0.0681,0.1116,0.6412,0.0713],"c":[0.036,0.0956,0.7053,0.1033],"r":9.6559,"img":"img/I1/walk/p030_h.jpg"},"parts":[{"b":[0.077,0.194,0.849,0.072],"c":[0.0345,0.1357,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p030_30_01.jpg","say":"정의: 거주자 생활 패턴을 학습해 상황에 맞는 최적의 환경을 AI가 자동으로 판단하고 제어하는 최상위 지능 단계"},{"b":[0.077,0.283,0.419,0.227],"c":[0.056,0.267,0.4609,0.259],"r":2.5167,"img":"img/I1/walk/p030_30_02.jpg","say":"자동화 실무 모듈: 4-1 [자동화] 재실 기반 낙상 감지, 4-2 [자동화] 외출 감지 기반 절전, 4-3 [자동화] 공기질 기반 환기"},{"b":[0.506,0.283,0.42,0.227],"c":[0.485,0.267,0.462,0.259],"r":2.5227,"img":"img/I1/walk/p030_30_03.jpg","say":"AI 스택 설계 모듈: 4-4 AI 기술 체계 이해 및 인지 루프, 4-5 AI 스택 설계(주거 공간), 4-6 AI 스택 설계(확장 공간)"}]}},{"p":31,"title":"1.3.6 기반-제어 관계 (Foundation-Control Relationship)","terms":["Foundation-Control Relationship","Electrical, Infrastructure Layer","Spatial, Interior Layer","Connectivity, Network Layer","Intelligence, AI Layer","Architect","Neutral Line"],"pass1":[{"kind":"analogy","head":"꼭대기 사무실과 아래층 설비","scene":"건물 꼭대기 사무실에서 '에어컨 켜' 하고 지시해요. 이 지시가 통하려면 아래층 전기실과 배관이 멀쩡해야 해요. 아래층은 위층을 떠받치고, 위층은 아래층 설비를 움직여요. 그런데 인테리어가 끝난 뒤 벽 속 전선을 바꾸려면 벽을 뜯어야 해요.","map":[["아래층 전기실, 배관","아래 계층의 물리적 기반"],["꼭대기 사무실의 지시","위 계층 AI의 제어"],["벽을 뜯는 공사","준공 뒤 물리 인프라 수정의 어려움"]]},{"kind":"figure","head":"받쳐 주고, 조종하고","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><rect class=\"n2\" x=\"140\" y=\"15\" width=\"200\" height=\"44\" rx=\"2\"/><text class=\"tl\" x=\"240\" y=\"43\" font-size=\"16\" text-anchor=\"middle\">위층: AI 판단<\/text><rect class=\"n3\" x=\"140\" y=\"205\" width=\"200\" height=\"44\" rx=\"2\"/><text class=\"tl\" x=\"240\" y=\"233\" font-size=\"16\" text-anchor=\"middle\">아래층: 전기, 공간, 무선<\/text><line class=\"e2 b2\" x1=\"110\" y1=\"205\" x2=\"110\" y2=\"70\"/><polygon class=\"arrow b2\" points=\"103,74 110,60 117,74\"/><text class=\"tb b2\" x=\"95\" y=\"130\" font-size=\"15\" text-anchor=\"end\">받쳐 줌<\/text><text class=\"tm b2\" x=\"95\" y=\"152\" font-size=\"14\" text-anchor=\"end\">기반 제공<\/text><line class=\"e2 b3\" x1=\"370\" y1=\"60\" x2=\"370\" y2=\"195\"/><polygon class=\"arrow b3\" points=\"363,191 370,205 377,191\"/><text class=\"tb b3\" x=\"385\" y=\"130\" font-size=\"15\">조종함<\/text><text class=\"tm b3\" x=\"385\" y=\"152\" font-size=\"14\">제어 작용<\/text><\/svg>","caption":"아래층은 위로 기반을 주고, 위층은 아래로 제어를 내려요.","builds":3}],"pass2":[{"kind":"compare","head":"두 방향","cols":["방향","이름","뜻"],"rows":[["아래 → 위","상향 작용(Upward), 기반 제공(Foundation)","AI는 튼튼한 전기, 공간, 네트워크 위에서만 제대로 돌아가요"],["위 → 아래","하향 작용(Downward), 제어 작용(Control)","AI의 판단이 아래 기기 제어, 전력 조절로 이어져 공간 상태를 바꿔요"]]},{"kind":"points","head":"그래서 설계 순서가 정해져요","items":["소프트웨어(앱 설정, 자동화 로직)는 나중에 업데이트로 언제든 고칠 수 있어요.","벽 속 **중성선(Neutral Line)**, 센서 배선은 준공 뒤 고치려면 크게 뜯어야 해요.","그러니 고치기 비싼 아래층부터 먼저 확실히 검증해요. 이 관계가 **기반-제어 관계(Foundation-Control Relationship)**예요."]},{"kind":"check","q":"'기반-제어 관계(Foundation-Control Relationship)'에서 상향 작용은?","choices":["아래 계층이 위 계층에 물리적 작동 기반을 주는 것","위 계층이 아래 설비를 제어하는 것","앱을 업데이트하는 것","센서를 빼는 것"],"a":0,"why":"위로(Upward) 향하는 것은 기반 제공(Foundation)이에요. 아래로(Downward)는 제어(Control)예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"compare","head":"고치기 쉬운 층, 어려운 층","cols":["구분","층","고치는 방법"],"rows":[["상위 제어의 유연성","**L4 지능 및 자동화 계층(Intelligence, AI Layer)**","소프트웨어 업데이트로 언제든"],["물리 마감의 고정성","**L1 전기 및 인프라 계층(Electrical, Infrastructure Layer)**, **L2 공간 및 기기 배치 계층(Spatial, Interior Layer)**","준공 뒤엔 대규모 철거 공사"]]}],"pass4":[{"kind":"english","head":"답안 문장: 34쪽 Q2","en":"하부 계층(L1, L2)은 상부에 물리적 작동 기반을 제공하고 상부 계층(L4)은 하부를 제어해 공간 상태를 바꾸는 양방향 수직 의존 체계를 기반-제어 관계라고 한다.","ko":"기반(아래 → 위), 제어(위 → 아래) 두 방향을 모두 써야 해요.","tip":"'밑은 받치고, 위는 부린다'."},{"kind":"check","q":"Architect 설계 지침에 맞는 순서는?","choices":["하부 물리 기반을 먼저 검증, 확보한 뒤 상위 제어를 얹는다","AI 자동화부터 만들고 전선은 나중에 맞춘다","앱 설정을 먼저 확정하고 벽을 마감한다","센서 배선은 준공 뒤에 한다"],"a":0,"why":"물리 인프라는 준공 뒤 고치기 어려워서 먼저 검증해요."},{"kind":"warn","head":"방향을 뒤바꾸기 쉬워요","items":["상향 작용(Upward) = 기반 제공(Foundation), 하향 작용(Downward) = 제어 작용(Control)이에요.","유연한 쪽은 L4(소프트웨어), 고정된 쪽은 L1, L2(물리 마감)예요."]}],"pass5":[{"kind":"points","head":"실기 가이드북 2권, 2-1 스마트 릴레이 스위치 설치 위치 문항","items":["스마트 릴레이 스위치도 상시 전원이 필요해서, **중성선(Neutral Line)**이 있고 전등을 직접 제어하는 위치에 설치해야 해요.","기존 스위치의 활선(Live)과 부하선(Load)만 있는 자리는 중성선이 없어서 설치할 수 없어요.","접지선과 중성선만 있는 자리는 전등 제어가 안 돼요.","벽 속에 중성선이 없으면 나중에 AI(L4)로 해결할 수 없어요. 물리 마감의 고정성을 보여 주는 사례예요."]}],"walk":{"head":{"b":[0.0681,0.1116,0.6785,0.0713],"c":[0.0342,0.0956,0.7463,0.1033],"r":10.2172,"img":"img/I1/walk/p031_h.jpg"},"parts":[{"b":[0.077,0.196,0.849,0.123],"c":[0.0345,0.1632,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p031_30_01.jpg","say":"정의: 하부 계층이 상부 계층에게 물리적인 작동 기반(Foundation)을 제공하고, 반대로 상부 계층은 하부 설비를 제어(Control)하여 공간 상태를 변화시키는 양방향 수직 의존 체계"},{"b":[0.077,0.334,0.417,0.161],"c":[0.0561,0.318,0.4587,0.193],"r":3.3612,"img":"img/I1/walk/p031_30_02.jpg","say":"상향 작용(Upward), 기반 제공(Foundation): 상위 AI(L4)는 단단한 L1 전기, L2 공간, L3 네트워크 인프라 기반 위에서 정상 구동 가능"},{"b":[0.508,0.334,0.418,0.161],"c":[0.4871,0.318,0.4598,0.193],"r":3.3692,"img":"img/I1/walk/p031_30_03.jpg","say":"하향 작용(Downward), 제어 작용(Control): 상위 AI의 판단 결과는 하부 기기 제어 및 전력 공급 조절로 이어져 공간 상태를 변경"},{"b":[0.107,0.612,0.704,0.042],"c":[0.0718,0.5548,0.7744,0.1565],"r":6.998,"img":"img/I1/walk/p031_30_04.jpg","say":"① Architect의 설계 지침: \"수정 비용이 큰 하부 물리 기반부터 철저히 선행 검증하고 확보한 뒤, 상위 제어를 얹는다.\""},{"b":[0.107,0.657,0.607,0.036],"c":[0.0766,0.6076,0.6677,0.1349],"r":6.9999,"img":"img/I1/walk/p031_30_05.jpg","say":"② 상위 제어의 유연성(L4): AI 자동화 로직이나 앱 설정은 소프트웨어 업데이트로 언제든지 수정 가능"},{"b":[0.107,0.697,0.654,0.037],"c":[0.0743,0.6428,0.7194,0.1453],"r":7.002,"img":"img/I1/walk/p031_30_06.jpg","say":"③ 물리 마감의 고정성(L1, L2): 벽체 매립 중성선이나 센서 배선은 준공 후 수정 시 대규모 철거 공사가 수반됨"}]}},{"p":32,"title":"1.3.7 공간 전문가의 정체성: 오케스트라의 지휘자","terms":["Architect","기술 시공자","4-Layer Architecture","User Experience"],"pass1":[{"kind":"analogy","head":"악보를 든 지휘자","scene":"오케스트라 지휘자는 악기를 직접 연주하지 않아요. 대신 악보를 보고 바이올린은 언제 들어오고 드럼은 얼마나 크게 칠지 맞춰요. 연주자들은 저마다 제 악기를 잘 다뤄요. 지휘자가 있어야 그 소리가 한 곡이 돼요.","map":[["악보","사는 사람이 느낄 경험 목표"],["연주자","전기, 통신, AI를 직접 만드는 기술 시공자"],["지휘자","지능형 공간 Architect"]]},{"kind":"say","lines":["여러분의 자리는 지휘자, 곧 **지능형 공간 Architect**예요."]}],"pass2":[{"kind":"compare","head":"단순 구현자와 통합 기획자","cols":["구분","**기술 시공자**","**지능형 공간 Architect**"],"rows":[["다른 이름","단순 구현자","통합 기획자, 공간 지휘자"],["하는 일","전기 배선, 통신 개통, AI 알고리즘 개발 같은 한 기술을 손으로 구현","네 층 기술을 모아 조율"],["기준","자기 기술","**거주자 경험(User Experience)**이라는 악보"]]},{"kind":"check","q":"'기술 시공자'가 하는 일로 알맞은 것은?","choices":["전기 배선, 통신 개통처럼 개별 기술을 직접 구현","4-Layer를 도면에서 총괄 조율","거주자 UX 목표를 세우기","4대 가치를 정의하기"],"a":0,"why":"기술 시공자는 한 기술을 손으로 만드는 사람이에요. 조율은 **지능형 공간 Architect**의 일이에요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"14쪽과 이어 보기","items":["14쪽에서 통신사, 건설사, 제조사, 인테리어 BM 사이의 빈칸을 봤어요.","그 빈칸이 바로 **4-Layer 적층구조(4-Layer Architecture)** 전체를 조율하는 지휘자 자리예요.","UX 악보: **거주자 경험(User Experience)** 목표가 모든 기술 결정의 기준이라는 뜻이에요."]}],"pass4":[{"kind":"english","head":"답안 문장: 34쪽 Q3","en":"지능형 공간 Architect는 개별 기술을 수동 구현하는 기술 시공자와 달리, 거주자 UX 목표를 바탕으로 4-Layer 기술 요소들을 도면 위에서 총괄 지휘하고 조율하는 오케스트라의 지휘자이다.","ko":"비교 대상(기술 시공자), 기준(UX), 대상(4-Layer), 장소(도면 위), 역할(지휘, 조율)을 넣어요.","tip":"'악보는 UX, 악기는 4-Layer, 무대는 도면'."},{"kind":"check","q":"Architect가 기술을 조율할 때 '악보'로 삼는 것은?","choices":["거주자 UX","제조사 카탈로그","통신사 요금표","건설사 최저가 입찰서"],"a":0,"why":"거주자 경험(UX) 악보를 바탕으로 4-Layer를 총괄 조율해요."}],"pass5":[],"walk":{"head":{"b":[0.0681,0.1116,0.5658,0.0666],"c":[0.0398,0.0956,0.6223,0.0986],"r":8.9257,"img":"img/I1/walk/p032_h.jpg"},"parts":[{"b":[0.077,0.194,0.414,0.196],"c":[0.0563,0.178,0.4554,0.228],"r":2.8247,"img":"img/I1/walk/p032_30_01.jpg","say":"단순 구현자, 기술 시공자: 전기 배선, 통신 개통, AI 알고리즘 개발 등 개별 기술 수동 구현에 집중"},{"b":[0.511,0.194,0.415,0.196],"c":[0.4903,0.178,0.4565,0.228],"r":2.8316,"img":"img/I1/walk/p032_30_02.jpg","say":"통합 기획자(Architect), 공간 지휘자: 거주자 UX 악보를 바탕으로 4-Layer 기술 요소를 총괄 통합 및 조율"},{"b":[0.077,0.406,0.849,0.408],"c":[0.0345,0.3856,0.9339,0.4488],"r":2.9428,"img":"img/I1/walk/p032_30_03.jpg","say":"그림이 깨져 제목만 보여요: '구스타보 두다멜 오케스트라 지휘'. 유명 지휘자 사진으로 비유를 보여 주려던 자리예요."}]}},{"p":33,"title":"1.3.8 실무 구축 vs 커리큘럼 학습의 대칭 구조","terms":["Bottom-Up","Electrical, Infrastructure Layer","Spatial, Interior Layer","Connectivity, Network Layer","Intelligence, AI Layer","Switching Mode Power Supply","4-Layer Architecture"],"pass1":[{"kind":"say","lines":["집을 실제로 지을 때는 아래층부터 올려요. 전기, 공간, 연결, 지능 순서예요.","그런데 수업은 이해하기 쉬운 순서로 배워요. 연결, 공간, 지능, 전기 순서예요."]},{"kind":"figure","head":"짓는 순서와 배우는 순서","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text class=\"tb\" x=\"10\" y=\"40\" font-size=\"16\">현장에서 짓는 순서<\/text><rect class=\"n3\" x=\"10\" y=\"55\" width=\"100\" height=\"40\" rx=\"2\"/><text class=\"tl\" x=\"60\" y=\"81\" font-size=\"15\" text-anchor=\"middle\">전기<\/text><rect class=\"n3\" x=\"130\" y=\"55\" width=\"100\" height=\"40\" rx=\"2\"/><text class=\"tl\" x=\"180\" y=\"81\" font-size=\"15\" text-anchor=\"middle\">공간<\/text><rect class=\"n3\" x=\"250\" y=\"55\" width=\"100\" height=\"40\" rx=\"2\"/><text class=\"tl\" x=\"300\" y=\"81\" font-size=\"15\" text-anchor=\"middle\">연결<\/text><rect class=\"n3\" x=\"370\" y=\"55\" width=\"100\" height=\"40\" rx=\"2\"/><text class=\"tl\" x=\"420\" y=\"81\" font-size=\"15\" text-anchor=\"middle\">지능<\/text><text class=\"tb b2\" x=\"10\" y=\"160\" font-size=\"16\">수업에서 배우는 순서<\/text><rect class=\"n2 b2\" x=\"10\" y=\"175\" width=\"100\" height=\"40\" rx=\"2\"/><text class=\"tl b2\" x=\"60\" y=\"201\" font-size=\"15\" text-anchor=\"middle\">연결<\/text><rect class=\"n2 b2\" x=\"130\" y=\"175\" width=\"100\" height=\"40\" rx=\"2\"/><text class=\"tl b2\" x=\"180\" y=\"201\" font-size=\"15\" text-anchor=\"middle\">공간<\/text><rect class=\"n2 b2\" x=\"250\" y=\"175\" width=\"100\" height=\"40\" rx=\"2\"/><text class=\"tl b2\" x=\"300\" y=\"201\" font-size=\"15\" text-anchor=\"middle\">지능<\/text><rect class=\"n2 b2\" x=\"370\" y=\"175\" width=\"100\" height=\"40\" rx=\"2\"/><text class=\"tl b2\" x=\"420\" y=\"201\" font-size=\"15\" text-anchor=\"middle\">전기<\/text><text class=\"tm b2\" x=\"240\" y=\"250\" font-size=\"14\" text-anchor=\"middle\">왼쪽에서 오른쪽으로 진행<\/text><\/svg>","caption":"위는 현장 순서, 아래는 수업 순서예요.","builds":2}],"pass2":[{"kind":"compare","head":"두 순서","cols":["구분","순서","왜"],"rows":[["현장 실무 구축(**Bottom-Up**)","L1 전기 인프라 → L2 기기 배치 → L3 통신 → L4 AI 자동화","아래층이 위층을 받치니까 아래부터 지어요"],["본 과목 학습(학습 접근성 순)","L3 무선통신 → L2 공간 센서 → L4 AI 인지 → L1 전기 기초","처음 배우는 사람이 다가가기 쉬운 순서예요"]]},{"kind":"points","head":"용어","items":["**Bottom-Up**: 바닥(Bottom)부터 위(Up)로 쌓는다는 뜻이에요. 집은 아래층부터 지어요.","학습 접근성: 배우는 사람이 얼마나 쉽게 다가갈 수 있는지예요."]},{"kind":"check","q":"현장 실무 구축 순서(Bottom-Up)로 맞는 것은?","choices":["L1 → L2 → L3 → L4","L3 → L2 → L4 → L1","L4 → L3 → L2 → L1","L2 → L1 → L4 → L3"],"a":0,"why":"**Bottom-Up**은 L1 전기 인프라부터 L4 AI 자동화까지 아래에서 위로예요."}],"pass3":[{"kind":"look","walked":1},{"kind":"compare","head":"4-Layer × 실습 주차","cols":["층","주차","실습 내용"],"rows":[["**L4 지능 및 자동화 계층(Intelligence, AI Layer)**","6, 9주차","낙상 감지, 외출 절전 자동화"],["**L3 연결 및 네트워크 계층(Connectivity, Network Layer)**","3, 4주차","허브 연결, 무선 간섭 진단"],["**L2 공간 및 기기 배치 계층(Spatial, Interior Layer)**","5, 14주차","센서 화각, 음영 지역 배치"],["**L1 전기 및 인프라 계층(Electrical, Infrastructure Layer)**","13주차","**SMPS(Switching Mode Power Supply)** 용량 산정, 배선 설계"]]}],"pass4":[{"kind":"check","q":"이 과목에서 가장 먼저 배우는 층은?","choices":["L3 무선통신","L1 전기 기초","L4 AI 인지","L2 공간 센서"],"a":0,"why":"학습 접근성 순서는 L3 → L2 → L4 → L1이에요. 그래서 3, 4주차가 무선통신이에요."},{"kind":"check","q":"SMPS 용량 산정과 배선 설계를 실습하는 주차는?","choices":["13주차","3주차","6주차","14주차"],"a":0,"why":"L1은 13주차예요."},{"kind":"warn","head":"세 가지 순서를 섞지 않아요","items":["**Bottom-Up**(현장에서 짓는 순서): L1 → L2 → L3 → L4","수업 학습 순서: L3 → L2 → L4 → L1","R-BD(설계를 생각하는 순서): 경험 목표 → 필요 데이터 → 기술 사양 → 물리 검증"]}],"pass5":[],"walk":{"head":{"b":[0.0681,0.1116,0.5042,0.0666],"c":[0.0429,0.0956,0.5547,0.0986],"r":7.9561,"img":"img/I1/walk/p033_h.jpg"},"parts":[{"b":[0.077,0.194,0.416,0.112],"c":[0.0562,0.178,0.4576,0.144],"r":4.4941,"img":"img/I1/walk/p033_30_01.jpg","say":"현장 실무 구축 순서(Bottom-Up): L1 전기 인프라 → L2 기기 배치 → L3 통신 → L4 AI 자동화"},{"b":[0.509,0.194,0.417,0.112],"c":[0.4882,0.178,0.4587,0.144],"r":4.5049,"img":"img/I1/walk/p033_30_02.jpg","say":"본 과목 학습 순서(학습 접근성 순): L3 무선통신 → L2 공간 센서 → L4 AI 인지 → L1 전기 기초"},{"b":[0.093,0.399,0.5,0.033],"c":[0.068,0.3599,0.55,0.1111],"r":7.0011,"img":"img/I1/walk/p033_30_03.jpg","say":"학습성과: 4-Layer 적층 구조에 따라 기술 요소별 의존 관계를 판별할 수 있어요."},{"b":[0.111,0.449,0.264,0.081],"c":[0.0978,0.433,0.2904,0.113],"r":3.6344,"img":"img/I1/walk/p033_30_04.jpg","say":"L4 6, 9주차: 낙상 감지, 외출 절전 자동화 / L3 3, 4주차: 허브 연결, 무선 간섭 진단"},{"b":[0.111,0.537,0.264,0.081],"c":[0.0978,0.521,0.2904,0.113],"r":3.6344,"img":"img/I1/walk/p033_30_05.jpg","say":"L2 5, 14주차: 센서 화각, 음영 지역 배치 / L1 13주차: SMPS 용량 산정, 배선 설계"}]}},{"p":34,"title":"1.3강 CHECKPOINT","terms":["Neutral Line","3-Wire Wiring","Flicker","Foundation-Control Relationship","Architect","Electrical, Infrastructure Layer"],"pass1":[{"kind":"say","lines":["1.3강 복습 문제 세 개예요. 답을 가리고 먼저 말해 봐요."]},{"kind":"recap","items":["똑똑한 스위치가 깜빡이지 않게 벽 속에 미리 깔아 둘 선: 전기가 돌아 나가는 선","아래층은 받치고 위층은 조종하는 사이: 기반과 제어의 관계","네 층 기술을 도면에서 지휘하는 사람: 지능형 공간 Architect"]}],"pass2":[{"kind":"points","head":"Q1에 나오는 새 용어","items":["**플리커(Flicker)**: 조명이 파르르 깜빡거리는 현상이에요.","**중성선(Neutral Line)**: 전기가 돌아 나가는 길이에요.","**3선식 배선(3-Wire Wiring)**: 들어오는 선, 중성선, 전등으로 가는 선이 다 있는 배선이에요.","상시 전원: 스위치를 꺼도 스마트 스위치 자체에는 늘 들어오는 전기예요."]},{"kind":"check","q":"'플리커(Flicker)'의 뜻은?","choices":["조명이 깜빡거리는 현상","전기가 새는 현상","센서가 못 보는 구석","무선 채널 겹침"],"a":0,"why":"전원이 불안정해 조명이 깜빡이는 현상이에요. 중성선 3선식 배선으로 막아요."}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"Q1을 더 정확히","items":["선행 배선: 벽을 마감하기 전에 미리 깔아 두는 배선이에요.","N선은 **중성선(Neutral Line)**의 약호예요. 강의에서는 Neutral Wire라고도 적어요.","이 일은 **L1 전기 및 인프라 계층(Electrical, Infrastructure Layer)** 1-3 '중성선(N선) 확보' 항목이에요."]}],"pass4":[{"kind":"english","head":"답안 문장: Q1","en":"스마트 스위치의 플리커 현상을 방지하고 안정적인 상시 전원을 공급하려면 L1 계층에서 중성선(N선, Neutral Wire)을 포함한 3선식 배선을 선행해야 한다.","ko":"문제(플리커), 목적(상시 전원), 해법(중성선 3선식), 시점(선행) 네 조각이에요.","tip":"'깜빡이면 N선, 그것도 미리'."},{"kind":"check","q":"Q1 상황에서 선행 배선을 하지 않고 준공했다면 어떻게 될까요? (31쪽 연결)","choices":["벽체 매립 중성선을 고치려면 대규모 철거 공사가 필요해요","앱 업데이트로 바로 해결돼요","AI가 스스로 전선을 만들어요","Zigbee 채널만 바꾸면 돼요"],"a":0,"why":"물리 마감의 고정성(L1, L2) 때문이에요. 그래서 선행 검증이 필요해요."},{"kind":"warn","head":"헷갈리는 점","items":["**플리커(Flicker)**(깜빡임)와 잔광 현상(꺼져도 희미한 빛)은 다른 현상이지만, 둘 다 중성선 3선식이 해법으로 나와요.","Q2 답은 '기반-제어 관계'예요. Bottom-Up이나 R-BD가 아니에요."]}],"pass5":[{"kind":"points","head":"실기 가이드북 2권, 2-1 스마트 스위치 결선","items":["활선(L)으로 스위치에 전기가 들어오고, 일부 전기는 **중성선(Neutral Line)**(N)으로 빠져나가요.","부하선(L1, L2, L3)으로 전등에 전기를 보내요. 스위치를 끄면 전등 쪽 전기가 다시 중성선으로 빠져나가요.","가이드북의 부하선 L1, L2, L3은 스위치 구 번호예요. 4-Layer의 L1과 이름만 같아요.","**3선식 배선(3-Wire Wiring)** 스위치는 공급, 차단이 100%와 0%라 잔광 현상이 없어요."]},{"kind":"check","q":"실기 가이드북 배선도에서 '중성선-N, 활선-Live, 부하선-L1/L2'로 된 스위치는?","choices":["3선식 2구 스위치","2선식 1구 스위치","3로 스위치","누전차단기"],"a":0,"why":"중성선이 있으니 3선식이고, 부하선이 L1, L2 두 개라 2구예요."}],"walk":{"head":{"b":[0.0681,0.1116,0.2708,0.0666],"c":[0.0545,0.0956,0.2978,0.0986],"r":4.2714,"img":"img/I1/walk/p034_h.jpg"},"parts":[{"b":[0.077,0.21,0.849,0.115],"c":[0.0345,0.1732,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p034_30_01.jpg","say":"Q1 스마트 스위치 설치 시 플리커를 막고 안정적인 상시 전원을 주려고 L1에서 요구되는 선행 배선은? 정답: 중성선(N선, Neutral Wire) 3선식 선행 배선"},{"b":[0.077,0.354,0.849,0.115],"c":[0.0345,0.3172,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p034_30_02.jpg","say":"Q2 상위 제어(L4)와 하부 인프라(L1, L2)의 관계는? 정답: 기반-제어 관계(하부는 상부에 물리적 기반 제공, 상부는 하부를 제어해 환경 변경)"},{"b":[0.077,0.497,0.849,0.114],"c":[0.0345,0.4597,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p034_30_03.jpg","say":"Q3 개별 시공자와 구별되는 지능형 공간 Architect의 역할은? 정답: 거주자 UX 목표로 4-Layer 기술 요소를 도면 위에서 총괄 지휘, 조율하는 오케스트라의 지휘자"}]}},{"p":35,"title":"다음 주 강의 예고","terms":["1-Loop","State Data","Event Data","Time-series Data","Non-identifying Sensing"],"pass1":[{"kind":"say","lines":["다음 주에는 집 안의 데이터가 어떻게 흘러가는지 배워요.","센서가 느낀 것이 어떤 길로 날라져 판단에 쓰이는지 따라가요.","오늘 배운 주문을 다시 떠올려 두세요. 센서가 느끼고, 네트워크가 나르고, 허브와 플랫폼이 판단하고, 기기가 움직여요."]}],"pass2":[{"kind":"points","head":"예고에 나온 용어 미리 보기","items":["**1-Loop**: 감지 → 전달 → 판단 → 실행이 한 바퀴 도는 고리예요.","**상태 데이터(State Data)**: 지금 켜져 있는지, 몇 도인지 같은 현재 상태예요.","**이벤트 데이터(Event Data)**: 문이 열렸다처럼 무슨 일이 일어난 순간의 기록이에요.","**시계열 데이터(Time-series Data)**: 시간 순서대로 쌓인 값이에요. 예) 한 시간마다 잰 온도","**비식별 센싱(Non-identifying Sensing)**: 누구인지 알아보지 않고 감지하는 방식이에요."]}],"pass3":[{"kind":"look","walked":1},{"kind":"points","head":"1강과 이어지는 곳","items":["**1-Loop**는 4쪽 학습목표의 'AI 인지 순환 체계(1-Loop)'예요.","**비식별 센싱(Non-identifying Sensing)**은 10쪽 AI@Home 정의의 '비식별 센서'와 21쪽 '비식별 프라이버시'로 이어져요.","**상태 데이터(State Data)**, **이벤트 데이터(Event Data)**, **시계열 데이터(Time-series Data)**는 센서가 모으는 데이터의 세 가지 모양이에요."]}],"pass4":[{"kind":"check","q":"2주차 예고에 나온 데이터 유형 세 가지는?","choices":["상태, 이벤트, 시계열","편의, 안전, 쾌적","유선, 무선, 메시","L1, L2, L3"],"a":0,"why":"상태 데이터(State Data), 이벤트 데이터(Event Data), 시계열 데이터(Time-series Data)예요. 1-Loop과 비식별 센싱도 함께 배워요."}],"pass5":[],"walk":{"head":{"b":[0.0685,0.1116,0.2019,0.0666],"c":[0.0565,0.0956,0.2259,0.0986],"r":3.2401,"img":"img/I1/walk/p035_h.jpg"},"parts":[{"b":[0.077,0.209,0.849,0.081],"c":[0.0345,0.1552,0.9339,0.1887],"r":6.9992,"img":"img/I1/walk/p035_30_01.jpg","say":"다음 주차 [2주차 예고]: 공간 데이터 흐름과 IoT 파이프라인(1-Loop, 상태, 이벤트, 시계열 데이터 및 비식별 센싱)"}]}}]};
